QCU_T("es", "procedimiento2", {
  "0": ["¿Cuál de estas propuestas describe mejor el funcionamiento del sistema nervioso central?",["Funciona en red, estando todo ligado en él","Funciona por zonas independientes y compartimentadas","Funciona según una jerarquía descendente sin retorno"],["Exacto: nada ocurre en una zona sin consecuencia en otra parte.","Falso: esta concepción modular estricta es precisamente la que el modelo en red supera.","Falso: los bucles de retorno son, al contrario, constantes."]],
  "1": ["¿Qué ventaja presenta una organización en red del sistema nervioso?",["Es ligera, rápida, potente y ahorradora de energía","Es pesada pero extremadamente estable a lo largo del tiempo","Es lenta pero perfectamente reproducible"],["Exacto: es además potente, compacta y flexible.","Falso: la ligereza y la flexibilidad forman parte de sus virtudes.","Falso: la rapidez es, al contrario, una de sus ventajas."]],
  "2": ["¿Qué distingue un neurotransmisor de un neuromodulador?",["El neurotransmisor produce cambios rápidos","El neurotransmisor produce cambios lentos","Ambos actúan exactamente a la misma velocidad"],["Exacto: el neuromodulador produce, al contrario, cambios lentos.","Falso: esa lentitud caracteriza al neuromodulador.","Falso: la diferencia de cinética es precisamente lo que los separa."]],
  "3": ["¿Qué proporción de su ADN comparten los seres humanos?",["Alrededor del noventa y nueve coma nueve por ciento del ADN","Alrededor del sesenta por ciento de su patrimonio","Alrededor del ochenta por ciento de su patrimonio"],["Exacto: la expresión del noventa y cinco por ciento de los genes puede, sin embargo, ser modificada por el entorno.","Falso: esa proporción es muy inferior a la realidad.","Falso: la parte común es mucho más elevada."]],
  "4": ["¿Qué proporción de los genes puede ver su expresión modificada por el entorno?",["Alrededor del noventa y cinco por ciento","Alrededor de solo el cinco por ciento","Alrededor del veinte por ciento como máximo"],["Exacto: es el fundamento de la epigenética aplicada a la rehabilitación.","Falso: esa estimación es muy inferior a la realidad.","Falso: la parte modificable es mucho más importante."]],
  "5": ["¿Por qué se dice que el cerebro es plástico y no elástico?",["Porque modifica duraderamente sus estructuras","Porque se extiende y luego vuelve a su forma inicial","Porque se deforma sin cambiar de función"],["Exacto: la elasticidad supondría un retorno al estado inicial, lo que no es el caso.","Falso: esa descripción es la de la elasticidad.","Falso: la plasticidad implica, al contrario, una reorganización funcional duradera, y no una simple deformación."]],
  "6": ["¿Cuándo se cierra el tubo neural después de la concepción?",["Entre los veintiséis y los veintiocho días","Entre los diez y los quince días","Entre los sesenta y los noventa días"],["Exacto: las primeras células nerviosas aparecen seis días más tarde, alrededor de los ventrículos.","Falso: ese plazo es demasiado precoz.","Falso: el cierre es bastante anterior."]],
  "7": ["¿Dónde aparecen las primeras células nerviosas?",["Alrededor de los ventrículos","Directamente en la corteza definitiva","Únicamente a la altura de las crestas neurales"],["Exacto: aparecen seis días después del cierre del tubo neural.","Falso: la corteza solo es colonizada después de la migración.","Falso: las crestas neurales dan lugar al sistema nervioso periférico."]],
  "8": ["¿Por cuánto se multiplica el volumen cerebral en la segunda mitad de la gestación?",["Por veinte","Por dos","Por cien"],["Exacto: ese crecimiento acompaña a la puesta en marcha de las grandes redes.","Falso: esa multiplicación está muy subestimada.","Falso: esa multiplicación está sobreestimada."]],
  "9": ["¿Qué ocurre entre las semanas veinte y veinticinco de gestación?",["Algunas conexiones alcanzan la subplaca","La mielinización de las vías motoras se completa","El tubo neural acaba de cerrarse"],["Exacto: allí esperan a ser reubicadas hacia la corteza en las semanas veinticinco y veintiséis.","Falso: la mielinización solo comienza uno o dos meses antes del nacimiento.","Falso: ese cierre tiene lugar mucho antes, en el primer mes."]],
  "10": ["¿A partir de qué semana aparecen los clubes de actividad neuronal densamente conectados?",["A partir de la trigésima semana","A partir de la decimoquinta semana","Solamente después del nacimiento"],["Exacto: señalan la organización de redes fuertemente interconectadas.","Falso: ese término es demasiado precoz.","Falso: su aparición es prenatal."]],
  "11": ["¿Qué región cortical madura más tardíamente durante la gestación?",["La corteza frontal, hacia las veintisiete semanas","La corteza occipital, hacia las veinte semanas","La corteza temporal, hacia las veinte semanas"],["Exacto: las regiones occipital y temporal maduran ya hacia la vigésima semana aproximadamente.","Falso: es, al contrario, una de las primeras regiones en madurar.","Falso: madura igualmente de forma precoz."]],
  "12": ["¿Cuál es el orden de las cuatro etapas del desarrollo neural?",["Proliferación, migración, organización y luego mielinización","Migración, proliferación, mielinización, organización","Organización, proliferación, migración, mielinización"],["Exacto: ese orden es constante y estructura todo el desarrollo.","Falso: la proliferación precede necesariamente a la migración.","Falso: la organización sigue a la migración, no la precede."]],
  "13": ["¿De qué hoja embrionaria derivan la placa y las crestas neurales?",["Del ectodermo","Del mesodermo","Del endodermo"],["Exacto: las crestas neurales darán lugar al sistema nervioso periférico.","Falso: da lugar, en particular, al esqueleto y a los músculos.","Falso: da lugar a los epitelios digestivos y respiratorios."]],
  "14": ["¿A qué da lugar la vesícula anterior del tubo neural?",["Al cerebro, al cerebelo y al tronco","A la medula espinal y a sus raíces","Al sistema nervioso periférico entero"],["Exacto: la vesícula posterior da lugar a la medula espinal.","Falso: la medula deriva de la vesícula posterior.","Falso: deriva de las crestas neurales."]],
  "15": ["¿En qué sentido se efectúa la migración neuronal?",["Del interior hacia el exterior de la corteza","Del exterior hacia el interior, de la corteza a los ventrículos","De forma aleatoria, sin dirección privilegiada"],["Exacto: las neuronas abandonan las zonas periventriculares para alcanzar la corteza.","Falso: el sentido es exactamente el inverso.","Falso: la migración es, al contrario, muy ordenada."]],
  "16": ["¿Cuándo comienza la mielinización?",["Uno o dos meses antes del nacimiento","Ya desde el cierre del tubo neural","Solamente después del primer aniversario"],["Exacto: solo se completa unos tres años después del nacimiento.","Falso: ese momento es mucho demasiado precoz.","Falso: comienza incluso antes del nacimiento."]],
  "17": ["¿Cuándo se completa la mielinización?",["Unos tres años después del nacimiento del niño","Ya desde las primeras semanas de vida","Solamente al final de la adolescencia"],["Exacto: comienza uno o dos meses antes del nacimiento.","Falso: el proceso es mucho más largo.","Falso: ese plazo supera el que se considera."]],
  "18": ["¿En qué orden se mielinizan las regiones?",["Sensoriales, luego motoras, luego asociativas","Motoras, luego sensoriales, luego asociativas","Asociativas, luego motoras, luego sensoriales"],["Exacto: ese orden explica la precocidad de los circuitos sensoriales.","Falso: las zonas sensoriales preceden a las motoras.","Falso: las zonas asociativas son las últimas en recibirla."]],
  "19": ["¿Qué es la sinaptogénesis?",["La formación de nuevas sinapsis","La formación de nuevas neuronas","La eliminación de las conexiones inútiles"],["Exacto: la neurogénesis designa, por su parte, la formación de nuevas neuronas.","Falso: esa definición es la de la neurogénesis.","Falso: esa definición es la de la poda sináptica."]],
  "20": ["¿Qué hace el cerebro con las conexiones inútiles durante el aprendizaje?",["Las elimina y conserva las más eficaces","Las conserva todas, por seguridad funcional","Las transforma en nuevas neuronas"],["Exacto: es el proceso de ajuste y de poda sináptica.","Falso: la conservación indiferenciada no tendría ningún interés.","Falso: no existe ninguna transformación de ese tipo."]],
  "21": ["¿Cuáles son los primeros circuitos maduros y permanentes?",["Los circuitos sensoriales y visuales, maduros hacia los tres meses","Los circuitos motores voluntarios, ya desde el nacimiento","Los circuitos asociativos frontales, hacia los seis meses"],["Exacto: esa precocidad se desprende del orden de mielinización.","Falso: los circuitos motores maduran después de los sensoriales.","Falso: esos circuitos son los más tardíos."]],
  "22": ["¿A qué dan lugar las crestas neurales?",["Al sistema nervioso periférico","A la corteza cerebral definitiva","A la medula espinal en su totalidad"],["Exacto: se desprenden de la placa neural hacia el vigesimoprimer día.","Falso: la corteza deriva de la vesícula anterior.","Falso: la medula deriva de la vesícula posterior."]],
  "23": ["¿Hacia qué día se forma la placa neural?",["Hacia el vigesimoprimer día","Hacia el séptimo día","Hacia el sexagésimo día aproximadamente"],["Exacto: el cierre del tubo le sigue, entre los veintiséis y los veintiocho días.","Falso: ese plazo es demasiado precoz.","Falso: la formación es bastante anterior."]],
  "24": ["¿Cuáles son las primeras redes en constituirse en el feto?",["Motoras, visuales y talámicas","Exclusivamente asociativas y prefrontales","Únicamente cerebelosas y vestibulares"],["Exacto: a ellas se añaden las redes subcorticales del núcleo caudado y del putamen.","Falso: esas redes son, al contrario, las más tardías.","Falso: esa restricción no corresponde a los datos."]],
  "25": ["¿Qué estructura subcortical se cuenta entre las primeras redes fetales?",["El núcleo caudado y el putamen","El cerebelo en su conjunto","El hipocampo y la amígdala"],["Exacto: acompañan a las redes motoras, visuales y talámicas.","Falso: no aparece en esa enumeración.","Falso: esas estructuras no se citan entre las primeras redes."]],
  "26": ["¿Qué ocurre en las semanas veinticinco y veintiséis del desarrollo?",["Las conexiones alcanzan por fin la corteza","El tubo neural completa su cierre caudal","La mielinización de las vías sensoriales se completa"],["Exacto: allí esperaban desde las semanas veinte a veinticinco.","Falso: ese cierre tiene lugar en el primer mes.","Falso: ni siquiera ha comenzado todavía."]],
  "27": ["¿Cuándo madura la ínsula a lo largo de la gestación?",["Entre las veintiséis y las treinta semanas","Entre las diez y las quince semanas aproximadamente","Solamente después del nacimiento"],["Exacto: la corteza frontal madura hacia las veintisiete o veintiocho semanas.","Falso: ese término es demasiado precoz.","Falso: su maduración comienza durante la gestación."]],
  "28": ["¿Qué es la etapa de organización del desarrollo neural?",["La diferenciación de las dendritas","La multiplicación de las células madre","El desplazamiento de las neuronas hacia la corteza"],["Exacto: es en esa fase cuando aparecen los pliegues y los surcos.","Falso: esa etapa es la proliferación.","Falso: esa etapa es la migración."]],
  "29": ["¿En qué momento del desarrollo se vuelven visibles los pliegues y los surcos?",["Durante la etapa de organización de las dendritas","Durante la proliferación","Durante la mielinización"],["Exacto: esa etapa sigue a la migración y precede a la mielinización.","Falso: en esa fase el tubo neural apenas se está estableciendo.","Falso: la giración ya está adquirida en esa fase."]],
  "30": ["¿Qué significa la epigenética en rehabilitación neurológica?",["El entorno modifica la expresión de los genes","El entorno modifica la secuencia de los genes","Los genes determinan por sí solos el devenir del paciente"],["Exacto: cerca del noventa y cinco por ciento de los genes están implicados.","Falso: la secuencia misma no se modifica.","Falso: es precisamente esa visión la que la epigenética matiza."]],
  "31": ["¿Qué es la neurogénesis?",["La formación de nuevas neuronas","La formación de nuevas sinapsis","La mielinización progresiva de los axones"],["Exacto: la sinaptogénesis atañe, por su parte, a las nuevas sinapsis.","Falso: esa definición es la de la sinaptogénesis.","Falso: se trata de un proceso distinto."]],
  "32": ["¿Cuáles son los dos fines del control postural?",["La estabilidad y la orientación","La fuerza y la resistencia musculares globales","La velocidad y la precisión del gesto voluntario"],["Exacto: estabilizar el centro de masa sobre la base de apoyo y orientar los segmentos en el entorno.","Falso: esas cualidades físicas no definen el control postural.","Falso: esos parámetros corresponden al control del movimiento, no a la postura."]],
  "33": ["¿Qué sistema asegura la percepción en el control postural?",["El sistema aferente","El sistema eferente","El sistema autónomo simpático"],["Exacto: la acción pasa, al contrario, por el sistema eferente y las vías motoras mediales.","Falso: sostiene la acción, no la percepción.","Falso: no desempeña ese papel en el control postural."]],
  "34": ["¿Qué es el centro de gravedad?",["La proyección vertical del centro de masa en el suelo","El punto central de la masa corporal total","La superficie delimitada por los puntos de contacto"],["Exacto: el centro de masa es, por su parte, el punto central de la masa corporal total.","Falso: esa definición es la del centro de masa.","Falso: esa definición es la de la base de apoyo."]],
  "35": ["¿Qué es la base de apoyo?",["La superficie delimitada por los puntos de contacto","El punto central de la masa del cuerpo","La proyección vertical de la masa en el suelo"],["Exacto: es sobre ella donde se proyecta el centro de gravedad.","Falso: esa definición es la del centro de masa.","Falso: esa definición es la del centro de gravedad."]],
  "36": ["¿Un centro de masa que sale de la base de apoyo provoca necesariamente la caída?",["No, el centro de presión lo devuelve","Sí, la caída se vuelve entonces inevitable","Sí, salvo si la visión está intacta"],["Exacto: el patinador es la ilustración de ello, conserva el control pese a esa salida.","Falso: esa afirmación ignora el papel del centro de presión.","Falso: no es la visión lo que explica el mantenimiento del control."]],
  "37": ["¿Qué privilegia un portero que se lanza hacia el balón?",["La orientación","La estabilidad","El ahorro de energía del gesto"],["Exacto: acepta caer para seguir orientado hacia el balón, mientras que el funambulista privilegia la estabilidad.","Falso: es lo que privilegia el funambulista.","Falso: no es la decisión descrita."]],
  "38": ["¿Qué abarca el término «cognitivo» entre los componentes del control postural?",["Procesos superiores, no necesariamente conscientes","Procesos necesariamente conscientes y voluntarios","Procesos puramente sensoriales periféricos"],["Exacto: es un contrasentido frecuente equiparar cognitivo y consciente.","Falso: es precisamente la confusión que hay que evitar.","Falso: estos corresponden a los procesos sensoriales, distintos."]],
  "39": ["¿Qué papel desempeña la visión focal?",["Localiza los objetos antes de la prensión","Reconoce el entorno global","Calibra únicamente el sistema vestibular"],["Exacto: la visión periférica, por su parte, reconoce el entorno.","Falso: ese papel corresponde a la visión periférica.","Falso: es la visión en su conjunto la que asegura esa calibración."]],
  "40": ["¿Por qué resulta ineficaz emplear la visión focal para mantener la postura?",["Genera fijaciones cervicales","Es demasiado lenta para corregir un desequilibrio","No proporciona ninguna información espacial útil"],["Exacto: la postura debe apoyarse en la visión periférica y en las demás aferencias.","Falso: no es el argumento que se considera.","Falso: sí la proporciona, pero para la prensión de objetos."]],
  "41": ["¿Qué se puede decir de los reflejos vestibulares y cervicales?",["Son innatos pero integrados centralmente","Son enteramente aprendidos después del nacimiento","Son innatos y estrictamente inmutables"],["Exacto: su aprendizaje adaptativo y plástico puede, por tanto, volverse inadecuado.","Falso: su base es innata.","Falso: su plasticidad es, al contrario, importante."]],
  "42": ["¿Qué comportamiento caracteriza al sistema vestibular?",["Un comportamiento reactivo mediante esquemas extensores totales","Un comportamiento anticipatorio finamente graduado","Un comportamiento puramente cognitivo y voluntario"],["Exacto: gestiona los desequilibrios inesperados mediante respuestas globales.","Falso: la anticipación corresponde a la formación reticular.","Falso: sus respuestas son, al contrario, primitivas y rápidas."]],
  "43": ["¿Dónde se sitúan los graviceptores?",["A nivel visceral","En las cápsulas articulares de los miembros","En la piel de la planta del pie"],["Exacto: detectan el desplazamiento del peso mediante la redistribución de los fluidos viscerales.","Falso: esos receptores son los corpúsculos de Ruffini.","Falso: se trata ahí de mecanorreceptores cutáneos."]],
  "44": ["¿Hacia qué estructuras proyectan los graviceptores?",["Hacia el tálamo posterolateral y el parietal","Únicamente hacia el cerebelo y el tronco cerebral","Hacia la corteza frontal asociativa"],["Exacto: esa proyección explica su papel en el esquema corporal.","Falso: no es la proyección descrita.","Falso: esa región no es la diana descrita."]],
  "45": ["¿Qué sistema permite las respuestas en anticipación?",["El sistema somatosensorial","El sistema vestibular","El sistema visual focal"],["Exacto: es él el que hace posible el control en anticipación.","Falso: gestiona más bien las respuestas reactivas inesperadas.","Falso: sirve para localizar los objetos antes de la prensión."]],
  "46": ["¿Cuántos modelos del esquema corporal se distinguen?",["Dos, uno parietal y el otro cerebeloso","Uno solo, enteramente consciente y parietal","Tres, parietal, cerebeloso y frontal"],["Exacto: esa dualidad explica que un segmento pueda ser conocido sin ser utilizable para la postura.","Falso: el modelo cerebeloso no consciente también está descrito.","Falso: solo se consideran dos modelos."]],
  "47": ["¿Qué inconveniente presentan los bastones y los andadores?",["Perturban las aferencias del paciente","Aumentan excesivamente la fuerza muscular","No tienen ningún inconveniente demostrado"],["Exacto: alteran los límites de estabilidad percibidos por el paciente.","Falso: no es el efecto descrito.","Falso: su efecto sobre las aferencias está documentado."]],
  "48": ["¿Qué tipo de control del equilibrio se ejerce durante una marcha a velocidad constante?",["El control en estado estable","El control reactivo","El control anticipatorio"],["Exacto: se aplica a las condiciones previsibles, como la sedestación o la bipedestación estática.","Falso: interviene después de una perturbación inesperada.","Falso: precede a un movimiento voluntario desestabilizador."]],
  "49": ["¿Qué tipo de control interviene cuando uno tropieza?",["El control reactivo, por retroalimentación","El control anticipatorio, por anticipación","El control en estado estable"],["Exacto: restablece la estabilidad después de una perturbación inesperada.","Falso: la anticipación precede a un movimiento voluntario.","Falso: se aplica a las condiciones previsibles."]],
  "50": ["¿Qué tipo de control precede al levantamiento de un objeto pesado?",["El control anticipatorio, por anticipación","El control reactivo, por retroalimentación","El control en estado estable"],["Exacto: los músculos posturales se activan antes del movimiento desestabilizador.","Falso: interviene después de la perturbación.","Falso: la situación no tiene nada de estática."]],
  "51": ["¿Dónde se produce el control anticipatorio del equilibrio?",["En la formación reticular","En el sistema vestibular","En la corteza parietal asociativa"],["Exacto: siempre está ligado al movimiento voluntario.","Falso: este sostiene el control reactivo.","Falso: esa región no es la descrita."]],
  "52": ["¿Dónde se produce el control reactivo del equilibrio?",["En el sistema vestibular","En la formación reticular","En la corteza motora primaria"],["Exacto: sus respuestas son genéticas, primitivas, rápidas y prioritarias.","Falso: esta sostiene el control anticipatorio.","Falso: esa área ordena el movimiento voluntario."]],
  "53": ["¿Qué son los ajustes posturales anticipatorios?",["Una condición previa al movimiento voluntario","Una respuesta automática a una perturbación sufrida","Un reflejo medular independiente de la corteza"],["Exacto: son aprendidos y modificados por la retroalimentación, lo que remodela el esquema corporal.","Falso: esa descripción es la del control reactivo.","Falso: son aprendidos y modificables."]],
  "54": ["¿Puede un segmento que no pertenece al esquema corporal servir al control postural?",["No, solo puede servir a un control cortical","Sí, en cuanto es visible para el paciente","Sí, con la condición de que sea móvil"],["Exacto: si sigue siendo accesible por la visión, entra en un control cortical, pero no postural.","Falso: la visibilidad no basta para integrarlo al control postural.","Falso: la movilidad tampoco basta."]],
  "55": ["¿En qué base muscular se asientan los ajustes posturales anticipatorios?",["La estabilidad del tronco profundo","La fuerza de los músculos superficiales de la espalda","La potencia de los extensores de la cadera"],["Exacto: los músculos posturales profundos de la parte baja del tronco se coactivan antes de todo movimiento de los miembros.","Falso: no son esos músculos los que aseguran esa función.","Falso: la coactivación profunda precede a su acción."]],
  "56": ["¿Qué estrategia motora se activa ante un pequeño desequilibrio sobre superficie firme?",["La estrategia de tobillo","La estrategia de cadera","La estrategia del paso"],["Exacto: la cadera toma el relevo ante perturbaciones más importantes, y después el paso.","Falso: responde a las perturbaciones más importantes o a las superficies inestables.","Falso: responde a las perturbaciones más intensas."]],
  "57": ["¿Qué estrategia motora se activa sobre una superficie inestable?",["La estrategia de cadera","La estrategia de tobillo","La estrategia del paso"],["Exacto: se intercala entre la estrategia de tobillo y la del paso.","Falso: conviene a los pequeños desequilibrios sobre superficie firme.","Falso: está reservada a las perturbaciones muy importantes."]],
  "58": ["¿Qué ocurre con la estrategia de tobillo en el paciente neurológico?",["Se pierde","Se vuelve predominante y eficaz","Permanece estrictamente inalterada"],["Exacto: la estrategia de cadera se vuelve compensatoria pero ineficaz, y el paso se ralentiza.","Falso: lo que se observa es lo contrario.","Falso: su alteración es, al contrario, constante."]],
  "59": ["¿Cuáles son las dos leyes de dirección del desarrollo motor?",["Cefalocaudal y proximodistal","Caudocefálica y distoproximal","Lateral y luego medial, de forma simétrica"],["Exacto: el desarrollo sigue siendo, no obstante, no lineal, con retrocesos.","Falso: ambas direcciones están invertidas.","Falso: esa descripción no corresponde a ninguna ley descrita."]],
  "60": ["¿Cómo se califica la progresión del desarrollo motor?",["Una jerarquía en espiral, no lineal","Una progresión estrictamente lineal y continua","Una sucesión de etapas definitivas e irreversibles"],["Exacto: se producen retrocesos cuando el niño adquiere una competencia más compleja.","Falso: las regresiones transitorias son normales.","Falso: las adquisiciones pueden regresar de forma transitoria."]],
  "61": ["¿A qué edad adquiere el niño la sedestación autónoma?",["Entre los seis y los ocho meses","Entre los dos y los cuatro meses","Entre los ocho y los diez meses"],["Exacto: el control cefálico la precede en dos a cuatro meses, y la marcha le sigue a los doce o quince meses.","Falso: ese periodo es el del control cefálico.","Falso: ese periodo es el del gateo."]],
  "62": ["¿Qué excepción a la ley cefalocaudal se observa a las ocho semanas?",["El lactante alcanza juguetes con los pies","El lactante se mantiene sentado sin apoyo","El lactante se da la vuelta por completo"],["Exacto: el control de las piernas en el espacio aparece un mes antes que el de los brazos.","Falso: esa competencia es bastante más tardía.","Falso: esa competencia no aparece a esa edad."]],
  "63": ["¿Se aplica la ley cefalocaudal al equilibrio?",["Sí, la secuencia se respeta en él perfectamente","No, en él se encuentra sistemáticamente invertida","No, en él no se observa ninguna dirección"],["Exacto: la excepción atañe al alcance de objetos con los pies, no al equilibrio.","Falso: la inversión solo atañe a la prensión con el pie.","Falso: la secuencia es en él, al contrario, nítida."]],
  "64": ["¿Qué postula la teoría jerárquica del control postural?",["Depende de la maduración del sistema nervioso central","Nace de la interacción entre el niño y su medio","Depende únicamente de la fuerza muscular adquirida"],["Exacto: describe la aparición y la integración sucesivas de los reflejos.","Falso: esa concepción es la de la teoría sistémica.","Falso: ninguna teoría reduce el control postural a la fuerza."]],
  "65": ["¿Qué postula la teoría sistémica del control postural?",["Una interacción compleja entre el niño y su entorno","Una maduración programada del sistema nervioso central","Una sucesión de integraciones reflejas obligatorias"],["Exacto: en ella intervienen la fuerza, la coordinación, los sistemas sensoriales y los recursos cognitivos.","Falso: esa concepción es la de la teoría jerárquica.","Falso: esa descripción corresponde igualmente a la teoría jerárquica."]],
  "66": ["¿Por qué el recién nacido no tiene control cefálico?",["Por falta de fuerza y de organización","Únicamente por falta de fuerza muscular","Por ausencia total de reflejos vestibulares"],["Exacto: el electromiograma no muestra ningún patrón organizado contra la gravedad.","Falso: la ausencia de organización cuenta igual de mucho.","Falso: esos reflejos existen desde el nacimiento."]],
  "67": ["¿A partir de qué edad se orienta el lactante hacia un estímulo visual?",["Ya desde las sesenta horas de vida","Ya desde los dos meses de vida","Ya desde los seis meses de vida"],["Exacto: a los dos o tres meses, la visión se vuelve esencial para el control antigravitatorio de la cabeza.","Falso: esa orientación es bastante más precoz.","Falso: esa competencia existe desde los primeros días."]],
  "68": ["¿Qué papel desempeña la visión con respecto a los demás sistemas?",["Los calibra","Los sustituye por entero","Los inhibe de forma duradera"],["Exacto: calibra los sistemas vestibular y propioceptivo.","Falso: los demás sistemas conservan su papel propio.","Falso: su papel es calibrador y no inhibidor."]],
  "69": ["¿Qué muestran los lactantes ciegos sobre el papel de la visión?",["No emplean el vestibular para la cabeza","Compensan íntegramente mediante el vestibular","Desarrollan un control postural más precoz"],["Exacto: orientan la cabeza hacia un objeto sostenido a los seis meses, pero esa conducta desaparece hacia los diez meses.","Falso: es precisamente lo que no logran hacer.","Falso: su desarrollo postural está, al contrario, retrasado."]],
  "70": ["¿Qué muestra la respuesta al flujo óptico ya desde los tres días de vida?",["Las redes subcorticales existen ya","La visión no desempeña ningún papel antes de los dos meses","El control postural es enteramente aprendido"],["Exacto: un balanceo visual hacia delante hace que la cabeza del lactante retroceda.","Falso: ese experimento prueba lo contrario.","Falso: esas redes están presentes desde el nacimiento."]],
  "71": ["¿Qué muestra la comparación entre niños sordos según su función vestibular?",["Retrasa el control cefálico y la marcha","La sordera por sí sola explica todo el retraso observado","No se observa ninguna diferencia entre ambos grupos"],["Exacto: la maduración vestibular está programada, pero depende de la experiencia.","Falso: es la función vestibular la que marca la diferencia.","Falso: la diferencia es, al contrario, nítida."]],
  "72": ["¿Puede mejorarse el control cefálico del lactante mediante el entrenamiento?",["Sí, veinte minutos al día durante cuatro semanas","No, depende únicamente de la maduración del sistema","Sí, pero solo después de los seis meses de vida"],["Exacto: esa mejora se ha demostrado en lactantes de un mes.","Falso: el entrenamiento tiene un efecto demostrado.","Falso: el efecto se obtiene ya desde el primer mes."]],
  "73": ["¿Cómo se construye el control del tronco entre los tres y los nueve meses?",["De arriba abajo","De abajo arriba","Simultáneamente en toda su altura"],["Exacto: esa progresión acompaña a la adquisición de la sedestación autónoma.","Falso: la dirección es la inversa.","Falso: la progresión es, al contrario, escalonada."]],
  "74": ["¿Qué traduce la disminución de complejidad del balanceo entre los cinco y los seis meses y medio?",["El niño se fija en una estrategia única","Una regresión del control postural adquirido","Una pérdida definitiva de las estrategias exploradas"],["Exacto: la complejidad vuelve a subir después, entre los seis y los ocho meses, signo de adaptabilidad.","Falso: se trata de una etapa normal del aprendizaje.","Falso: la complejidad vuelve a subir después."]],
  "75": ["¿Qué traduce el aumento de complejidad del balanceo entre los seis y los ocho meses?",["El dominio y, por tanto, la adaptabilidad","Una exploración desordenada de estrategias","Una inestabilidad patológica del control"],["Exacto: después de la fase de fijación en una estrategia única.","Falso: esa fase es anterior, entre los cuatro y los cinco meses y medio.","Falso: ese aumento es, al contrario, un buen signo."]],
  "76": ["¿A qué edad es mínimo el control reactivo del tronco?",["Hacia los tres meses","Ya desde el nacimiento","Hacia los ocho meses"],["Exacto: está disponible desde el primer mes, pero limitado, y luego aumenta a partir de los cuatro o cinco meses.","Falso: está presente, aunque limitado, ya desde el primer mes.","Falso: a esa edad está, al contrario, bien desarrollado."]],
  "77": ["¿Cuántos flexores anteriores se activan en el niño de siete a ocho meses que se mantiene sentado?",["Tres, en todas las perturbaciones","Uno solo, de forma muy inconstante","Cinco, de forma sistemática"],["Exacto: cuello, recto del abdomen y recto femoral; entre los cinco y los siete meses el niño solo moviliza uno o dos.","Falso: esa respuesta limitada corresponde al niño de cinco a siete meses.","Falso: solo se describen tres músculos."]],
  "78": ["¿Qué proporción de intentos presenta un control anticipatorio ya a los tres meses?",["Alrededor del cuarenta por ciento","Alrededor del diez por ciento","Alrededor del ochenta por ciento"],["Exacto: esa proporción sube después al sesenta por ciento.","Falso: esa estimación está subvalorada.","Falso: esa proporción corresponde al control compensatorio."]],
  "79": ["¿Qué control aparece primero en el lactante?",["El control compensatorio","El control anticipatorio","Ambos aparecen simultáneamente"],["Exacto: atañe al ochenta por ciento de los intentos y precede al anticipatorio.","Falso: aparece después del compensatorio.","Falso: su cronología está claramente desfasada."]],
  "80": ["¿Cómo evoluciona la dependencia sensorial durante la adquisición de la sedestación?",["De la visión hacia el somatosensorial de la cadera","De una dependencia somatosensorial hacia la visión","De una dependencia vestibular hacia la visión focal"],["Exacto: el balanceo aumenta con las luces apagadas, lo que muestra el papel persistente de la visión.","Falso: la progresión es exactamente la inversa.","Falso: esa secuencia no corresponde a los datos."]],
  "81": ["¿Es la fuerza el factor limitante de la bipedestación en el niño?",["No, la fuerza se adquiere ya a los seis meses","Sí, la fuerza es el principal factor limitante","Sí, pero solo antes de los tres meses de edad"],["Exacto: los límites de estabilidad, mucho más reducidos que en sedestación, son el verdadero problema.","Falso: la fuerza se adquiere mucho antes de la bipedestación.","Falso: la fuerza no es el factor limitante a ninguna edad."]],
  "82": ["¿A qué edad aparecen las primeras respuestas direccionales en el tobillo?",["Entre los siete y los nueve meses","Entre los dos y los seis meses","Entre los nueve y los once meses"],["Exacto: antes, entre los dos y los seis meses, no se observa ninguna respuesta coordinada.","Falso: a esa edad no existe ninguna respuesta coordinada.","Falso: a esa edad se añaden el segmento femoral y después el tronco."]],
  "83": ["¿En qué sentido se activa la sinergia postural entre los nueve y los once meses?",["De distal a proximal","De proximal a distal","Simultáneamente en toda la cadena"],["Exacto: tobillo, luego cadera, luego tronco.","Falso: la secuencia es la inversa.","Falso: la activación es secuencial."]],
  "84": ["¿Qué sistema pilota los músculos de la bipedestación ya desde los cinco o seis meses?",["La visión","El somatosensorial","Únicamente el vestibular"],["Exacto: el niño debe después redescubrir sus sinergias cuando el somatosensorial se integra.","Falso: se integra más tardíamente.","Falso: no es el piloto inicial descrito."]],
  "85": ["¿A qué edad aparece el control activo de la estrategia de cadera?",["Entre los siete y los diez años","Entre los nueve y los once meses","Entre los dos y los cuatro años"],["Exacto: es bastante más tardío que la aparición de las respuestas de tobillo.","Falso: a esa edad el segmento femoral solo se recluta de forma pasiva.","Falso: la adquisición es más tardía."]],
  "86": ["¿Por qué el equilibrio es más difícil en el niño?",["Su centro de gravedad está más alto","Su base de apoyo es más amplia","Su masa muscular es proporcionalmente menor"],["Exacto: la madurez musculoesquelética se adquiere entre los cero y los siete años.","Falso: una base amplia facilitaría, al contrario, el equilibrio.","Falso: la fuerza no es el factor limitante."]],
  "87": ["¿A qué edad alcanza el control postural el nivel del adulto?",["Hacia los diez o doce años","Hacia los seis o siete años","Hacia los quince o dieciséis años"],["Exacto: la organización sensorial madura de los cuatro a los diez años y los sistemas cognitivos de los cuatro a los trece años.","Falso: la maduración no está completada a esa edad.","Falso: el nivel del adulto se alcanza antes."]],
  "88": ["¿Qué no consiguen hacer los niños de menos de siete u ocho años?",["Mantener el equilibrio solo con las señales vestibulares","Generar una fuerza suficiente para mantenerse de pie","Emplear la estrategia de tobillo"],["Exacto: todavía necesitan las aferencias visuales o somatosensoriales.","Falso: esa fuerza se adquiere ya hacia los seis meses.","Falso: se adquiere ya a los siete o nueve meses."]],
  "89": ["¿Cómo se define un control postural maduro?",["Por la capacidad de recalibrar las aferencias","Únicamente por la rapidez de las respuestas musculares","Por la fuerza máxima de los músculos posturales"],["Exacto: si la visión se vuelve engañosa, el sistema reduce su dependencia de ella.","Falso: la velocidad depende de la mielinización, no de la madurez del control.","Falso: la fuerza no es el criterio de madurez."]],
  "90": ["¿Qué efecto tiene el entrenamiento sobre la respuesta muscular postural?",["Aumenta su probabilidad pero no su velocidad","Aumenta su velocidad pero no su probabilidad","Aumenta a la vez la probabilidad y la velocidad"],["Exacto: la latencia de activación depende de la mielinización.","Falso: ambos efectos están invertidos.","Falso: la velocidad sigue estando limitada por la maduración."]],
  "91": ["¿Qué principio resume el desarrollo de los sistemas del control postural?",["Los sistemas más lentos son los más limitantes","Todos los sistemas se desarrollan al mismo ritmo","Los sistemas más rápidos son los más limitantes"],["Exacto: se desarrollan a velocidades diferentes, y el reactivo precede al anticipatorio.","Falso: sus velocidades difieren claramente.","Falso: lo cierto es lo contrario."]],
  "92": ["¿Qué caracteriza al periodo prenatal del desarrollo neurológico?",["La fase de la subplaca, orientada a la exploración","El predominio de los circuitos permanentes","Una conducta motora centrada en la adaptación al medio"],["Exacto: dura hasta los tres meses aproximadamente, siendo el periodo posnatal el de la adaptación.","Falso: esos circuitos predominan en el periodo posnatal.","Falso: la adaptación caracteriza al periodo posnatal."]],
  "93": ["¿Qué área cortical madura hacia los doce meses?",["La corteza prefrontal asociativa","La corteza somatosensorial primaria","Las áreas de asociación parietales"],["Exacto: las áreas somatosensorial, auditiva y visual maduran ya a los tres meses.","Falso: madura ya a los tres meses.","Falso: maduran hacia los veinticuatro meses."]],
  "94": ["¿Qué áreas maduran hacia los veinticuatro meses?",["Las áreas de asociación parietal y frontal","Las áreas auditiva y visual primarias","La corteza frontal de la etapa preescolar"],["Exacto: la prefrontal asociativa las ha precedido a los doce meses.","Falso: maduran ya a los tres meses.","Falso: esa maduración es más tardía."]],
  "95": ["¿Qué produce la repetición de un estímulo nuevo?",["Crea más conexiones y las estabiliza","Disminuye el número de sinapsis creadas","No tiene ningún efecto sobre las conexiones"],["Exacto: el aprendizaje se refuerza mediante las emociones y la búsqueda de nuevos retos.","Falso: la repetición refuerza, al contrario, la sinaptogénesis.","Falso: su efecto estructural está bien documentado."]],
  "96": ["¿A partir de qué término se habla de prematuridad en este marco?",["Antes de las treinta y ocho semanas","Antes de las treinta y dos semanas","Antes de las cuarenta y dos semanas"],["Exacto: el gran prematuro nace antes de las treinta y dos semanas o pesa menos de mil quinientos gramos.","Falso: ese umbral define la gran prematuridad.","Falso: ese término corresponde al final del embarazo normal."]],
  "97": ["¿Qué define a un gran prematuro?",["Un nacimiento antes de las treinta y dos semanas","Un nacimiento antes de las treinta y ocho semanas","Un peso al nacer por debajo de dos mil quinientos gramos"],["Exacto: la prematuridad simple se define antes de las treinta y ocho semanas.","Falso: ese umbral define la prematuridad en general.","Falso: ese umbral define el bajo peso al nacer."]],
  "98": ["¿Cómo se calcula la edad corregida?",["Edad cronológica menos los meses de prematuridad","Edad cronológica más los meses de prematuridad","Edad gestacional menos la edad cronológica"],["Exacto: permite distinguir una afectación neurológica de un simple retraso de maduración.","Falso: el cálculo está invertido.","Falso: esa resta no tiene sentido clínico."]],
  "99": ["¿Qué mide el enfoque cuantitativo del desarrollo?",["La edad mental, es decir, lo que el niño hace","La edad postural, es decir, la manera de hacerlo","La calidad del tono pasivo de los miembros"],["Exacto: la lectura cualitativa, o edad postural, se refiere a la manera en que lo hace.","Falso: esa lectura es cualitativa.","Falso: no es la distinción descrita."]],
  "100": ["¿Qué mide el enfoque cualitativo del desarrollo?",["La edad postural, la manera en que el niño lo hace","La edad mental, lo que el niño sabe hacer","El número de adquisiciones motoras alcanzadas"],["Exacto: la cantidad, o edad mental, se refiere a lo que hace.","Falso: esa lectura es cuantitativa.","Falso: el recuento corresponde a la vertiente cuantitativa."]],
  "101": ["¿Qué desarrolla principalmente el decúbito supino en el lactante?",["La motricidad fina y la manipulación","El enderezamiento y la orientación en el espacio","La coordinación de las cinturas escapulares"],["Exacto: el decúbito prono desarrolla, al contrario, el enderezamiento y la motricidad global.","Falso: esos mecanismos se construyen en decúbito prono.","Falso: no es la función propia de esa posición."]],
  "102": ["¿Qué desarrolla principalmente el decúbito prono en el lactante?",["El enderezamiento y la motricidad global","La prensión y la motricidad fina","La estereognosia y la supinación"],["Exacto: el decúbito supino desarrolla la prensión y la motricidad fina.","Falso: esos mecanismos se construyen en decúbito supino.","Falso: esas adquisiciones aparecen en supino, al quinto mes."]],
  "103": ["¿Qué patrón postural caracteriza al recién nacido?",["Un patrón en flexión, asimétrico e inestable","Un patrón en extensión, simétrico y estable","Un patrón en rotación con apoyo simétrico"],["Exacto: con reflejos arcaicos presentes y movimientos globales.","Falso: la simetría y la estabilidad solo aparecen al tercer mes.","Falso: esa descripción no corresponde al recién nacido."]],
  "104": ["¿Cómo se presentan las manos del recién nacido?",["En puño, con las muñecas flexionadas y desviadas","Abiertas, con la bóveda palmar ahuecada","En supinación con el pulgar en oposición"],["Exacto: con una desviación cubital de las muñecas.","Falso: esa apertura aparece al sexto mes.","Falso: la oposición del pulgar solo llega a los veinticuatro meses."]],
  "105": ["¿Cuál es la posición de las caderas del recién nacido?",["En gran flexión y abducción","En extensión completa y aducción","En rotación externa con las rodillas estiradas"],["Exacto: la pelvis está en anteversión y las piernas flexionadas.","Falso: esa posición no es la del recién nacido.","Falso: las rodillas están flexionadas."]],
  "106": ["¿Qué respuesta de los miembros inferiores se observa en el recién nacido?",["Una flexión en los tres niveles","Una extensión completa de los tres niveles","Una abducción máxima sin flexión"],["Exacto: cadera, rodilla y tobillo adoptan esa posición de flexión.","Falso: el patrón postural es en flexión.","Falso: la abducción es de cuarenta y cinco grados, con flexión."]],
  "107": ["¿Qué ocurre hacia las seis semanas de vida?",["El primer enderezamiento óptico","El apoyo simétrico sobre ambos codos","El apoyo simétrico sobre las manos"],["Exacto: fijación de la mirada, cabeza levantada, codos adelantados y apoyo umbilical.","Falso: esa adquisición es la del tercer mes.","Falso: esa adquisición es la del sexto mes."]],
  "108": ["¿Qué es el patrón del esgrimista?",["Flexión nucal, extensión facial","Extensión nucal, flexión facial","Flexión simétrica de los cuatro miembros"],["Exacto: aparece entre las seis y las ocho semanas, como consecuencia de la orientación óptica.","Falso: ambas vertientes están invertidas.","Falso: el patrón es asimétrico por definición."]],
  "109": ["¿Qué caracteriza al tercer mes de vida?",["La estabilidad y la simetría","La asimetría y la inestabilidad postural","La verticalización y la bipedestación"],["Exacto: corresponden a los primeros circuitos sensitivomotores permanentes corticales.","Falso: esos caracteres son los del recién nacido.","Falso: esas adquisiciones son las del noveno y del décimo mes."]],
  "110": ["¿En qué se apoya el lactante de tres meses en decúbito prono?",["Simétricamente sobre los codos","Asimétricamente sobre un solo codo","Simétricamente sobre las manos abiertas"],["Exacto: con rotación libre de la cabeza a noventa grados y apoyo pubiano.","Falso: ese apoyo asimétrico aparece a los cuatro meses y medio.","Falso: ese apoyo aparece al sexto mes."]],
  "111": ["¿Qué puede hacer el lactante de cuatro meses y medio?",["Asir lateralmente sin cruzar el eje","Cruzar la línea media con un objeto","Asir en el eje medio en supinación"],["Exacto: el apoyo asimétrico sobre un codo desplaza el centro de gravedad lateralmente.","Falso: esa adquisición es la del sexto mes.","Falso: esa adquisición es la del quinto mes."]],
  "112": ["¿Qué describe el triángulo de base lateral del cuarto mes y medio?",["Codo y muslo occipitales, rodilla facial","Dos codos y el pubis en apoyo simétrico","Dos manos y las dos rodillas en el suelo"],["Exacto: ese apoyo se acompaña de una oblicuidad pélvica.","Falso: esa descripción es la del tercer mes.","Falso: esa posición es la del gateo."]],
  "113": ["¿Qué adquisición caracteriza al quinto mes?",["La supinación, con prensión en el eje","El apoyo simétrico sobre las dos manos","La pinza digital fina"],["Exacto: el contacto planta contra planta y la estereognosia aparecen también.","Falso: esa adquisición es la del sexto mes.","Falso: aparece a los siete meses y medio."]],
  "114": ["¿Qué es el patrón del nadador?",["El primer callejón sin salida motor, breve","Una etapa duradera del gateo","El patrón asimétrico del segundo mes"],["Exacto: se observa en decúbito prono y no se prolonga.","Falso: se trata de un callejón sin salida breve, no de una etapa del gateo.","Falso: ese patrón es el del esgrimista."]],
  "115": ["¿Qué adquisición marca el sexto mes?",["El apoyo simétrico sobre las manos abiertas","El apoyo simétrico sobre los dos codos","La sedestación autónoma estable"],["Exacto: con rotación externa de los hombros y control cefálico total.","Falso: esa adquisición es la del tercer mes.","Falso: aparece al octavo mes."]],
  "116": ["¿Qué reflejo desaparece al sexto mes?",["La prensión palmar","La prensión plantar","El reflejo acusticofacial"],["Exacto: la prensión plantar, por su parte, persiste hasta el noveno mes.","Falso: persiste hasta el noveno mes.","Falso: persiste toda la vida."]],
  "117": ["¿Qué reacción de protección aparece al sexto mes?",["La reacción de paracaídas anterior","La reacción de paracaídas lateral","La reacción de extensión cruzada"],["Exacto: acompaña al control cefálico total y al volteo de supino a prono.","Falso: no es la descrita a esa edad.","Falso: ese reflejo desaparece hacia las seis semanas."]],
  "118": ["¿Qué es el balanceo (rocking) del séptimo mes?",["Un balanceo en cuadrupedia sin avanzar","Un desplazamiento rápido en cuadrupedia","Un volteo de prono a supino"],["Exacto: acompaña al arrastre en foca y al decúbito lateral estable.","Falso: el niño todavía no progresa.","Falso: este aparece al octavo mes."]],
  "119": ["¿Qué adquisición manual marca los siete meses y medio?",["La pinza digital","La pinza en tenaza","La oposición completa del pulgar"],["Exacto: el arrastre y la sedestación oblicua la acompañan.","Falso: aparece al octavo mes.","Falso: solo aparece a los veinticuatro meses."]],
  "120": ["¿Qué adquisición manual marca el octavo mes?",["La pinza en tenaza","La pinza digital simple","La bóveda palmar abierta en apoyo"],["Exacto: la sedestación, el gateo y el volteo de prono a supino la acompañan.","Falso: aparece a los siete meses y medio.","Falso: aparece al sexto mes."]],
  "121": ["¿Cómo se desarrolla la verticalización del noveno mes?",["Por curiosidad, mediante tracción de los brazos","Por empuje sobre los miembros inferiores","Por un reflejo de enderezamiento automático"],["Exacto: es un proceso instintivo con motricidad cruzada.","Falso: la tracción parte de los miembros superiores.","Falso: se trata de un proceso instintivo ligado a la curiosidad."]],
  "122": ["¿Qué caracteriza al décimo mes?",["Gateo maduro, con las cinturas disociadas","La marcha frontal sin poder detenerse","La marcha lateral a lo largo de los muebles"],["Exacto: el niño mantiene la bipedestación y asume una carga lateral.","Falso: esa adquisición es la del duodécimo mes.","Falso: corresponde al undécimo mes."]],
  "123": ["¿Qué marcha aparece al duodécimo mes?",["La marcha frontal, sin poder detenerse","La marcha lateral a lo largo de los apoyos","La marcha con cambio de dirección"],["Exacto: la detención y el cambio de dirección solo llegan a los quince o dieciséis meses.","Falso: corresponde al undécimo mes.","Falso: ese dominio es más tardío."]],
  "124": ["¿Cuándo puede el niño detenerse y cambiar de dirección al andar?",["Entre los quince y los dieciséis meses","Entre los doce y los trece meses","Entre los veinte y los veinticuatro meses"],["Exacto: a los doce meses todavía anda sin poder detenerse.","Falso: a esa edad aún no sabe detenerse.","Falso: ese dominio se adquiere antes."]],
  "125": ["¿A qué edad se opone el pulgar a los demás dedos?",["Entre los quince y los dieciséis meses","A los ocho meses","Entre los veinte y los veinticuatro meses"],["Exacto: la pinza en tenaza la ha precedido ya en el octavo mes.","Falso: a esa edad aparece la pinza en tenaza.","Falso: la oposición completa es más tardía."]],
  "126": ["¿Qué marca el periodo de los tres a los cuatro años?",["El final del desarrollo motor ideal","El inicio de la marcha autónoma","La aparición de la pinza digital"],["Exacto: alineación de la pelvis, colocación astragalocalcánea y apoyo monopodal.","Falso: esta comienza hacia los doce meses.","Falso: aparece a los siete meses y medio."]],
  "127": ["¿Cuántas reacciones posturales se describen en el lactante?",["Siete","Tres","Doce"],["Exacto: responden a un cambio postural súbito y evolucionan de forma típica el primer año.","Falso: ese número es inferior al descrito.","Falso: ese número es superior al que se considera."]],
  "128": ["¿Qué propiedad hace particularmente útiles a las reacciones posturales?",["No dependen de la motivación del niño","Dependen estrechamente de su cooperación","Varían mucho de un examinador a otro"],["Exacto: son reproducibles y distinguen claramente lo normal de lo anormal.","Falso: es precisamente lo contrario lo que constituye su valor.","Falso: su reproducibilidad es buena."]],
  "129": ["¿Cuál es el interés clínico mayor de las reacciones posturales?",["Detectar la anomalía antes de la motricidad voluntaria","Medir el cociente de desarrollo del niño","Evaluar la fuerza muscular segmentaria"],["Exacto: son interpretables ya desde los primeros días de vida.","Falso: no es su objeto.","Falso: no evalúan la fuerza."]],
  "130": ["¿Cuándo aparece el reflejo acusticofacial?",["Hacia el décimo día de vida","Ya desde el nacimiento","Después del tercer mes"],["Exacto: persiste toda la vida, y su ausencia después del cuarto mes es patológica.","Falso: aparece algunos días después.","Falso: ese plazo es el del reflejo opticofacial."]],
  "131": ["¿Cuándo se vuelve patológica la ausencia del reflejo acusticofacial?",["Después del cuarto mes","Ya desde el nacimiento","Después del primer aniversario"],["Exacto: ese reflejo aparece hacia el décimo día y persiste toda la vida.","Falso: todavía no ha aparecido en esa fase.","Falso: el umbral es bastante más precoz."]],
  "132": ["¿Cuándo aparece el reflejo opticofacial?",["Después del tercer mes","Hacia el décimo día de vida","Ya desde el nacimiento"],["Exacto: su ausencia al final del segundo trimestre es patológica.","Falso: ese plazo es el del reflejo acusticofacial.","Falso: no está presente de entrada."]],
  "133": ["¿Hasta qué edad persiste el reflejo de succión?",["Hasta los tres meses","Hasta los nueve meses","Hasta las cuatro semanas"],["Exacto: es más intenso durante las cuatro primeras semanas.","Falso: esa duración es la de la prensión plantar.","Falso: esa duración es la del reflejo suprapubiano."]],
  "134": ["¿Hasta qué edad persiste la prensión plantar?",["Hasta los nueve meses","Hasta los tres meses","Hasta los cuatro meses"],["Exacto: la prensión palmar desaparece bastante antes, hacia los tres meses.","Falso: esa duración es la de la prensión palmar.","Falso: esa duración es la del reflejo de Galant."]],
  "135": ["¿Qué es el reflejo de Galant?",["Una incurvación hacia el lado estimulado en suspensión ventral","Una extensión tónica de las piernas a la presión pubiana","Un parpadeo ante la aproximación rápida de un objeto"],["Exacto: persiste desde el nacimiento hasta los cuatro meses.","Falso: esa descripción es la del reflejo suprapubiano.","Falso: esa descripción es la del reflejo opticofacial."]],
  "136": ["¿Hasta qué edad persiste el reflejo suprapubiano?",["Hasta las cuatro semanas","Hasta los cuatro meses","Hasta las seis semanas"],["Exacto: consiste en una extensión tónica de las piernas.","Falso: esa duración es la del reflejo de Galant.","Falso: esa duración es la de la extensión cruzada."]],
  "137": ["¿Hasta qué edad persiste el reflejo de extensión cruzada?",["Hasta las seis semanas","Hasta las cuatro semanas","Hasta los cuatro meses"],["Exacto: el reflejo suprapubiano, por su parte, se extingue ya a las cuatro semanas.","Falso: esa duración es la del reflejo suprapubiano.","Falso: esa duración es la del reflejo de Galant."]],
  "138": ["¿Sobre qué informan los reflejos primitivos?",["Sobre el funcionamiento subcortical","Sobre la maduración de la corteza asociativa","Sobre la integridad de los nervios periféricos"],["Exacto: están regulados a la altura del tronco cerebral.","Falso: exploran los niveles subcorticales.","Falso: no es su objeto."]],
  "139": ["¿Cuál es el tercer pilar del diagnóstico neurocinesiológico?",["La exploración de los reflejos primitivos","La medición del perímetro craneal","La exploración de la función pulmonar"],["Exacto: completa la motricidad espontánea y las reacciones posturales.","Falso: pertenece a la valoración morfológica.","Falso: corresponde a otro apartado de la evaluación."]],
  "140": ["¿Qué adquisición respiratoria marca el sexto mes?",["El inicio de la respiración toracoabdominal","La aparición de una respiración puramente abdominal","La maduración completa del diafragma"],["Exacto: el centro de gravedad se sitúa entonces a la altura de la pelvis y los muslos.","Falso: es el patrón anterior el que evoluciona.","Falso: esa formulación no corresponde a la adquisición descrita."]],
  "141": ["¿A qué nivel se sitúa el centro de gravedad del lactante de seis meses?",["A la altura de la pelvis y los muslos","A la altura umbilical","A la altura esternal y nucal"],["Exacto: ese desplazamiento acompaña al apoyo simétrico sobre las manos.","Falso: ese apoyo corresponde a las seis semanas.","Falso: esos apoyos son los del recién nacido."]],
  "142": ["¿Qué curvatura raquídea caracteriza al recién nacido en el plano frontal?",["Excurvación facial, incurvación occipital","Una rectitud perfecta del raquis","Una escoliosis estructural ya constituida"],["Exacto: en el plano sagital se encuentran lordosis cervical, cifosis dorsal y lordosis lumbar.","Falso: la asimetría frontal es característica.","Falso: se trata de una actitud y no de una deformidad."]],
  "143": ["¿Cuándo aparece la sonrisa en el lactante?",["Entre las seis y las doce semanas","Ya desde la primera semana de vida","Hacia el sexto mes de vida"],["Exacto: acompaña a la orientación óptica y al patrón del esgrimista.","Falso: la sonrisa social es más tardía.","Falso: aparece bastante antes."]],
  "144": ["¿Qué rotación cefálica realiza el lactante de tres meses?",["Noventa grados, con las cinturas disociadas","Cuarenta y cinco grados sin ninguna disociación","Ciento ochenta grados en bloque"],["Exacto: la articulación escapulohumeral está libre a esa edad.","Falso: la rotación alcanza los noventa grados.","Falso: esa amplitud es irreal."]],
  "145": ["¿Cuál es la posición de los miembros superiores en supino al tercer mes?",["En flexión de ciento veinte grados","En extensión completa a lo largo del cuerpo","En flexión de noventa grados"],["Exacto: los miembros inferiores están en flexión a noventa grados y abducción a cuarenta y cinco.","Falso: esa posición no es la descrita.","Falso: ese valor corresponde a los miembros inferiores."]],
  "146": ["¿Qué adquisición sensorial aparece al quinto mes?",["La estereognosia","La visión binocular fina","La discriminación auditiva de los fonemas"],["Exacto: acompaña a la supinación y al contacto planta contra planta.","Falso: no es la adquisición descrita a esa edad.","Falso: esa competencia no es la que se considera aquí."]],
  "147": ["¿Qué volteo aparece al sexto mes?",["De la espalda hacia el vientre","Del vientre hacia la espalda","Ambos aparecen simultáneamente"],["Exacto: el volteo del vientre hacia la espalda aparece al octavo mes.","Falso: esa adquisición es la del octavo mes.","Falso: su cronología está desfasada en dos meses."]],
  "148": ["¿Cuál es la naturaleza jurídica de la historia clínica?",["Un documento legal admisible como prueba","Un documento interno sin valor jurídico","Un documento que pertenece únicamente al centro"],["Exacto: se conserva de forma centralizada, durante un plazo mínimo, incluso después del fallecimiento.","Falso: su valor probatorio está, al contrario, reconocido.","Falso: el paciente puede obtener copia de ella."]],
  "149": ["¿Dónde se encuentra la historia de fisioterapia?",["En la historia clínica del paciente","En un expediente oficial e independiente","En poder del fisioterapeuta, a título privado"],["Exacto: no existe un expediente oficial de fisioterapia aparte.","Falso: no existe ningún expediente oficial separado.","Falso: forma parte de la historia clínica del paciente."]],
  "150": ["¿Qué debe obtener la entrevista clínica acerca del problema del paciente?",["Su naturaleza, su gravedad y su origen","Únicamente la intensidad del dolor","Únicamente el diagnóstico médico establecido"],["Exacto: a ello se añaden los antecedentes, las consecuencias y los factores agravantes o aliviadores.","Falso: ese dato aislado resultaría muy insuficiente.","Falso: la entrevista va mucho más allá del diagnóstico."]],
  "151": ["¿Cuál es la finalidad del razonamiento llevado a cabo durante la entrevista clínica?",["Formular hipótesis y objetivos","Confirmar el diagnóstico médico establecido","Elegir de entrada la técnica que se va a aplicar"],["Exacto: después hay que devolver la información al paciente y evaluar los resultados.","Falso: el fisioterapeuta no busca confirmarlo.","Falso: la técnica se desprende de los objetivos, no al contrario."]],
  "152": ["¿Qué duración de gestación define un parto a término?",["Treinta y siete a cuarenta y dos semanas","Treinta y dos a treinta y siete semanas","Cuarenta a cuarenta y cuatro semanas"],["Exacto: por debajo de las treinta y siete semanas se habla de prematuridad.","Falso: ese intervalo corresponde a la prematuridad moderada.","Falso: el límite inferior es mucho más bajo."]],
  "153": ["¿Qué umbral define un bajo peso al nacer?",["Menos de dos mil quinientos gramos","Menos de mil quinientos gramos","Menos de tres mil gramos"],["Exacto: el umbral de mil quinientos gramos define, por su parte, la gran prematuridad.","Falso: ese umbral es el del muy bajo peso, ligado a la gran prematuridad.","Falso: ese peso se mantiene dentro de los límites de la normalidad."]],
  "154": ["¿Qué abarca el acrónimo APGAR?",["Apariencia, pulso, gesto, actividad y respiración","Edad, peso, gestación, asistencia y reanimación","Apetito, postura, gases, apnea y reflejos"],["Exacto: la actividad corresponde al tono muscular.","Falso: esa serie no corresponde al puntaje descrito.","Falso: ninguno de esos ítems figura en el puntaje."]],
  "155": ["¿Qué busca la prueba del talón en el recién nacido?",["Enfermedades metabólicas","Una sordera congénita","Una displasia de cadera"],["Exacto: ese cribado neonatal se basa en un análisis de sangre.","Falso: esta se detecta mediante los potenciales auditivos.","Falso: esta se detecta clínicamente y después mediante ecografía."]],
  "156": ["¿Qué mide el inventario de rutinas domésticas en el niño pequeño?",["Participación, autonomía y relaciones","La fuerza muscular segmentaria","El cociente de desarrollo global del niño"],["Exacto: se aplica de cero a cinco años mediante una entrevista basada en las rutinas.","Falso: esa herramienta no evalúa la fuerza.","Falso: no es el objeto de esa herramienta."]],
  "157": ["¿Qué marco de referencia estructura la evaluación en neuropediatría?",["La clasificación internacional del funcionamiento","La clasificación internacional de enfermedades","La escala de medida de la independencia funcional"],["Exacto: articula estructuras, actividades, participación y factores contextuales.","Falso: esta codifica los diagnósticos, no el funcionamiento.","Falso: es una herramienta y no un marco de referencia."]],
  "158": ["¿Cuáles son los apartados de la evaluación fisioterápica en neuropediatría?",["Neurocinesiológico, ortopédico, respiratorio","Únicamente neurológico y psicológico","Musculoesquelético y respiratorio solamente"],["Exacto: el rendimiento funcional abarca la marcha y la función manual.","Falso: esa reducción deja de lado varios apartados.","Falso: el apartado neurocinesiológico es central."]],
  "159": ["¿Existe un consenso sobre la mejor exploración neurológica neonatal?",["No, la recomendación es dominar una de ellas","Sí, un protocolo es el de referencia","Sí, hay que combinar al menos tres"],["Exacto: coexisten varios protocolos sin superioridad demostrada de uno sobre otro.","Falso: no existe ningún consenso de ese tipo.","Falso: no se formula ninguna recomendación de ese tipo."]],
  "160": ["¿Qué comprende la evaluación neurocinesiológica del lactante?",["Motricidad, reacciones posturales y reflejos","Únicamente fuerza segmentaria y amplitudes articulares","Pruebas de neuroimagen y analítica"],["Exacto: a ello se añade la exploración del cráneo, del tórax, del raquis y de las caderas.","Falso: esas mediciones solo constituyen una parte de la valoración.","Falso: esas pruebas no corresponden a la evaluación fisioterápica."]],
  "161": ["¿Por qué se evalúan el tórax y el raquis en neuropediatría?",["Por su relación con la función pulmonar","Para detectar una displasia de cadera","Para medir el perímetro craneal"],["Exacto: la exploración del cráneo, por su parte, busca deformidades.","Falso: esta se busca en la cadera misma.","Falso: esa medición corresponde a la exploración del cráneo."]],
  "162": ["¿Qué anomalía se busca sistemáticamente en la cadera del lactante?",["Una displasia o una luxación","Una artritis séptica incipiente","Una osteocondrosis de la cabeza femoral"],["Exacto: esa exploración forma parte integrante de la valoración neurocinesiológica.","Falso: no es la anomalía que se busca de forma rutinaria.","Falso: esta atañe al niño de mayor edad."]],
  "163": ["¿En qué situación conserva el modelo biomédico todo su valor?",["En la fase aguda","En fase de rehabilitación prolongada","En prevención primaria poblacional"],["Exacto: se trata entonces de estabilizar y de tratar los síntomas.","Falso: es entonces el modelo biopsicosocial el que se impone.","Falso: no es el marco descrito."]],
  "164": ["¿Por qué se impone el modelo biopsicosocial en rehabilitación?",["Porque apunta en adelante a las secuelas","Porque permite curar la lesión inicial","Porque sustituye a la exploración clínica"],["Exacto: ya no se trata de curar la lesión inicial.","Falso: la curación de la lesión ya no es el objetivo.","Falso: estructura el análisis sin sustituir a la exploración."]],
  "165": ["¿A qué nivel de la clasificación corresponde una deficiencia?",["A las estructuras y funciones corporales","A las actividades de la vida diaria","A la participación social del paciente"],["Exacto: las actividades dan lugar a limitaciones y la participación a restricciones.","Falso: ese nivel da lugar a limitaciones.","Falso: ese nivel da lugar a restricciones."]],
  "166": ["¿Cómo se denomina un problema a nivel de las actividades?",["Una limitación","Una deficiencia","Una restricción"],["Exacto: a nivel de las estructuras se habla de deficiencia, y de la participación, de restricción.","Falso: ese término designa la afectación de las estructuras y funciones.","Falso: ese término designa la afectación de la participación."]],
  "167": ["¿Cómo se denomina un problema a nivel de la participación?",["Una restricción","Una limitación","Una deficiencia"],["Exacto: no poder vivir solo con seguridad es un ejemplo de ello.","Falso: ese término designa la afectación de las actividades.","Falso: ese término designa la afectación de las estructuras."]],
  "168": ["¿Cómo calificar una movilidad de la rodilla disminuida en este marco?",["Una deficiencia","Una limitación de la actividad","Una restricción de la participación"],["Exacto: afecta a la estructura y a la función corporales.","Falso: necesitar ayuda para levantarse de la cama sería una de ellas.","Falso: la imposibilidad de vivir solo sería una de ellas."]],
  "169": ["¿Qué puede ser un factor contextual en este marco?",["Un facilitador o una barrera","Únicamente una barrera que hay que superar","Únicamente un facilitador de la atención"],["Exacto: esos factores son a la vez ambientales y personales.","Falso: puede igualmente facilitar la situación.","Falso: puede igualmente obstaculizarla."]],
  "170": ["¿Qué es una deficiencia primaria?",["Un componente producido por la lesión","Una afectación aparecida secundariamente con el tiempo","Una afectación siempre definitiva e irreversible"],["Exacto: una gran hipotonía postural es un ejemplo de ello.","Falso: esa descripción es la de la deficiencia secundaria.","Falso: la durabilidad no entra en esa distinción."]],
  "171": ["¿Qué es una deficiencia secundaria?",["Una afectación desarrollada con el tiempo","Una afectación producida directamente por la lesión","Una afectación siempre temporal y reversible"],["Exacto: el dolor de hombro es el ejemplo clásico; puede ser temporal o permanente.","Falso: esa descripción es la de la deficiencia primaria.","Falso: también puede volverse permanente."]],
  "172": ["¿Qué signos componen el síndrome de la primera motoneurona?",["Espasticidad, clonus e hiperreflexia","Ataxia y disdiadococinesia","Temblor de reposo y bradicinesia marcada"],["Exacto: a ellos se añaden los patrones motores estereotipados.","Falso: esos signos sugieren una afectación cerebelosa.","Falso: esos signos sugieren un síndrome parkinsoniano."]],
  "173": ["¿Qué signos sugieren una lesión cerebelosa?",["Ataxia y disdiadococinesia","Espasticidad e hiperreflexia","Rigidez y bradicinesia"],["Exacto: la espasticidad y la hiperreflexia sugieren, al contrario, la primera motoneurona.","Falso: esos signos sugieren una afectación de la primera motoneurona.","Falso: esos signos sugieren un síndrome parkinsoniano."]],
  "174": ["¿Qué síntoma domina el cuadro de la esclerosis múltiple?",["La fatiga neurológica","La bradicinesia","La disdiadococinesia aislada"],["Exacto: se distingue de la fatiga muscular ordinaria.","Falso: ese signo sugiere un síndrome parkinsoniano.","Falso: ese signo orienta hacia una afectación cerebelosa."]],
  "175": ["¿Qué hay que vigilar en particular después de un traumatismo craneal?",["El estado de conciencia y la conducta","Únicamente la espasticidad de los miembros inferiores","Únicamente el temblor de reposo"],["Exacto: el control cefálico forma parte también de los puntos que hay que evaluar.","Falso: esa vigilancia resultaría muy insuficiente.","Falso: ese signo no es característico de ese cuadro."]],
  "176": ["¿Qué principio guía la observación del paciente neurológico?",["La manera de moverse tanto como la amplitud","Solo cuenta la amplitud del movimiento","Solo cuenta aquí verdaderamente la fuerza desarrollada"],["Exacto: la calidad del movimiento es tan informativa como su cantidad.","Falso: esa reducción hace perder lo esencial de la información.","Falso: la fuerza no resume la calidad del movimiento."]],
  "177": ["¿Por dónde comienza el razonamiento clínico en neurología?",["Por reconocer al paciente","Por plantear una hipótesis diagnóstica","Por elegir la técnica de rehabilitación"],["Exacto: después se relacionan las deficiencias con las limitaciones y se identifican sus objetivos.","Falso: la hipótesis viene después del reconocimiento y del análisis.","Falso: la elección técnica llega al final del proceso."]],
  "178": ["¿Qué cualidades deben tener los objetivos de rehabilitación?",["Específicos, realistas y medibles","Generales, ambiciosos y cualitativos","Idénticos para todos los pacientes afectados"],["Exacto: la reevaluación se realiza antes, durante y después de la intervención.","Falso: unos objetivos vagos no permiten ninguna evaluación.","Falso: deben ser individualizados."]],
  "179": ["¿Qué beneficio aportan unos objetivos ligados a las dificultades propias del paciente?",["Aumentan la implicación y la motivación","Acortan la duración total de las sesiones","Eximen de toda reevaluación"],["Exacto: evitan además las actividades inútiles.","Falso: no es el beneficio descrito.","Falso: la reevaluación sigue siendo indispensable."]],
  "180": ["¿Cuándo hay que reevaluar en rehabilitación neurológica?",["Antes, durante y después de la intervención","Solamente al final del abordaje","Solamente al principio, antes del tratamiento"],["Exacto: la reevaluación continua valida o corrige la hipótesis de partida.","Falso: esa única evaluación final sería demasiado tardía.","Falso: la evaluación inicial no basta."]],
  "181": ["¿En qué se asienta principalmente la neuroplasticidad?",["En las conexiones y la mielina","En la producción masiva de nuevas neuronas","En el aumento del número de células gliales"],["Exacto: a ello se añaden los cambios de los árboles dendríticos, y no la producción de nuevas neuronas.","Falso: la neurogénesis no es el mecanismo principal.","Falso: la glía sostiene el proceso sin ser su mecanismo central."]],
  "182": ["¿Qué es la plasticidad estructural?",["Cambios fisiológicos por aprendizaje y experiencia","La asunción de una función por otra zona","La conectividad entre áreas corticales y subcorticales"],["Exacto: la sinaptogénesis, la poda sináptica y la neurogénesis son sus formas.","Falso: esa descripción es la de la plasticidad funcional.","Falso: esa descripción es la de la plasticidad de red."]],
  "183": ["¿Qué es la plasticidad funcional?",["Una zona asume la función de una zona dañada","La creación de nuevas sinapsis por la experiencia","La conectividad entre la corteza y las estructuras profundas"],["Exacto: modifica la actividad o la eficacia de las redes existentes, a corto plazo.","Falso: esa descripción es la de la plasticidad estructural.","Falso: esa descripción es la de la plasticidad de red."]],
  "184": ["¿Qué forma de plasticidad corresponde a situaciones ambientales breves?",["La plasticidad reactiva","La plasticidad adaptativa","La plasticidad evolutiva"],["Exacto: la adaptativa produce cambios estructurales por aprendizaje.","Falso: produce cambios estructurales duraderos.","Falso: modifica las conexiones a largo plazo."]],
  "185": ["¿Qué forma de plasticidad permite la recuperación de funciones perdidas?",["La plasticidad reconstructiva","La plasticidad reactiva","La plasticidad evolutiva"],["Exacto: esa recuperación puede ser parcial o total.","Falso: responde a situaciones ambientales breves.","Falso: modifica las conexiones a largo plazo."]],
  "186": ["¿Qué les ocurre a las neuronas no activadas por la experiencia en el niño?",["No sobreviven","Quedan en reserva toda la vida","Se transforman en células gliales"],["Exacto: ese carácter competitivo explica trastornos como el ojo perezoso.","Falso: la regla es la del «usado o perdido».","Falso: no existe ninguna transformación de ese tipo."]],
  "187": ["¿Dónde se ha demostrado la neurogénesis del adulto?",["En el hipocampo y el bulbo olfatorio","En la corteza motora primaria","En el cerebelo y el tronco cerebral"],["Exacto: las nuevas neuronas proceden de la capa de ependimocitos.","Falso: esa localización no es la que se ha demostrado.","Falso: esas estructuras no están implicadas."]],
  "188": ["¿Qué es la degeneración anterógrada?",["Una afectación distal con respecto a la lesión","Una afectación que asciende hacia el cuerpo celular","Un refuerzo de las conexiones restantes"],["Exacto: la forma retrógrada asciende, al contrario, hacia el cuerpo celular.","Falso: esa descripción es la de la degeneración retrógrada.","Falso: esa descripción corresponde a la reorganización."]],
  "189": ["¿Existe la regeneración en el sistema nervioso central del adulto?",["No, es inexistente en el adulto","Sí, es allí tan eficaz como en la periferia","Sí, pero solo antes de los veinte años"],["Exacto: existe en el sistema nervioso periférico, sin funcionar siempre en él.","Falso: allí está ausente.","Falso: no se describe ningún límite de edad de ese tipo."]],
  "190": ["¿Mediante qué mecanismo se produce la reorganización después de una lesión?",["Mediante brotes colaterales de los axones sanos","Mediante el rebrote directo del axón seccionado","Mediante la producción de nuevas neuronas corticales"],["Exacto: las conexiones existentes se refuerzan y se crean otras nuevas.","Falso: la regeneración central no existe en el adulto.","Falso: la neurogénesis del adulto no atañe a la corteza."]],
  "191": ["¿Cuántas veces más numerosa es la neuroglía que las neuronas?",["De cinco a diez veces más numerosa","Unas dos veces más numerosa","Cien veces más"],["Exacto: tiene además una capacidad de división ilimitada.","Falso: la proporción es bastante superior.","Falso: esa proporción está muy sobreestimada."]],
  "192": ["¿Qué papel desempeña la neuroglía después de una lesión?",["Forma la cicatriz glial","Regenera directamente los axones","Produce nuevas neuronas corticales"],["Exacto: modula además la actividad sináptica y regula la sinaptogénesis.","Falso: no tiene lugar ninguna regeneración central.","Falso: no es su papel."]],
  "193": ["¿Cuál es la secuencia de la cascada lesional?",["Hipoxia, pérdida del gradiente, calcio, muerte","Entrada de calcio, luego isquemia, luego rotura vascular","Muerte celular, luego caída de la glucosa, luego isquemia"],["Exacto: la rotura vascular o la isquemia es su punto de partida.","Falso: el orden de los acontecimientos está invertido.","Falso: esa secuencia es imposible."]],
  "194": ["¿Qué proteína liberada después de una lesión facilita la sinaptogénesis?",["La proteína GAP-43","La proteína tau fosforilada","La proteína beta-amiloide"],["Exacto: forma parte de la química que modula el potencial de recuperación.","Falso: está asociada a las enfermedades neurodegenerativas.","Falso: no interviene en ese proceso."]],
  "195": ["¿Cuáles son los signos iniciales negativos después de una lesión central?",["Hipotonía, hiporreflexia e hipoestesia","Espasticidad, hiperreflexia y clonus","Temblor, rigidez y bradicinesia"],["Exacto: la espasticidad y las reacciones asociadas aparecen más tarde.","Falso: esos signos positivos son más tardíos.","Falso: esos signos sugieren un síndrome parkinsoniano."]],
  "196": ["¿Qué es el diasquisis?",["Cambios a distancia de la lesión","Una degeneración distal a la lesión","Una cicatriz glial que rodea la lesión"],["Exacto: se desprende del funcionamiento en red y de una desactivación general.","Falso: esa descripción es la de la degeneración anterógrada.","Falso: esa formación es local y no a distancia."]],
  "197": ["¿Qué es la plasticidad intermodal?",["La pérdida de un sentido mejora los demás","Una zona sana asume la función perdida","Los dos hemisferios intercambian sus funciones"],["Exacto: las personas ciegas activan la corteza visual al leer mediante el tacto.","Falso: esa descripción es la de la plasticidad funcional.","Falso: no es el fenómeno descrito."]],
  "198": ["¿Es la plasticidad intermodal siempre beneficiosa?",["No, es inadecuada en el hemipléjico","Sí, mejora siempre el rendimiento","Sí, salvo en la persona mayor"],["Exacto: en él limita la recuperación óptima, mientras que es adaptativa en la persona sorda o ciega.","Falso: puede, al contrario, perjudicar la recuperación.","Falso: la edad no es el criterio determinante."]],
  "199": ["¿Qué se puede decir de una reorganización contralateral a la lesión?",["Es menos eficaz para la motricidad fina","Es siempre la mejor solución posible","No existe después de una lesión cortical"],["Exacto: le cuesta preservar la especialización funcional.","Falso: su eficacia es, al contrario, limitada.","Falso: está, al contrario, bien documentada."]],
  "200": ["¿Cuál de estos factores de plasticidad es modificable?",["El sueño y el descanso","La localización de la lesión","La extensión de la lesión inicial"],["Exacto: la alimentación, la actividad física, la motivación y el entorno lo son igualmente.","Falso: forma parte de los factores no modificables.","Falso: tampoco es modificable."]],
  "201": ["¿Cuál de estos factores de plasticidad es poco o nada modificable?",["La genética del paciente","La motivación y el estado emocional","El tipo y la duración del tratamiento"],["Exacto: la gravedad, el tipo, la localización y la extensión de la lesión lo son igual de poco.","Falso: esos factores son modificables.","Falso: esos parámetros están en manos del profesional."]],
  "202": ["¿Qué produce la ausencia de rehabilitación durante varias semanas?",["Un aprendizaje del no uso","Una recuperación espontánea más completa","Una plasticidad adaptativa reforzada"],["Exacto: la representación cortical del miembro se empobrece.","Falso: la inacción empobrece la representación cortical.","Falso: lo que se produce es lo contrario."]],
  "203": ["¿Qué efecto tiene el uso excesivo del miembro sano después de un accidente cerebrovascular?",["Inhibe la recuperación del miembro afectado","Acelera la recuperación del miembro afectado","No tiene efecto alguno sobre la recuperación"],["Exacto: reduce la necesidad de emplear el lado afectado.","Falso: el efecto es exactamente el inverso.","Falso: su efecto perjudicial está documentado."]],
  "204": ["¿Qué se puede decir de las estrategias compensatorias precoces?",["Son más difíciles de reorientar después","Hay que proscribirlas siempre de forma absoluta","Facilitan siempre la recuperación posterior"],["Exacto: la compensación no es, sin embargo, negativa en sí misma: todo depende del contexto.","Falso: su valor depende de la duración, del tipo de lesión y del contexto.","Falso: pueden, al contrario, estorbarla."]],
  "205": ["¿Qué síntomas tardíos corresponden a una plasticidad inadecuada?",["Reacciones asociadas y espasticidad","Hipotonía, hiporreflexia e hipoestesia","Ataxia y disdiadococinesia cerebelosas"],["Exacto: no son la evolución natural de la lesión.","Falso: esos signos son iniciales y no tardíos.","Falso: esos signos corresponden a una afectación cerebelosa directa."]],
  "206": ["¿Qué significa el principio de especificidad en neuroplasticidad?",["El entrenamiento reproduce la conducta buscada","Cada paciente necesita un protocolo único","Cada lesión da un cuadro específico"],["Exacto: un entrenamiento genérico se transfiere mal a la tarea diana.","Falso: no es el sentido del principio.","Falso: ese principio se refiere al entrenamiento, no a la lesión."]],
  "207": ["¿Qué abarca el principio de intensidad en neuroplasticidad?",["Un entrenamiento exigente sin fatiga","El mayor número posible de repeticiones","La mayor duración posible de la sesión"],["Exacto: la fatiga excesiva anula el beneficio buscado.","Falso: la repetición es un principio distinto.","Falso: la duración es otro principio."]],
  "208": ["¿Qué dice el principio de duración en neuroplasticidad?",["Empezar pronto es mejor, pero nada está perdido","Más allá de los seis meses ya no es posible ningún progreso","El momento del inicio no tiene ninguna importancia"],["Exacto: ese matiz justifica no renunciar nunca a rehabilitar.","Falso: persiste un potencial en fase crónica.","Falso: la precocidad sigue siendo una ventaja."]],
  "209": ["¿Qué dice el principio de edad en neuroplasticidad?",["Los adultos conservan su plasticidad","La plasticidad desaparece después de los veinte años","Solo los niños pueden recuperarse"],["Exacto: la plasticidad no está reservada a la infancia.","Falso: persiste a cualquier edad.","Falso: esa afirmación queda desmentida por los datos."]],
  "210": ["¿Qué significa el principio de importancia emocional?",["Las tareas que tienen un sentido se aprenden mejor","Hay que evitar toda emoción durante la sesión","Solo las emociones negativas son eficaces"],["Exacto: la motivación y la recompensa refuerzan el aprendizaje.","Falso: la emoción es, al contrario, una palanca.","Falso: no es lo que describe el principio."]],
  "211": ["¿Qué caracteriza a una rehabilitación óptima?",["Una participación activa y un verdadero reto","Un número muy grande de repeticiones pasivas","Sesiones cortas y muy espaciadas"],["Exacto: la simple acumulación de repeticiones no basta.","Falso: la pasividad limita mucho el beneficio.","Falso: se busca la intensidad a lo largo de un periodo prolongado."]],
  "212": ["¿Qué elementos del estilo de vida hay que integrar en la rehabilitación?",["Sueño, alimentación y actividad física","Únicamente la intensidad de los ejercicios propuestos","Únicamente la duración total del programa"],["Exacto: forman parte de los factores modificables de la plasticidad.","Falso: esa reducción olvida los factores del estilo de vida.","Falso: la duración por sí sola no basta."]],
  "213": ["¿Qué abarca la plasticidad de red?",["La conectividad entre áreas corticales y subcorticales","La creación de nuevas sinapsis locales","La asunción de una función por una zona sana"],["Exacto: se añade a las plasticidades estructural y funcional.","Falso: esa descripción corresponde a la plasticidad estructural.","Falso: esa descripción corresponde a la plasticidad funcional."]],
  "214": ["¿Qué es la plasticidad evolutiva?",["Conexiones modificadas a largo plazo","Una respuesta breve al entorno","La recuperación de funciones perdidas"],["Exacto: se distingue de las formas reactiva, adaptativa y reconstructiva.","Falso: esa descripción es la de la forma reactiva.","Falso: esa descripción es la de la forma reconstructiva."]],
  "215": ["¿Qué mecanismo explica el trastorno del ojo perezoso?",["El carácter competitivo de las conexiones","Una degeneración retiniana primitiva","Una ausencia congénita de vías visuales"],["Exacto: las vías no estimuladas pierden su lugar en beneficio de las demás.","Falso: el mecanismo descrito es central y competitivo.","Falso: las vías existen, pero no están estimuladas."]],
  "216": ["¿Qué demuestra la reorganización de los mapas sensitivos en el adulto?",["Que la experiencia remodela los mapas","Que la corteza del adulto está definitivamente fijada","Que solo los niños tienen mapas modificables"],["Exacto: los mapas motores se reorganizan de la misma manera.","Falso: esa concepción está precisamente superada.","Falso: la reorganización del adulto está demostrada."]],
  "217": ["¿Cuál es el punto de partida de la cascada lesional?",["Una rotura vascular o una isquemia","Una entrada masiva de calcio celular","La formación de una cicatriz glial"],["Exacto: conlleva la caída del oxígeno y de la glucosa.","Falso: esa entrada es una etapa posterior.","Falso: sobreviene mucho más tarde."]],
  "218": ["¿Por qué deja de mantenerse el gradiente transmembrana después de una isquemia?",["Porque faltan el oxígeno y la glucosa","Porque la cicatriz glial bloquea los intercambios","Porque la mielina se degrada de inmediato"],["Exacto: las bombas iónicas ya no reciben energía.","Falso: se forma mucho más tarde.","Falso: no es el mecanismo invocado."]],
  "219": ["¿Qué abarcan los principios de transferencia y de interferencia?",["Un aprendizaje favorece o estorba a otro","Un aprendizaje nunca atañe más que a una sola tarea","Un aprendizaje borra siempre el anterior"],["Exacto: completan los otros ocho principios de neuroplasticidad aplicada.","Falso: la transferencia supone justamente un efecto más allá de la tarea.","Falso: la interferencia no es ni sistemática ni total."]],
  "220": ["¿Cuál es la definición de la neuroplasticidad?",["La capacidad del sistema nervioso de reorganizarse","La capacidad del sistema nervioso de regenerar sus axones","La capacidad del sistema nervioso de producir neuronas"],["Exacto: atañe a su estructura, su función y sus conexiones.","Falso: la regeneración central no existe en el adulto.","Falso: no es el mecanismo principal."]],
  "221": ["¿Cómo se define el tono muscular?",["La resistencia pasiva del músculo en reposo","La fuerza máxima desarrollada voluntariamente","La velocidad de contracción del músculo explorado"],["Exacto: es la tensión de base que mantiene al músculo listo para la acción.","Falso: esa medida es la de la fuerza, no la del tono.","Falso: esa medida no define el tono."]],
  "222": ["¿Cuáles son los dos componentes del tono muscular?",["Un componente neural y un componente viscoelástico","Un componente voluntario y un componente reflejo","Un componente agonista y un componente antagonista"],["Exacto: el primero es reflejo, el segundo depende de las propiedades del tejido.","Falso: el tono de reposo no tiene componente voluntario.","Falso: esa división no corresponde a los componentes descritos."]],
  "223": ["¿Qué estructuras regulan el tono muscular?",["Vías descendentes, núcleos grises y cerebelo","Únicamente la corteza motora primaria","Únicamente los nervios periféricos motores"],["Exacto: los reflejos espinales, entre ellos el reflejo de estiramiento, participan igualmente en ello.","Falso: esa reducción olvida varios niveles de regulación.","Falso: la regulación es en gran medida central."]],
  "224": ["¿Qué define la espasticidad?",["Un aumento del tono dependiente de la velocidad","Un aumento del tono independiente de la velocidad","Una disminución del tono con hiporreflexia"],["Exacto: se acompaña de reflejos tendinosos exagerados y predomina en los músculos antigravitatorios.","Falso: esa característica es la de la rigidez.","Falso: esa descripción es la de la hipotonía."]],
  "225": ["¿Cuál es el origen de la espasticidad?",["Corticoespinal, por afectación de la motoneurona superior","De los ganglios basales, como en la enfermedad de Parkinson","Cerebeloso, por pérdida de la coordinación"],["Exacto: la rigidez proviene, al contrario, de los ganglios basales.","Falso: ese origen es el de la rigidez.","Falso: la afectación cerebelosa da una ataxia."]],
  "226": ["¿Qué músculos afecta preferentemente la espasticidad?",["Los músculos antigravitatorios","Los agonistas y los antagonistas por igual","Únicamente los músculos distales de los miembros"],["Exacto: la rigidez afecta, al contrario, a agonistas y antagonistas indistintamente.","Falso: esa distribución caracteriza a la rigidez.","Falso: la distribución no es la descrita."]],
  "227": ["¿Qué fenómeno caracteriza a la espasticidad en la movilización?",["El fenómeno de la navaja","El fenómeno de la rueda dentada","El fenómeno del tubo de plomo"],["Exacto: una resistencia inicial cede de forma brusca.","Falso: ese fenómeno caracteriza a la rigidez.","Falso: caracteriza igualmente a la rigidez."]],
  "228": ["¿Qué define la rigidez?",["Un aumento del tono independiente de la velocidad","Un aumento del tono dependiente de la velocidad","Una resistencia que cede bruscamente al final del recorrido"],["Exacto: afecta a agonistas y antagonistas, con un reflejo de estiramiento normal o poco aumentado.","Falso: esa dependencia caracteriza a la espasticidad.","Falso: esa descripción es la del fenómeno de la navaja."]],
  "229": ["¿Cuál es el estado del reflejo de estiramiento en la rigidez?",["Normal o poco aumentado","Muy intensamente aumentado","Completamente abolido"],["Exacto: la espasticidad se acompaña, al contrario, de una franca hiperreflexia.","Falso: esa hiperreflexia caracteriza a la espasticidad.","Falso: la abolición sugeriría una afectación periférica."]],
  "230": ["¿Cómo se considera hoy la espasticidad?",["Un componente del síndrome piramidal","Como un síntoma aislado e independiente","Como una afectación puramente muscular local"],["Exacto: al igual que la debilidad, el clonus y los cambios tisulares.","Falso: se integra en un síndrome más amplio.","Falso: su origen es central."]],
  "231": ["¿Qué describe el grado 1 de la escala de Ashworth modificada?",["Una resistencia mínima al final de la amplitud","Una resistencia en menos de la mitad de la amplitud","Una ausencia total de aumento del tono"],["Exacto: el grado 1 más extiende esa resistencia a menos de la mitad de la amplitud.","Falso: esa descripción corresponde al grado 1 más.","Falso: esa situación corresponde al grado 0."]],
  "232": ["¿Qué describe el grado 2 de la escala de Ashworth modificada?",["Un aumento marcado pero el segmento se mueve con facilidad","Un aumento que hace difícil el movimiento pasivo","Un segmento rígido en flexión o en extensión"],["Exacto: en el grado 3 el movimiento pasivo se vuelve difícil.","Falso: esa descripción corresponde al grado 3.","Falso: esa descripción corresponde al grado 4."]],
  "233": ["¿Qué describe el grado 4 de la escala de Ashworth modificada?",["Un segmento rígido en flexión o en extensión","Un aumento marcado con movilización fácil","Una resistencia mínima al final de la amplitud"],["Exacto: es el grado más severo de la escala.","Falso: esa descripción corresponde al grado 2.","Falso: esa descripción corresponde al grado 1."]],
  "234": ["¿Qué distingue a la escala de Tardieu de la de Ashworth?",["Tiene en cuenta la velocidad de estiramiento","Solo puntúa la amplitud articular pasiva","Se aplica únicamente a los miembros inferiores"],["Exacto: es su diferencia esencial, que permite aislar el componente dinámico.","Falso: puntúa también la calidad de la respuesta.","Falso: su empleo no se limita a un segmento."]],
  "235": ["¿Qué mide la velocidad V1 en la escala de Tardieu?",["La amplitud pasiva máxima","El ángulo de captura, anotado R1","La velocidad de caída por gravedad"],["Exacto: la velocidad V3, la más rápida, da el ángulo de captura R1.","Falso: ese ángulo se obtiene a la velocidad V3.","Falso: esa velocidad es V2."]],
  "236": ["¿Qué da la velocidad V3 en la escala de Tardieu?",["El ángulo de captura, anotado R1","La amplitud pasiva máxima, anotada R2","La velocidad de caída del segmento por gravedad"],["Exacto: es la velocidad más rápida posible.","Falso: esta se obtiene a la velocidad V1, muy lenta.","Falso: esa velocidad es V2."]],
  "237": ["¿Qué representa la diferencia entre R2 y R1?",["El componente dinámico de la espasticidad","El componente viscoelástico del músculo","La amplitud articular activa disponible"],["Exacto: más allá de los treinta grados, ese componente se considera elevado.","Falso: este no queda aislado por ese cálculo.","Falso: la escala de Tardieu explora el movimiento pasivo."]],
  "238": ["¿A partir de qué valor se juzga elevado el componente dinámico?",["Más allá de los treinta grados","Más allá de los diez grados","Más allá de los sesenta grados"],["Exacto: ese valor corresponde a la diferencia entre R2 y R1.","Falso: ese umbral es demasiado bajo.","Falso: ese umbral es demasiado elevado."]],
  "239": ["¿Qué describe la puntuación 2 de la respuesta cualitativa de Tardieu?",["Un enganche claro seguido de una relajación","Una contracción clónica o fatigable","Una resistencia ligera sin enganche"],["Exacto: la puntuación 3 corresponde a una contracción clónica o fatigable.","Falso: esa respuesta corresponde a la puntuación 3.","Falso: esa respuesta corresponde a la puntuación 1."]],
  "240": ["¿Qué describe la puntuación 4 de la respuesta cualitativa de Tardieu?",["Una contracción mantenida por debajo de los diez grados","Una contracción clónica o fatigable","Un enganche seguido de una relajación nítida"],["Exacto: es la respuesta más severa de la escala.","Falso: esa respuesta corresponde a la puntuación 3.","Falso: esa respuesta corresponde a la puntuación 2."]],
  "241": ["¿Qué mide la dinamometría isocinética?",["El momento de fuerza, a varias velocidades constantes","La actividad eléctrica de las unidades motoras","La amplitud articular pasiva máxima"],["Exacto: complementa a la electromiografía de superficie en la evaluación del tono.","Falso: esa medida corresponde a la electromiografía.","Falso: esa medida corresponde a la valoración goniométrica."]],
  "242": ["¿Qué exploración separa el componente neural del componente viscoelástico?",["La electromiografía de superficie","La dinamometría isocinética","La escala de Ashworth modificada"],["Exacto: identifica además los patrones de cocontracción.","Falso: mide el momento de fuerza sin distinguir ambos componentes.","Falso: esa escala es puramente clínica."]],
  "243": ["¿Cómo se caracteriza el tono postural?",["Una activación difusa de bajo nivel","Una contracción máxima de algunos músculos clave","Una ausencia completa de actividad en reposo"],["Exacto: contrarresta la gravedad y prepara los ajustes anticipados y reactivos.","Falso: la activación es, al contrario, difusa y de baja intensidad.","Falso: siempre persiste una actividad de fondo."]],
  "244": ["¿De qué depende el tono postural?",["De la gravedad, de la postura y del apoyo","Únicamente de la fuerza máxima del paciente","Únicamente de la velocidad de movilización pasiva"],["Exacto: la anchura, la firmeza y la naturaleza de la superficie lo modifican.","Falso: la fuerza no determina el tono postural.","Falso: esa dependencia caracteriza a la espasticidad."]],
  "245": ["¿Qué vía transporta la sensibilidad superficial consciente?",["El sistema espinotalámico","Las columnas dorsales y el lemnisco medial","Los sistemas espinocerebelosos"],["Exacto: transporta el tacto, el dolor y la temperatura.","Falso: transportan la sensibilidad profunda consciente.","Falso: transportan la propiocepción inconsciente."]],
  "246": ["¿Qué vía transporta la propiocepción consciente?",["Las columnas dorsales y el lemnisco medial","El sistema espinotalámico anterolateral","Los sistemas espinocerebelosos cruzados"],["Exacto: transportan también la vibración y la presión profunda.","Falso: transporta la sensibilidad superficial.","Falso: transportan la propiocepción inconsciente."]],
  "247": ["¿Qué regulan los sistemas espinocerebelosos?",["El tono postural y el automatismo","La percepción consciente del dolor","La discriminación táctil fina de los dedos"],["Exacto: ajustan igualmente los reflejos posturales.","Falso: esta pasa por el sistema espinotalámico.","Falso: esta pasa por las columnas dorsales."]],
  "248": ["¿Qué receptores informan de la sensibilidad profunda consciente?",["Los husos y los órganos de Golgi","Las terminaciones libres cutáneas","Los graviceptores viscerales abdominales"],["Exacto: informan sobre la posición, la vibración y la presión profunda.","Falso: transportan la sensibilidad superficial.","Falso: informan sobre el desplazamiento del peso."]],
  "249": ["¿Qué comprende el apartado superficial de la evaluación sensitiva de Nottingham?",["Algodón, alfiler y tubos de temperatura","Discriminación de dos puntos y estereognosia","Movimiento pasivo de un dedo con imitación"],["Exacto: el apartado profundo explora la posición de un dedo movilizado pasivamente.","Falso: esas pruebas corresponden al apartado cortical.","Falso: esa prueba corresponde al apartado profundo."]],
  "250": ["¿Qué comprende el apartado cortical de la evaluación sensitiva de Nottingham?",["Discriminación de dos puntos, estereognosia y grafestesia","Algodón, alfiler y tubos de temperatura","Movimiento pasivo de un dedo con indicación de la posición"],["Exacto: esas pruebas exploran la integración cortical de la información.","Falso: esas pruebas corresponden al apartado superficial.","Falso: esa prueba corresponde al apartado profundo."]],
  "251": ["¿Cómo se aplica un monofilamento de Semmes-Weinstein?",["Perpendicularmente, hasta que se dobla","Oblicuamente, sin dejar que se doble nunca","Barriendo la piel de forma continua"],["Exacto: el grosor mínimo detectado marca el umbral de sensibilidad.","Falso: el doblado calibra con precisión la fuerza aplicada.","Falso: la aplicación debe ser puntual y perpendicular."]],
  "252": ["¿Qué determina el compás de Weber?",["La distancia mínima reconocida entre dos puntos","El umbral de percepción de un pinchazo","La capacidad de reconocer un objeto al tacto"],["Exacto: esa distancia define el umbral de discriminación táctil.","Falso: esa medida corresponde a la prueba del alfiler.","Falso: esa capacidad es la estereognosia."]],
  "253": ["¿Qué es la estereognosia?",["El reconocimiento de objetos al tacto","El reconocimiento de una cifra trazada sobre la piel","La percepción de dos puntos distintos"],["Exacto: forma parte del apartado cortical de la evaluación sensitiva.","Falso: esa capacidad es la grafestesia.","Falso: esa capacidad se mide con el compás."]],
  "254": ["¿Qué es el sentido de la posición articular?",["Reconocer una posición sin verla","Detectar la dirección de un movimiento pasivo","Reconocer un objeto colocado en la mano"],["Exacto: la cinestesia, por su parte, detecta la dirección y la velocidad de un movimiento pasivo.","Falso: esa capacidad es la cinestesia.","Falso: esa capacidad es la estereognosia."]],
  "255": ["¿Qué es la cinestesia?",["Reconocer una posición sin verla","Detectar la dirección de un movimiento pasivo","Percibir la presión ejercida sobre la piel"],["Exacto: es sensible a las lesiones de los cordones posteriores y a las neuropatías.","Falso: esa capacidad es el sentido de la posición articular.","Falso: esa capacidad corresponde a la sensibilidad superficial."]],
  "256": ["¿A qué lesiones es particularmente sensible la cinestesia?",["A las afectaciones de los cordones posteriores","A las afectaciones del sistema espinotalámico","A las afectaciones de los ganglios basales"],["Exacto: las neuropatías periféricas la alteran igualmente.","Falso: este transporta la sensibilidad superficial.","Falso: estas dan más bien una rigidez."]],
  "257": ["¿En qué consiste la prueba de mantenimiento, llamada holding?",["El terapeuta coloca el segmento y el paciente lo mantiene","El terapeuta coloca el segmento contralateral que hay que reproducir","El paciente desplaza activamente su segmento afectado"],["Exacto: después se retira la ayuda y se observa el tiempo de mantenimiento.","Falso: esa consigna es la del placing.","Falso: no es el protocolo descrito."]],
  "258": ["¿En qué consiste la prueba de colocación, llamada placing?",["El paciente reproduce la posición mostrada","El terapeuta coloca el segmento afectado que hay que mantener","El paciente mantiene una postura global de pie"],["Exacto: el terapeuta ha colocado primero el segmento contralateral.","Falso: esa consigna es la del holding.","Falso: no es el protocolo descrito."]],
  "259": ["¿Qué tiempo de mantenimiento sirve de referencia en estas pruebas?",["De cinco a diez segundos","De uno a dos segundos","De treinta a sesenta segundos"],["Exacto: se observan además la deriva postural y las compensaciones.","Falso: esa duración es insuficiente para concluir.","Falso: esa duración supera con mucho la referencia."]],
  "260": ["¿Qué se observa además del tiempo de mantenimiento en estas pruebas?",["La deriva postural y las compensaciones","La fuerza máxima isométrica desarrollada","La amplitud articular pasiva del segmento"],["Exacto: se anotan también la necesidad de ayuda manual y la respuesta a las pequeñas perturbaciones.","Falso: la fuerza no es el objeto de la prueba.","Falso: esa medida corresponde a otra valoración."]],
  "261": ["¿Qué cualidad explora la prueba del alfiler?",["La sensibilidad superficial al dolor","La propiocepción consciente profunda","La discriminación cortical de dos puntos"],["Exacto: pertenece al apartado superficial, junto con el algodón y los tubos de temperatura.","Falso: esta se explora mediante el movimiento pasivo.","Falso: esta se mide con el compás."]],
  "262": ["¿Cómo puede responder el paciente en la prueba de sensibilidad profunda?",["Indicando la posición o imitándola","Nombrando el objeto colocado en su mano","Contando los puntos de contacto percibidos"],["Exacto: el terapeuta moviliza pasivamente un dedo, fuera del campo visual.","Falso: esa prueba es la de la estereognosia.","Falso: esa prueba es la de la discriminación."]],
  "263": ["¿Por dónde comienza la construcción de una escala de medida?",["Por la identificación del concepto que se va a medir","Por la generación de los ítems del cuestionario","Por la prueba piloto con pacientes"],["Exacto: después se define la población y luego se generan los ítems.","Falso: esa etapa viene después de la definición del concepto y de la población.","Falso: la prueba piloto interviene mucho más tarde."]],
  "264": ["¿Qué etapa sigue a la generación de los ítems de una escala?",["La validación de contenido por expertos","La identificación del concepto que se va a medir","La publicación del artículo original"],["Exacto: la prueba piloto y la evaluación psicométrica vienen después.","Falso: esa etapa, al contrario, abre el proceso.","Falso: la publicación cierra el proceso."]],
  "265": ["¿Qué significa la validez de una escala?",["Mide realmente lo que pretende medir","Da resultados reproducibles","Detecta los cambios a lo largo del tiempo"],["Exacto: la fiabilidad designa, por su parte, la reproducibilidad de las mediciones.","Falso: esa propiedad es la fiabilidad.","Falso: esa propiedad es la sensibilidad."]],
  "266": ["¿Qué se debe observar entre dos escalas que miden aspectos próximos?",["Una correlación positiva","Una correlación negativa","Una ausencia total de correlación"],["Exacto: es el principio de la validez conceptual convergente.","Falso: esa relación señalaría, al contrario, un problema.","Falso: la independencia iría contra la validez convergente."]],
  "267": ["¿Qué abarca la validez predictiva?",["La probabilidad de que sobrevenga un acontecimiento","La concordancia con una medida actual","La opinión de expertos sobre el contenido de los ítems"],["Exacto: el riesgo de caída es el ejemplo más corriente.","Falso: esa propiedad es la validez concurrente.","Falso: esa propiedad es la validez de contenido."]],
  "268": ["¿De qué depende el umbral de una escala predictiva?",["De la población estudiada","Del número de ítems de la escala","De la experiencia del examinador"],["Exacto: un mismo valor puede significar riesgos muy diferentes según el grupo.","Falso: el número de ítems no fija el umbral.","Falso: el umbral es una propiedad de la herramienta y de la población."]],
  "269": ["¿Qué significa la fiabilidad de una escala?",["Mediciones repetidas dan el mismo resultado","La escala mide realmente el concepto buscado","La escala detecta los pequeños cambios"],["Exacto: se declina en fiabilidad inter e intraobservador.","Falso: esa propiedad es la validez.","Falso: esa propiedad es la sensibilidad."]],
  "270": ["¿Qué es la fiabilidad intraobservador?",["El mismo examinador mide en dos momentos","Dos examinadores diferentes miden","Se comparan dos escalas diferentes"],["Exacto: la fiabilidad interobservadores compara dos examinadores diferentes.","Falso: esa situación define la fiabilidad interobservadores.","Falso: esa comparación corresponde a la validez."]],
  "271": ["¿Qué mide la sensibilidad de una escala?",["Su capacidad de detectar el cambio","Su capacidad de medir el concepto adecuado","Su reproducibilidad de una vez a otra"],["Exacto: es en ese punto donde el índice de Barthel falla.","Falso: esa propiedad es la validez.","Falso: esa propiedad es la fiabilidad."]],
  "272": ["¿Cuántos ítems comprende el índice de Barthel?",["Diez","Dieciocho","Catorce"],["Exacto: la medida de independencia funcional comprende dieciocho.","Falso: ese número es el de la medida de independencia funcional.","Falso: ese número es el de la escala de equilibrio de Berg."]],
  "273": ["¿Por qué es poco sensible el índice de Barthel?",["Su puntuación se hace por tramos amplios","Comprende demasiados ítems que hay que cumplimentar","Abarca la comunicación y la cognición"],["Exacto: los valores cero, cinco, diez y quince solo detectan los grandes cambios.","Falso: solo comprende diez.","Falso: es la medida de independencia funcional la que las abarca."]],
  "274": ["¿Qué amplitud de puntuación emplea la medida de independencia funcional?",["De uno a siete por ítem","De cero a quince por ítem","De cero a dos por ítem"],["Exacto: esa finura le da una sensibilidad superior a la del índice de Barthel.","Falso: esa puntuación es la del índice de Barthel.","Falso: esa puntuación es la del Mini-BESTest."]],
  "275": ["¿Qué ámbitos adicionales abarca la medida de independencia funcional?",["La comunicación y la cognición social","El equilibrio estático y dinámico","La calidad de vida percibida por el paciente"],["Exacto: el índice de Barthel se limita a las actividades físicas básicas.","Falso: esos ámbitos corresponden a las escalas de equilibrio.","Falso: ese ámbito corresponde a herramientas específicas."]],
  "276": ["¿Qué es el cambio mínimo detectable?",["El cambio que distingue el efecto del error","El cambio mínimo percibido como útil por el paciente","La variación más pequeña posible de la escala"],["Exacto: la diferencia mínima clínicamente importante se refiere, por su parte, a la vivencia del paciente.","Falso: esa definición es la de la diferencia clínicamente importante.","Falso: no se trata de una propiedad aritmética de la escala."]],
  "277": ["¿Qué es la diferencia mínima clínicamente importante?",["Una mejoría significativa para el paciente","El umbral más allá del cual se excluye el error de medida","La variación media observada en la población"],["Exacto: a menudo es superior al cambio mínimo detectable.","Falso: esa definición es la del cambio mínimo detectable.","Falso: no es la definición que se considera."]],
  "278": ["Un paciente pasa de treinta y dos a treinta y seis en una escala cuyo cambio detectable es de seis. ¿Qué cabe concluir?",["No se puede afirmar que haya habido un cambio real","El cambio es real y clínicamente útil","El cambio es real pero sin repercusión funcional"],["Exacto: la progresión de cuatro puntos queda por debajo del umbral de error de medida.","Falso: ni siquiera alcanza el umbral de detectabilidad.","Falso: esa conclusión supone haber superado el umbral de detectabilidad."]],
  "279": ["Un paciente progresa seis puntos en una escala cuyo cambio detectable es seis y la diferencia importante siete. ¿Qué cabe concluir?",["Un cambio real, sin repercusión funcional","El cambio sigue correspondiendo al error de medida","El cambio es clínicamente importante"],["Exacto: supera el error de medida sin alcanzar la relevancia clínica.","Falso: alcanza exactamente el umbral de detectabilidad.","Falso: sigue siendo inferior al umbral de relevancia clínica."]],
  "280": ["¿Qué es un efecto techo?",["Demasiados pacientes están en la puntuación máxima","Demasiados pacientes están en la puntuación mínima","La escala comprende demasiado pocos ítems"],["Exacto: la escala deja entonces de detectar las mejorías.","Falso: esa situación define el efecto suelo.","Falso: no es la definición de ese efecto."]],
  "281": ["¿Qué es un efecto suelo?",["Demasiados pacientes están en la puntuación mínima","Demasiados pacientes están en la puntuación máxima","La escala resulta demasiado larga de administrar"],["Exacto: la escala deja entonces de detectar los empeoramientos.","Falso: esa situación define el efecto techo.","Falso: la duración de administración no entra en esa definición."]],
  "282": ["¿Por qué evita el efecto suelo la escala postural para el accidente cerebrovascular?",["Comienza en decúbito supino","Comienza en bipedestación","Comprende muy pocos ítems"],["Exacto: detecta los pequeños pasos del tumbado al lateral y después al sentado.","Falso: semejante punto de partida crearía, al contrario, un efecto suelo.","Falso: el número de ítems no está en cuestión."]],
  "283": ["¿Por qué presenta un efecto suelo la escala de equilibrio de Berg?",["Parte del sentado sin respaldo","Comienza en decúbito supino","Solo comprende ítems de pie"],["Exacto: un paciente que no lo consigue obtiene cero.","Falso: es la escala postural la que empieza así.","Falso: comprende también ítems sentado."]],
  "284": ["¿En qué nivel se satura la escala de equilibrio de Berg en los pacientes leves?",["Hacia cincuenta y cinco o cincuenta y seis","Hacia veintiocho puntos como máximo","Hacia cien puntos"],["Exacto: el Mini-BESTest permite entonces seguir discriminando.","Falso: esa puntuación es el máximo del Mini-BESTest.","Falso: esa puntuación es el máximo de la escala postural."]],
  "285": ["¿Qué escala sigue discriminando en los pacientes con equilibrio casi normal?",["El Mini-BESTest","La escala de equilibrio de Berg","El índice de Barthel"],["Exacto: sus giros rápidos y su equilibrio reactivo evitan el efecto techo.","Falso: se satura en esos pacientes.","Falso: es aún menos sensible."]],
  "286": ["¿Cuál es el rango de la escala de equilibrio de Berg?",["De cero a cincuenta y seis","De cero a veintiocho","De dieciocho a ciento veintiséis"],["Exacto: una puntuación elevada indica un mejor equilibrio.","Falso: ese rango es el del Mini-BESTest.","Falso: ese rango es el de la medida de independencia funcional."]],
  "287": ["¿Cómo se interpreta la puntuación de la escala de marcha de Wisconsin?",["La puntuación más baja indica la mejor marcha","La puntuación más alta indica la mejor marcha","La puntuación media indica la mejor marcha"],["Exacto: es lo contrario de la mayoría de las escalas, lo que la convierte en una trampa clásica.","Falso: esa lectura es precisamente el error que hay que evitar.","Falso: no existe ninguna lectura de ese tipo."]],
  "288": ["¿Cuál es el rango de la medida de independencia funcional?",["De dieciocho a ciento veintiséis","De cero a cien","De cero a cincuenta y seis"],["Exacto: una puntuación elevada traduce mayor autonomía.","Falso: ese rango es el de la escala postural.","Falso: ese rango es el de la escala de Berg."]],
  "289": ["¿Cuál es el interés principal de los instrumentos de medida objetivos?",["Sirven de referencia para validar las escalas","Sustituyen con ventaja a las escalas clínicas","Permiten establecer el diagnóstico médico"],["Exacto: la mayoría de las veces no aportan motivos para modificar el tratamiento.","Falso: su aportación terapéutica directa es limitada.","Falso: no es su función."]],
  "290": ["¿En qué contexto se emplean sobre todo los instrumentos objetivos?",["En investigación","En la práctica clínica corriente","En cribado masivo poblacional"],["Exacto: proporcionan una información cuantitativa de referencia.","Falso: su uso cotidiano sigue siendo limitado.","Falso: no es su campo de aplicación."]],
  "291": ["¿Qué es la validez concurrente?",["Una validez de criterio, con una medida actual","Una forma de validez referida a un acontecimiento futuro","La concordancia entre dos examinadores diferentes"],["Exacto: la validez predictiva se refiere, por su parte, a un acontecimiento futuro.","Falso: esa definición es la de la validez predictiva.","Falso: esa propiedad corresponde a la fiabilidad."]],
  "292": ["¿Qué es la validez aparente?",["La impresión de que mide lo que anuncia","La concordancia estadística con una escala de referencia","La estabilidad de las mediciones a lo largo del tiempo"],["Exacto: se distingue de las validez de contenido, conceptual y de criterio.","Falso: esa propiedad corresponde a la validez de criterio.","Falso: esa propiedad es la fiabilidad."]],
  "293": ["¿Qué es la validez discriminante?",["La escala no correlaciona con conceptos alejados","La escala correlaciona con conceptos próximos","La escala distingue a los pacientes graves de los leves"],["Exacto: completa a la validez convergente dentro de la validez conceptual.","Falso: esa propiedad es la validez convergente.","Falso: esa capacidad corresponde más bien a la sensibilidad."]],
  "294": ["¿Por qué puede un paciente mantenerse en la misma puntuación de Barthel aun progresando?",["Sus tramos de puntuación son demasiado amplios","Porque la escala comprende demasiados ítems","Porque la escala mide un concepto completamente distinto"],["Exacto: la medida de independencia funcional, más fina, registra la progresión.","Falso: solo comprende diez.","Falso: el concepto medido es efectivamente la autonomía."]],
  "295": ["¿Qué hay que comprobar antes de emplear una escala en investigación?",["Que esté validada para la población","Que comprenda al menos quince ítems puntuados","Que sea la publicada más recientemente"],["Exacto: hay que conocer además sus umbrales, su fiabilidad y su cambio detectable.","Falso: el número de ítems no es un criterio.","Falso: la antigüedad no es el criterio que se considera."]],
  "296": ["¿Qué hay que citar cuando se emplea una escala traducida?",["El artículo original y la adaptación","Únicamente el artículo original","Únicamente la adaptación traducida y validada"],["Exacto: ambas referencias son necesarias para la trazabilidad.","Falso: la traducción validada debe citarse igualmente.","Falso: el artículo original sigue siendo indispensable."]],
  "297": ["¿Qué escala se centra en el tronco en posición sentada?",["La prueba de alcance del tronco","La escala de equilibrio de Berg","El Mini-BESTest"],["Exacto: comprende diecisiete ítems repartidos en tres subescalas.","Falso: explora el equilibrio estático y dinámico global.","Falso: explora cuatro dimensiones del equilibrio."]],
  "298": ["¿Cuántos ítems comprende la escala de equilibrio de Berg?",["Catorce","Diecisiete","Dieciocho"],["Exacto: se puntúa de cero a cincuenta y seis.","Falso: ese número es el de la prueba de alcance del tronco.","Falso: ese número es el de la medida de independencia funcional."]],
  "299": ["¿Cómo se puntúan los ítems del Mini-BESTest?",["De cero a dos","De cero a cuatro","De uno a siete"],["Exacto: catorce ítems dan un total de veintiocho puntos.","Falso: esa puntuación es la de la escala de Berg.","Falso: esa puntuación es la de la medida de independencia funcional."]],
  "300": ["¿Cuáles son las cuatro subescalas del Mini-BESTest?",["Anticipatorio, reactivo, sensorial y marcha","Estático, dinámico, sentado y de pie","Fuerza, amplitud, coordinación y resistencia"],["Exacto: esa estructura le permite discriminar a los pacientes poco afectados.","Falso: esa división no corresponde a la herramienta.","Falso: esas cualidades no son las que se exploran."]],
  "301": ["¿Qué puntuación de la escala de Berg indica un riesgo de caída bajo?",["De cuarenta y uno a cincuenta y seis","De veintiuno a cuarenta","De cero a veinte"],["Exacto: el riesgo es medio de veintiuno a cuarenta y elevado por debajo de veintiuno.","Falso: ese intervalo corresponde a un riesgo medio.","Falso: ese intervalo corresponde a un riesgo elevado."]],
  "302": ["¿Qué puntuación de la escala de Berg indica un riesgo de caída elevado?",["De cero a veinte","De veintiuno a cuarenta","De cuarenta y uno a cincuenta y seis"],["Exacto: por encima de cuarenta el riesgo pasa a ser bajo.","Falso: ese intervalo corresponde a un riesgo medio.","Falso: ese intervalo corresponde a un riesgo bajo."]],
  "303": ["¿Cuál es el rango de la escala postural para el accidente cerebrovascular?",["De cero a cien","De cero a cincuenta y seis","De cero a veintiocho"],["Exacto: comienza en decúbito supino, lo que evita el efecto suelo.","Falso: ese rango es el de la escala de Berg.","Falso: ese rango es el del Mini-BESTest."]],
  "304": ["¿Qué predice una puntuación superior o igual a cincuenta en la escala postural?",["La recuperación de la marcha a las dieciocho semanas","La aparición de una caída en el año siguiente","El regreso al domicilio en el plazo de un mes"],["Exacto: esa medición se realiza seis semanas después del accidente cerebrovascular.","Falso: esa predicción corresponde a la escala de Berg.","Falso: no es el acontecimiento predicho."]],
  "305": ["¿En qué momento se realiza la escala postural para predecir la marcha?",["Seis semanas después del accidente cerebrovascular","Ya en las primeras cuarenta y ocho horas","Dieciocho semanas después del accidente"],["Exacto: una puntuación de al menos cincuenta predice entonces la marcha a las dieciocho semanas.","Falso: el valor predictivo no está establecido en esa fase.","Falso: es el plazo de la predicción, no el de la medición."]],
  "306": ["¿Qué prueba mide la movilidad funcional y el riesgo de caída en un solo ítem?",["La prueba de levántate y anda cronometrada","La prueba de marcha de diez metros","La escala de marcha de Wisconsin"],["Exacto: levantarse, andar tres metros, girar y volver a sentarse lleva de uno a tres minutos.","Falso: mide la velocidad y no la movilidad funcional global.","Falso: comprende catorce ítems y evalúa la calidad."]],
  "307": ["¿Qué distancia se recorre en la prueba de levántate y anda cronometrada?",["Tres metros","Diez metros","Seis metros"],["Exacto: se levanta uno, anda, gira y vuelve a sentarse.","Falso: esa distancia es la de la prueba de marcha de diez metros.","Falso: esa distancia no corresponde a ninguna de estas pruebas."]],
  "308": ["¿Qué mide la prueba de marcha de diez metros?",["La velocidad de la marcha","La calidad del patrón de marcha","El equilibrio reactivo en situación"],["Exacto: no informa sobre el patrón de marcha.","Falso: precisamente no atiende al patrón.","Falso: esa dimensión corresponde al Mini-BESTest."]],
  "309": ["¿Cuántos ítems comprende la escala de marcha de Wisconsin?",["Catorce","Diecisiete","Dieciocho"],["Exacto: es específica del accidente cerebrovascular y detecta la asimetría.","Falso: ese número es el de la prueba de alcance del tronco.","Falso: ese número es el de la medida de independencia funcional."]],
  "310": ["¿A qué población se dirige la escala de marcha de Wisconsin?",["A los pacientes tras un accidente cerebrovascular","A los pacientes parkinsonianos","A los pacientes con esclerosis múltiple"],["Exacto: detecta la asimetría y los defectos de marcha propios de ese cuadro.","Falso: otras herramientas se les dedican específicamente.","Falso: otras escalas cubren esa patología."]],
  "311": ["¿Qué herramienta mide la cantidad de marcha?",["La categoría de marcha funcional","La escala de marcha de Wisconsin","La evaluación orientada de la movilidad"],["Exacto: las pruebas de marcha de diez y de seis minutos la complementan.","Falso: evalúa la calidad del patrón.","Falso: evalúa igualmente la calidad."]],
  "312": ["¿Cuántos niveles ordinales comprende cada ítem de la medida de independencia funcional?",["Siete","Tres","Cinco"],["Exacto: uno corresponde a la dependencia total y siete a la independencia completa.","Falso: esa puntuación es la del Mini-BESTest.","Falso: ese número no corresponde a esta herramienta."]],
  "313": ["¿Qué significa una puntuación de uno en un ítem de la medida de independencia funcional?",["Una dependencia total","Una independencia total","Una autonomía con ayuda técnica"],["Exacto: el siete corresponde a la independencia total.","Falso: esa situación corresponde a la puntuación de siete.","Falso: esa situación se sitúa en una posición intermedia."]],
  "314": ["¿Cuántos ítems añade la medida de evaluación funcional a la medida de independencia?",["Doce","Seis","Dieciocho"],["Exacto: eleva así el total a treinta ítems.","Falso: ese número es inferior al que se añade.","Falso: ese número corresponde a los ítems de la herramienta de base."]],
  "315": ["¿Qué mide la escala de Lawton y Brody?",["Las actividades instrumentales de la vida diaria","Las actividades básicas de la vida diaria","El equilibrio de pie y el riesgo de caída"],["Exacto: teléfono, compras, comidas, transporte, medicación y gestión del dinero.","Falso: estas corresponden al índice de Barthel.","Falso: esa dimensión corresponde a las escalas de equilibrio."]],
  "316": ["¿Cuál es la puntuación máxima de la escala de Lawton y Brody?",["Ocho","Cien","Cincuenta y seis"],["Exacto: cada una de las ocho actividades instrumentales vale un punto.","Falso: esa puntuación es la del índice de Barthel.","Falso: esa puntuación es la de la escala de Berg."]],
  "317": ["¿Qué actividad figura en la escala de Lawton y Brody?",["La responsabilidad sobre la medicación","El aseo y el vestido","La transferencia de la cama al sillón"],["Exacto: junto con el teléfono, las compras, las comidas, la ropa, las tareas del hogar y el transporte.","Falso: esas actividades básicas corresponden al índice de Barthel.","Falso: esa transferencia corresponde igualmente a las actividades básicas."]],
  "318": ["¿Qué escala evalúa la recuperación motora y las sinergias del miembro superior?",["La subescala de Fugl-Meyer","El índice de motricidad","La prueba de los cubos y la caja"],["Exacto: el índice de motricidad mide más bien la fuerza.","Falso: mide la fuerza y no las sinergias.","Falso: mide la destreza global."]],
  "319": ["¿Qué mide el índice de motricidad?",["La fuerza","La destreza fina de los dedos","La calidad de vida del paciente"],["Exacto: la escala de Fugl-Meyer explora más bien la recuperación motora y las sinergias.","Falso: esa cualidad se mide mediante la prueba de las clavijas.","Falso: esa dimensión corresponde a otras herramientas."]],
  "320": ["¿Qué explora la prueba de prensión del miembro superior?",["Prensión, agarre, pinza y movimientos gruesos","La fuerza isométrica de la muñeca","La calidad de la marcha y el equilibrio"],["Exacto: forma parte de las pruebas de destreza del miembro superior.","Falso: la fuerza corresponde al índice de motricidad.","Falso: esas dimensiones atañen al miembro inferior."]],
  "321": ["¿Cuánto dura la prueba de los cubos y la caja?",["Sesenta segundos","Treinta segundos","Ciento veinte segundos"],["Exacto: mide la destreza global contando los cubos transferidos.","Falso: la duración que se considera es el doble.","Falso: esa duración es demasiado larga."]],
  "322": ["¿Qué mide la prueba de las clavijas y el tablero perforado?",["La destreza fina y la coordinación bimanual","La destreza global del miembro superior","La fuerza de prensión de la mano"],["Exacto: evalúa igualmente la velocidad de ejecución.","Falso: esa dimensión corresponde a la prueba de los cubos.","Falso: esa medida corresponde a la dinamometría."]],
  "323": ["¿Qué escala de calidad de vida es genérica?",["El cuestionario de treinta y seis ítems","El cuestionario para la enfermedad de Parkinson","La escala de impacto de la esclerosis múltiple"],["Exacto: existen escalas específicas para la lesión medular y el accidente cerebrovascular.","Falso: es específico de esa patología.","Falso: es igualmente específica."]],
  "324": ["¿Qué escala mide la discapacidad global en la esclerosis múltiple?",["La escala ampliada del estado de discapacidad","La escala de severidad de la fatiga","La escala de impacto de veintinueve ítems"],["Exacto: la escala de marcha de doce ítems y la de impacto de veintinueve la complementan.","Falso: mide específicamente la fatiga.","Falso: mide el impacto percibido de la enfermedad."]],
  "325": ["¿Qué escala mide la fatiga en la esclerosis múltiple?",["La escala de severidad de la fatiga","La escala ampliada del estado de discapacidad","La escala de marcha de doce ítems"],["Exacto: la fatiga neurológica es un síntoma cardinal de esa enfermedad.","Falso: mide la discapacidad global.","Falso: se refiere específicamente a la marcha."]],
  "326": ["¿Qué escala describe el estadio de la enfermedad de Parkinson?",["La escala de Hoehn y Yahr","La escala unificada de evaluación","El cuestionario del bloqueo de la marcha"],["Exacto: la escala unificada de evaluación es, por su parte, mucho más detallada.","Falso: describe el estado clínico con detalle, no el estadio.","Falso: se refiere a un síntoma concreto."]],
  "327": ["¿Qué herramienta evalúa el bloqueo de la marcha en la enfermedad de Parkinson?",["El cuestionario del bloqueo de la marcha","La escala de Hoehn y Yahr","El cuestionario de calidad de vida de treinta y nueve ítems"],["Exacto: se dirige específicamente a ese síntoma incapacitante.","Falso: describe el estadio global de la enfermedad.","Falso: mide la calidad de vida."]],
  "328": ["¿Qué escala mide la gravedad inicial de un accidente cerebrovascular?",["La escala nacional del accidente cerebrovascular","La escala de Fugl-Meyer","La escala de impacto del accidente cerebrovascular"],["Exacto: la escala de Fugl-Meyer y la escala de impacto la complementan a largo plazo.","Falso: mide la recuperación motora.","Falso: mide la repercusión percibida."]],
  "329": ["¿Qué escala es específica de la esclerosis lateral amiotrófica?",["La escala funcional revisada","La escala ampliada del estado de discapacidad","La escala de Hoehn y Yahr"],["Exacto: sigue la evolución funcional de esa enfermedad.","Falso: es específica de la esclerosis múltiple.","Falso: es específica de la enfermedad de Parkinson."]],
  "330": ["¿Qué parámetros hay que evaluar en el paciente neurológico?",["Equilibrio, marcha, función, miembro y vida","Únicamente la fuerza y la amplitud articular","Únicamente la calidad de vida percibida"],["Exacto: cada dimensión dispone de sus propias herramientas validadas.","Falso: esa reducción deja de lado lo esencial.","Falso: esa única dimensión resultaría insuficiente."]],
  "331": ["¿Qué herramienta evalúa la calidad de vida del cuidador?",["El cuestionario de treinta y ocho ítems para el cuidador","El cuestionario genérico de treinta y seis ítems","La escala de impacto del accidente cerebrovascular"],["Exacto: la carga del cuidador forma parte de la valoración global.","Falso: se dirige al paciente mismo.","Falso: atañe igualmente al paciente."]],
  "332": ["¿Cuántas subescalas comprende la prueba de alcance del tronco?",["Tres","Cuatro","Dos"],["Exacto: sus diecisiete ítems se reparten entre ellas.","Falso: ese número es el del Mini-BESTest.","Falso: ese número es inferior a la realidad."]],
  "333": ["¿Cuánto tiempo lleva la prueba de levántate y anda cronometrada?",["De uno a tres minutos","De diez a quince minutos","Treinta segundos como máximo"],["Exacto: su rapidez la convierte en una herramienta de cribado cómoda.","Falso: esa duración está muy sobreestimada.","Falso: la duración es algo mayor."]],
  "334": ["¿Cuál es el total de puntos del Mini-BESTest?",["Veintiocho","Cincuenta y seis","Cien"],["Exacto: catorce ítems puntuados de cero a dos.","Falso: ese total es el de la escala de Berg.","Falso: ese total es el de la escala postural."]],
  "335": ["¿Qué mide la evaluación orientada de la movilidad?",["La calidad de la marcha","La cantidad de marcha recorrida","La velocidad de marcha en diez metros"],["Exacto: coincide con la escala de Wisconsin y la evaluación de Rivermead.","Falso: esa dimensión corresponde a la categoría de marcha funcional.","Falso: esa medida corresponde a la prueba de diez metros."]],
  "336": ["¿Qué dimensiones explora la escala de Berg?",["El equilibrio estático y dinámico","Únicamente la calidad de la marcha","Únicamente la fuerza de los miembros inferiores"],["Exacto: sirve además para estimar el riesgo de caída.","Falso: esa dimensión corresponde a otras herramientas.","Falso: la fuerza no es su objeto."]],
  "337": ["¿Cuál es la ventana terapéutica más favorable después de un accidente cerebrovascular?",["Las veinticuatro a cuarenta y ocho horas","Las dos primeras semanas","El tercer mes siguiente al accidente"],["Exacto: es entonces cuando la neuroplasticidad resulta más aprovechable.","Falso: la ventana más favorable es bastante más precoz.","Falso: ese plazo es muy posterior a la ventana descrita."]],
  "338": ["¿Qué se puede decir de una rehabilitación emprendida antes de las cuarenta y ocho horas?",["Es segura y puede mejorar los resultados","Es peligrosa y debe diferirse","No tiene efecto demostrado sobre la evolución"],["Exacto: la precocidad aprovecha al máximo la ventana de plasticidad.","Falso: su seguridad está, al contrario, establecida.","Falso: se describe un beneficio."]],
  "339": ["¿Qué es el estado de choque neural?",["Un descenso general de la actividad nerviosa","Una hiperactividad generalizada del sistema nervioso","Una destrucción irreversible de todas las zonas"],["Exacto: los síntomas son entonces más graves que la lesión real.","Falso: lo que se observa es una depresión de la actividad.","Falso: solo algunas zonas quedan definitivamente lesionadas."]],
  "340": ["¿Qué son las zonas de penumbra?",["Zonas temporalmente afectadas alrededor de la lesión","Zonas anatómicamente destruidas e irrecuperables","Zonas situadas en el hemisferio contralateral"],["Exacto: coexisten con el foco lesional, este irreversible.","Falso: esa descripción es la del foco lesional.","Falso: su localización es perilesional."]],
  "341": ["¿Por qué pueden resultar perjudiciales los estímulos en la fase aguda?",["La penumbra no puede metabolizar","Porque provocan una espasticidad inmediata","Porque aumentan la presión arterial"],["Exacto: en esa fase, el paciente es además incapaz de aprender.","Falso: la espasticidad se instala más tardíamente.","Falso: no es la razón invocada."]],
  "342": ["¿Qué pierde primero el paciente en la fase aguda?",["Su postura, antes que su movilidad","Su movilidad, antes que su postura","Su sensibilidad, antes que su motricidad"],["Exacto: ese orden condiciona toda la estrategia de abordaje inicial.","Falso: el orden es exactamente el inverso.","Falso: no es el orden descrito."]],
  "343": ["¿Qué desarrolla naturalmente el sistema antes de toda recuperación?",["Compensaciones y reacciones asociadas","Una recuperación motora espontánea completa","Una inhibición completa de toda actividad"],["Exacto: las exigencias internas y externas aparecen antes de la recuperación.","Falso: la recuperación viene después, y sigue siendo parcial.","Falso: el sistema responde, al contrario, de forma activa."]],
  "344": ["¿Qué factor determina los daños residuales?",["El diasquisis y el aprendizaje del no uso","Únicamente el tamaño del foco lesional inicial","La edad del paciente tomada aisladamente"],["Exacto: las zonas de penumbra y edematosas contribuyen igualmente a ello.","Falso: otros factores intervienen en gran medida.","Falso: la edad por sí sola no determina las secuelas."]],
  "345": ["¿Qué complicación respiratoria acecha al paciente en la fase aguda?",["La atelectasia y la hipoventilación","El enfisema pulmonar de instauración rápida","La crisis asmática grave desencadenada por el reposo en cama"],["Exacto: la neumonía y el descenso de la capacidad vital las acompañan.","Falso: esa afección no aparece en unos pocos días.","Falso: esa complicación no se describe aquí."]],
  "346": ["¿Qué articulaciones están más expuestas a las retracciones capsuloligamentosas?",["Los hombros, los codos y los tobillos","Las caderas, las rodillas y las muñecas","El raquis cervical y la mandíbula"],["Exacto: su posición debe vigilarse desde los primeros días.","Falso: esas articulaciones no son las citadas.","Falso: esas regiones no figuran en esa lista."]],
  "347": ["¿Qué complicación de hombro se teme especialmente después de un accidente cerebrovascular?",["El dolor y la subluxación","La capsulitis retráctil del sujeto joven","La rotura espontánea del bíceps largo"],["Exacto: figuran entre las complicaciones más frecuentes y más incapacitantes.","Falso: no es la complicación característica descrita.","Falso: esa lesión no está ligada a ese contexto."]],
  "348": ["¿Cuál es el primer objetivo en fase aguda?",["La profilaxis","El reposo del paciente","La activación segmentaria"],["Exacto: después vienen el reposo y luego la activación.","Falso: constituye el segundo objetivo.","Falso: constituye el tercer objetivo."]],
  "349": ["¿Qué debe sentir el paciente para que el reposo sea eficaz?",["Sentirse seguro, estable y sin dolor","Sentirse estimulado y solicitado de forma permanente","Sentirse constreñido por una sujeción rígida"],["Exacto: el sistema nervioso debe cumplir las fases del sueño para metabolizar los neurotransmisores.","Falso: la solicitación permanente perjudica a esa fase.","Falso: la constricción se opone al sentimiento de seguridad buscado."]],
  "350": ["¿Por qué es esencial el sueño en la fase aguda?",["Permite metabolizar los neurotransmisores","Acelera directamente la regeneración de los axones","Suprime el riesgo de complicaciones articulares"],["Exacto: por eso el reposo precede a la activación en los objetivos.","Falso: la regeneración central no existe en el adulto.","Falso: estas corresponden a la profilaxis postural."]],
  "351": ["¿En qué consiste la activación en fase aguda?",["En microcolocaciones de un segmento","En ejercicios activos resistidos de los cuatro miembros","En movilizaciones pasivas rápidas y repetidas"],["Exacto: un cambio de posición nunca es enteramente pasivo.","Falso: esa intensidad supera lo que tolera la fase aguda.","Falso: no se busca la pasividad pura."]],
  "352": ["¿Por qué un cambio de posición nunca es enteramente pasivo?",["Se pide la información para obtener la intención","Porque el paciente siempre se resiste al movimiento","Porque la gravedad impide toda pasividad"],["Exacto: esa solicitación convierte la maniobra en un acto terapéutico.","Falso: la resistencia no es el argumento invocado.","Falso: no es la razón descrita."]],
  "353": ["¿A partir de cuándo movilizar a un paciente hemodinámicamente estable?",["Más allá de las veinticuatro horas","Más allá de los siete días","Ya desde los primeros minutos"],["Exacto: las sesiones duran de quince a cuarenta y cinco minutos, eventualmente varias veces al día.","Falso: ese plazo es mucho demasiado tardío.","Falso: la estabilidad hemodinámica debe adquirirse primero."]],
  "354": ["¿Cuál es la duración de una sesión de movilización precoz?",["De quince a cuarenta y cinco minutos","De dos a cinco minutos","Dos horas consecutivas"],["Exacto: puede repetirse varias veces a lo largo del día.","Falso: esa duración es demasiado corta para resultar útil.","Falso: esa duración es excesiva en esa fase."]],
  "355": ["¿Con qué ritmo alternar las posiciones funcionales?",["Cada dos o tres horas","Cada doce horas","Cada quince minutos"],["Exacto: almohadas y toallas enrolladas mantienen la posición y protegen las prominencias.","Falso: ese intervalo expone a las úlceras por presión.","Falso: ese ritmo es irreal e inútil."]],
  "356": ["¿Qué precaución hay que tomar con las almohadas de colocación?",["No retirarlas todas de golpe","Retirarlas todas en cuanto el paciente despierta","Dejarlas en su sitio sin moverlas nunca"],["Exacto: su retirada brusca hace que el paciente pierda la estabilidad.","Falso: esa retirada brusca es precisamente lo que no se aconseja.","Falso: las posiciones deben alternarse con regularidad."]],
  "357": ["¿Hacia dónde tiende a caer un paciente tumbado sobre el lado afectado?",["Hacia atrás","Hacia delante","Hacia el techo, sin dirección nítida"],["Exacto: del lado opuesto, la tendencia es, al contrario, caer hacia delante.","Falso: esa tendencia se observa del lado no afectado.","Falso: la tendencia está bien orientada."]],
  "358": ["¿Qué posición privilegiar en un paciente muy afectado?",["El decúbito sobre el lado afectado","El decúbito supino estricto permanente","La sedestación prolongada en el sillón"],["Exacto: esa consigna tiene en cuenta las distintas tendencias de caída según el lado.","Falso: la alternancia de las posiciones sigue siendo necesaria.","Falso: no es adecuada para un paciente muy afectado en fase aguda."]],
  "359": ["¿Qué riesgo corre un hombro colocado a noventa grados?",["Irse en rotación interna, con la escápula despegada","Irse en rotación externa claramente excesiva","Bloquearse en abducción completa"],["Exacto: es más realista aproximar la escápula a la caja torácica.","Falso: lo que se teme es la rotación interna.","Falso: no es el riesgo descrito."]],
  "360": ["¿Cómo obtener de forma más realista una rotación externa de hombro?",["Aproximando la escápula a la caja torácica","Forzando directamente la rotación glenohumeral","Colocando el brazo por encima de la cabeza"],["Exacto: actuar sobre la escápula es más eficaz que forzar la glenohumeral.","Falso: esa constricción directa es poco eficaz y arriesgada.","Falso: esa posición agrava el riesgo de conflicto."]],
  "361": ["¿Qué precaución atañe al pie en decúbito?",["No debe caer por efecto de la gravedad","Debe permanecer en flexión plantar máxima","Debe dejarse enteramente libre"],["Exacto: un pie equino se instalaría rápidamente.","Falso: esa posición favorece precisamente el equino.","Falso: caería entonces por efecto de la gravedad."]],
  "362": ["¿Qué caracteriza a la fase subaguda de reorganización neuronal?",["El aprendizaje se vuelve posible y fácil","El aprendizaje sigue siendo totalmente imposible","Toda plasticidad desaparece definitivamente"],["Exacto: las compensaciones pasan entonces a ser algo nuevo y natural, de ahí el riesgo.","Falso: esa situación caracteriza a la fase aguda.","Falso: la plasticidad está, al contrario, reactivada."]],
  "363": ["¿Por qué es de riesgo la fase subaguda?",["El aprendizaje vuelve a ser posible","La neuroplasticidad está en ella totalmente ausente","El paciente ya no puede aprender nada"],["Exacto: hay que controlar, por tanto, el uso excesivo de las estrategias compensatorias.","Falso: está, al contrario, reactivada.","Falso: es precisamente lo contrario."]],
  "364": ["¿Qué hay que impedir que se instale en fase subaguda?",["La espasticidad como adaptación no funcional","Toda forma de movimiento activo del paciente","Toda participación de la familia en los cuidados"],["Exacto: pasaría a ser una estrategia aprendida difícil de deshacer.","Falso: el movimiento activo se busca, al contrario.","Falso: el entorno es un apoyo valioso."]],
  "365": ["¿Qué es el choque medular?",["Una pérdida transitoria de las funciones por debajo de la lesión","Una pérdida definitiva de todas las funciones","Una hiperreflexia de instauración brusca"],["Exacto: asocia hipotonía, arreflexia y ausencia de respuestas autónomas.","Falso: la pérdida es transitoria por definición.","Falso: la arreflexia domina, al contrario, el cuadro."]],
  "366": ["¿Qué riesgo corre un paciente portador de una lesión medular de C1 a C4?",["Una insuficiencia respiratoria","Una disreflexia autónoma inmediata","Una espasticidad mayor inmediata"],["Exacto: la inervación diafragmática está comprometida en esos niveles.","Falso: esta sobreviene más bien en fase subaguda o crónica.","Falso: el choque medular da primero una hipotonía."]],
  "367": ["¿Qué es el choque neurogénico?",["Una vasodilatación por pérdida del simpático","Una vasoconstricción intensa por descarga simpática","Una taquicardia con subida hipertensiva"],["Exacto: se acompaña de bradicardia e hipotensión ortostática.","Falso: lo que se produce es lo contrario.","Falso: la bradicardia domina el cuadro."]],
  "368": ["¿A partir de qué nivel lesional sobreviene la disreflexia autónoma?",["Por encima de T6","Por debajo de T10","Únicamente a nivel lumbar"],["Exacto: aparece más bien en fase subaguda o crónica.","Falso: ese nivel es demasiado bajo para ese fenómeno.","Falso: las lesiones lumbares no exponen a ese riesgo."]],
  "369": ["¿Qué puntuación de Glasgow define un traumatismo craneal grave?",["Una puntuación inferior a ocho","Una puntuación de nueve a doce","Una puntuación de trece a quince"],["Exacto: el traumatismo es moderado de nueve a doce y leve de trece a quince.","Falso: ese intervalo define el traumatismo moderado.","Falso: ese intervalo define el traumatismo leve."]],
  "370": ["¿Qué puntuación de Glasgow define un traumatismo craneal leve?",["De trece a quince","De nueve a doce","Por debajo de ocho"],["Exacto: el traumatismo grave se sitúa por debajo de ocho.","Falso: ese intervalo define el traumatismo moderado.","Falso: ese valor define el traumatismo grave."]],
  "371": ["¿Qué complicación intracraneal se teme después de un traumatismo craneal?",["El edema con hipertensión intracraneal","La isquemia medular cervical baja","La trombosis de la arteria femoral"],["Exacto: hematomas y hernias cerebrales completan el cuadro.","Falso: esa complicación no es intracraneal.","Falso: no tiene ninguna relación con ese contexto."]],
  "372": ["¿Qué precaución de fisioterapia respiratoria se impone después de un traumatismo craneal?",["Evitar aumentar la presión intracraneal","Privilegiar las técnicas más vigorosas","Prohibir toda fisioterapia respiratoria"],["Exacto: se privilegian el drenaje postural y las técnicas suaves.","Falso: elevan peligrosamente la presión intracraneal.","Falso: sigue estando indicada, pero adaptada."]],
  "373": ["¿Qué práctica hay que evitar ante un hombro doloroso en fase aguda?",["La poleoterapia sin vigilancia","La movilización suave de la escápula","La activación isométrica submáxima"],["Exacto: los estiramientos forzados y el brazo dejado colgando están igualmente proscritos.","Falso: está, al contrario, recomendada en primer lugar.","Falso: forma parte del tratamiento aconsejado."]],
  "374": ["¿Qué riesgo conlleva una flexión de hombro más allá de noventa grados sin estabilidad escapular?",["Un conflicto subacromial y una subluxación","Una rotura del tendón del bíceps largo","Una fractura del cuello quirúrgico del húmero"],["Exacto: por eso la escápula debe movilizarse en primer lugar.","Falso: no es el riesgo descrito.","Falso: esa lesión no está ligada a esa maniobra."]],
  "375": ["¿Qué hay que movilizar antes que la articulación glenohumeral?",["La escápula, en todos sus planos","El codo y la muñeca del lado afectado","El raquis cervical en rotación"],["Exacto: se respeta así el ritmo escapulohumeral.","Falso: no es la prioridad descrita.","Falso: esa movilización no es la recomendada."]],
  "376": ["¿Qué músculos activar de forma isométrica submáxima en el hombro?",["Manguito, deltoides y escapulares","Únicamente los músculos del antebrazo","Únicamente los músculos cervicales posteriores"],["Exacto: los ajustes anticipados se dirigen al serrato anterior y al trapecio inferior.","Falso: no intervienen en la estabilidad escapular.","Falso: no son los músculos buscados."]],
  "377": ["¿A qué músculos se apunta para los ajustes anticipados del hombro?",["Al serrato anterior y al trapecio","Al pectoral mayor y al dorsal ancho","Al deltoides medio y al supraespinoso"],["Exacto: estabilizan la escápula antes de todo movimiento del brazo.","Falso: esos músculos son más bien motores del brazo.","Falso: son abductores, no estabilizadores anticipados."]],
  "378": ["¿Qué regla de educación hay que dar al entorno del paciente hemipléjico?",["No agarrar nunca al paciente por el brazo","Tirar siempre del brazo para ayudar en la transferencia","Dejar el brazo colgando libremente en el sillón"],["Exacto: esa tracción expone a la subluxación de hombro.","Falso: es precisamente el gesto que hay que proscribir.","Falso: esa posición favorece la subluxación."]],
  "379": ["¿Qué complicación tromboembólica hay que prevenir en fase aguda?",["La trombosis venosa profunda","La embolia grasa posfractura","La trombosis arterial carotídea"],["Exacto: figura entre las complicaciones que hay que prevenir, junto con las úlceras por presión.","Falso: esa complicación corresponde a la traumatología.","Falso: no es la complicación a la que apunta la profilaxis."]],
  "380": ["¿Qué ocurre con el aprendizaje en la fase aguda?",["El paciente es incapaz de aprender","El paciente aprende más rápido que en estado normal","El paciente aprende con normalidad desde el primer día"],["Exacto: hay que esperar la fase subaguda de reorganización neuronal.","Falso: esa facilitación pertenece a la fase subaguda.","Falso: el choque neural se lo impide."]],
  "381": ["¿Qué hace una ortesis con respecto a una prótesis?",["Mejora, mientras que la prótesis sustituye","Sustituye, mientras que la prótesis mejora","Facilita, mientras que la prótesis mejora"],["Exacto: los productos de apoyo, por su parte, facilitan la función y la independencia.","Falso: ambos papeles están invertidos.","Falso: facilitar es el papel de los productos de apoyo."]],
  "382": ["¿Qué hace un producto de apoyo?",["Facilita la función y la independencia","Sustituye un segmento corporal ausente","Modifica la estructura neuromusculoesquelética"],["Exacto: la ortesis mejora y la prótesis sustituye.","Falso: ese papel es el de la prótesis.","Falso: esa definición es la de la ortesis."]],
  "383": ["¿Qué lugar ocupa una ortesis en un tratamiento?",["Un lugar complementario, nunca único","Un lugar central, suficiente por sí solo","Un lugar accesorio, sin efecto real"],["Exacto: nunca debe constituir el tratamiento por sí sola.","Falso: es precisamente lo que hay que evitar.","Falso: su efecto terapéutico es bien real."]],
  "384": ["¿Cuál es uno de los objetivos de una ortesis?",["Impedir la progresión de una deformidad","Sustituir definitivamente un músculo paralizado","Suprimir todo movimiento de la articulación"],["Exacto: busca también prevenir el dolor y compensar una musculatura debilitada.","Falso: ninguna ortesis sustituye a un músculo.","Falso: controla el movimiento sin abolirlo sistemáticamente."]],
  "385": ["¿Qué efecto indeseable acecha al uso prolongado de una ortesis?",["Una debilidad o una atrofia muscular","Un aumento de la fuerza muscular","Una mejoría espontánea de la sensibilidad"],["Exacto: a ello se añaden erosiones cutáneas, contracturas y dependencia psicológica.","Falso: lo que se teme es lo contrario.","Falso: no se describe ningún efecto de ese tipo."]],
  "386": ["¿Para qué elementos de una ortesis se emplean sobre todo los metales?",["Para las articulaciones","Para las partes en contacto con la piel","Para las láminas de pie dinámicas"],["Exacto: el aluminio, el acero y el titanio son pesados pero resistentes.","Falso: ahí se emplean plásticos blandos o espumas.","Falso: estas son de fibra de carbono."]],
  "387": ["¿Qué ventaja ofrece la fibra de carbono?",["Una alta rigidez con un peso reducido","Un coste muy bajo y una colocación rápida","Una gran flexibilidad para el contacto cutáneo"],["Exacto: su coste elevado y el riesgo de bordes cortantes son sus límites.","Falso: su coste es, al contrario, elevado.","Falso: es rígida; los plásticos blandos aseguran el confort."]],
  "388": ["¿Qué elemento determina el tipo de ortesis que se debe prescribir?",["El nivel metamérico de la lesión","Únicamente el peso del paciente","La preferencia estética de la familia"],["Exacto: el carácter flácido o espástico, la sensibilidad y la edad cuentan igualmente.","Falso: ese parámetro no es el determinante principal.","Falso: ese criterio no es determinante."]],
  "389": ["¿Qué precaución impone la prescripción de ortesis en el niño?",["Hacerlas sólidas, adaptables y poco pesadas","Hacerlas lo más rígidas posible","Renovarlas únicamente cada cinco años"],["Exacto: el crecimiento impone una adaptabilidad constante.","Falso: el peso y la adaptabilidad prevalecen.","Falso: el crecimiento impone una renovación mucho más frecuente."]],
  "390": ["¿Hasta dónde llega la ortesis antiequina de tipo Rancho?",["Hasta la articulación metatarsofalángica","Hasta la mitad del pie, por delante","Por encima de la rodilla"],["Exacto: es de polipropileno moldeado sobre el paciente.","Falso: se extiende más distalmente.","Falso: se trata de una ortesis de tobillo y pie."]],
  "391": ["¿Qué riesgo nervioso conlleva la ortesis antiequina de tipo Rancho?",["Una compresión del nervio peroneo común","Una compresión del nervio tibial posterior","Una compresión del nervio sural"],["Exacto: el velcro anterosuperior puede comprimir ese nervio superficial.","Falso: ese nervio no queda expuesto por este dispositivo.","Falso: ese trayecto no es el del velcro en cuestión."]],
  "392": ["¿Qué inconveniente articular puede provocar la ortesis de tipo Rancho?",["Una rigidez de tobillo y del Aquiles","Una hipermovilidad del antepié","Una inestabilidad de la rodilla en carga"],["Exacto: su carácter rígido limita la movilidad del tobillo.","Falso: lo que se teme es la rigidez.","Falso: esa ortesis no controla la rodilla."]],
  "393": ["¿Qué ortesis antiequina permite correr sin cinchas?",["La ortesis dinámica de fibra de carbono","La ortesis conformada de tipo Rancho","La ortesis convencional metálica"],["Exacto: es termoconformable y está destinada a las actividades elevadas.","Falso: su rigidez no lo permite.","Falso: su peso y su fijación lo impiden."]],
  "394": ["¿Qué ortesis antiequina es la más empleada hoy en pediatría?",["La ortesis que envuelve casi todo el pie","La ortesis convencional metálica corta","La ortesis de tipo Rancho de polipropileno"],["Exacto: a medida, muy fina y flexible, al contrario que las ortesis rígidas.","Falso: su peso la hace poco adecuada para el niño.","Falso: ya no es la más empleada en pediatría."]],
  "395": ["¿En qué situación se prefiere una ortesis convencional metálica?",["En caso de trastorno de la sensibilidad cutánea","En el niño muy activo en crecimiento rápido","En el deportista que busca correr"],["Exacto: su contacto mínimo con la piel y su tolerancia al edema lo explican.","Falso: su peso la hace poco adecuada.","Falso: una ortesis dinámica de carbono conviene mejor."]],
  "396": ["¿Qué ventaja ofrece una ortesis convencional en caso de edema?",["Tolera las fluctuaciones de volumen","Comprime el edema y lo reabsorbe","Debe remoldearse en cada variación"],["Exacto: su contacto cutáneo mínimo evita los puntos de presión.","Falso: su papel no es compresivo.","Falso: es el caso de las ortesis conformadas, no de las convencionales."]],
  "397": ["¿Qué hace la articulación de un bitutor metálico corto?",["Bloquea la flexión plantar","Bloquea la flexión dorsal","Libera todos los movimientos del tobillo"],["Exacto: impide así que el pie caiga en fase oscilante.","Falso: lo que se limita es la flexión plantar.","Falso: su papel es precisamente controlarlos."]],
  "398": ["¿Qué aporta el resorte interno de un bitutor de tipo Klenzack?",["La flexión dorsal en fase oscilante","El bloqueo completo del tobillo","El control de la rotación de la rodilla"],["Exacto: en el contacto de talón permite unos quince grados de flexión plantar.","Falso: el resorte permite, al contrario, cierto movimiento.","Falso: ese dispositivo no controla la rodilla."]],
  "399": ["¿Qué amplitud de flexión plantar permite el bitutor de tipo Klenzack en el contacto de talón?",["Unos quince grados","Unos cuarenta grados","Ninguna, el tobillo está bloqueado"],["Exacto: esa flexibilidad amortigua el contacto inicial.","Falso: esa amplitud es excesiva.","Falso: el resorte permite un movimiento controlado."]],
  "400": ["¿A qué situación convienen las ortesis antiequinas elásticas?",["A la parálisis flácida con tobillo estable","A la espasticidad severa con equino fijado","A la inestabilidad mayor del tobillo"],["Exacto: sus resultados son peores en caso de espasticidad severa.","Falso: sus resultados son ahí mediocres.","Falso: exigen cierta estabilidad."]],
  "401": ["¿Qué músculo activa la estimulación eléctrica funcional durante la marcha?",["Los dorsiflexores, en fase oscilante","Los flexores plantares, en fase de apoyo","El cuádriceps, en fase de contacto de talón"],["Exacto: suple la elevación del pie.","Falso: no es la diana del dispositivo.","Falso: la diana es el tobillo y no la rodilla."]],
  "402": ["¿Dónde se coloca el cátodo para una estimulación eléctrica de la elevación del pie?",["Sobre el nervio peroneo, detrás de la cabeza","Sobre el vientre del tibial anterior","Sobre el hueco poplíteo, frente al nervio tibial"],["Exacto: el ánodo se coloca sobre el vientre del tibial anterior.","Falso: es el emplazamiento del ánodo.","Falso: ese nervio ordena la flexión plantar."]],
  "403": ["¿Qué condición es indispensable para la estimulación eléctrica funcional?",["El músculo y el nervio deben estar intactos","El paciente debe ser capaz de correr","La sensibilidad debe estar totalmente abolida"],["Exacto: sin integridad neuromuscular, la estimulación queda sin efecto.","Falso: esa exigencia no tiene razón de ser.","Falso: es, al contrario, un factor desfavorable."]],
  "404": ["¿Qué ortesis trata la inestabilidad de la rodilla por parálisis del cuádriceps?",["El apoyo infrarrotuliano","La ortesis de reacción del suelo","La ortesis antiequina elástica"],["Exacto: la extensión se logra entonces de forma pasiva, y el tobillo queda igualmente estabilizado.","Falso: no ejerce un control directo sobre la rodilla.","Falso: solo controla el tobillo."]],
  "405": ["¿Cómo extiende la rodilla la ortesis de reacción del suelo?",["Mediante la fuerza de reacción del suelo","Mediante un cierre mecánico colocado en la rodilla","Mediante una cincha de tracción posterior"],["Exacto: no hay ningún control directo de la rodilla, y es más ligera que el apoyo infrarrotuliano.","Falso: no interviene ningún dispositivo de cierre.","Falso: no es el principio del dispositivo."]],
  "406": ["¿Cuántos planos controla la ortesis de reacción del suelo?",["Los tres planos del complejo tobillo-pie","Únicamente el plano sagital del tobillo","Únicamente los planos frontal y transverso"],["Exacto: su pieza anterior sostiene la tibia en proximal.","Falso: su control es tridimensional.","Falso: el plano sagital también se controla."]],
  "407": ["¿A qué patologías se destinan los bitutores largos?",["A las secuelas paralíticas por encima de la rodilla","Únicamente a las afectaciones aisladas del tobillo","A las lesiones del miembro superior"],["Exacto: la poliomielitis, el mielomeningocele y la parálisis cerebral son sus indicaciones.","Falso: bastaría entonces con una ortesis corta.","Falso: se trata de ortesis del miembro inferior."]],
  "408": ["¿Qué inconveniente presenta el bitutor largo con cinturón pélvico?",["Impone la marcha pendular y acaba abandonándose","Permite una marcha recíproca muy natural","Solo controla el tobillo y el pie"],["Exacto: la marcha en cuatro tiempos resulta difícil con él.","Falso: esa posibilidad es la del reciprocador.","Falso: su control se extiende a la pelvis."]],
  "409": ["¿Cómo funciona un reciprocador?",["La extensión de una cadera flexiona la otra","Ambas caderas se flexionan simultáneamente","Un motor eléctrico controla cada cadera"],["Exacto: ese acoplamiento pasa por un cable arqueado entre ambos lados.","Falso: el mecanismo es alterno por principio.","Falso: el mecanismo es puramente mecánico."]],
  "410": ["¿Exige el reciprocador un control de cadera?",["No, es utilizable incluso sin ese control","Sí, es indispensable un control completo","Sí, pero solo del lado menos afectado"],["Exacto: el mecanismo recíproco suple la ausencia de mando voluntario.","Falso: su interés es precisamente poder prescindir de él.","Falso: no se requiere ningún control."]],
  "411": ["¿Qué marcha prefieren los pacientes equipados con un reciprocador?",["La marcha recíproca, pese a la pendular","La marcha pendular en todas las circunstancias","Exclusivamente la marcha en cuatro tiempos"],["Exacto: emplean la pendular en distancias cortas cuando hay que ir rápido.","Falso: solo se emplea de forma puntual.","Falso: sigue siendo difícil con este tipo de aparato."]],
  "412": ["¿Qué efecto muscular produce la verticalización prolongada en el niño?",["Un alargamiento por adición de sarcómeros","Un acortamiento por pérdida de sarcómeros","Una hipertrofia de las fibras rápidas"],["Exacto: el estiramiento mantenido estimula esa adaptación estructural.","Falso: lo que se produce es lo contrario.","Falso: no es la adaptación descrita."]],
  "413": ["¿Qué duración diaria de verticalización mejora la mineralización ósea?",["Sesenta minutos al día","Diez minutos al día","Cuatro horas al día"],["Exacto: la verticalización mejora además el crecimiento acetabular.","Falso: esa duración es insuficiente.","Falso: esa duración supera la recomendación."]],
  "414": ["¿Qué beneficio articular aporta la verticalización en el niño?",["Un mejor crecimiento acetabular","Una reducción definitiva de la espasticidad","Una corrección de la escoliosis ya instaurada"],["Exacto: completa los beneficios musculares y óseos.","Falso: no se demuestra ningún efecto definitivo de ese tipo.","Falso: no corrige una escoliosis ya constituida."]],
  "415": ["¿Cuál es el principio de las ortesis elásticas dinámicas textiles?",["Mejorar la propiocepción y las sinergias","Inmovilizar rígidamente todas las articulaciones","Sustituir el mando motor deficiente"],["Exacto: están contraindicadas en caso de subluxación de cadera importante o de escoliosis severa.","Falso: su acción es, al contrario, dinámica.","Falso: no sustituyen ningún mando."]],
  "416": ["¿Qué contraindicación tienen las ortesis elásticas dinámicas textiles?",["Una subluxación de cadera de más de la mitad","Una espasticidad moderada del miembro inferior","Un trastorno aislado de la sensibilidad plantar"],["Exacto: la escoliosis severa es la otra contraindicación.","Falso: no constituye una contraindicación.","Falso: esa afectación no es una contraindicación."]],
  "417": ["¿Cuáles son las dos grandes categorías de ortesis del miembro superior?",["Estáticas y dinámicas","Metálicas y plásticas","Prefabricadas y a medida"],["Exacto: las primeras colocan, las segundas acompañan a la función.","Falso: esa distinción se refiere al material, no a la función.","Falso: esa distinción se refiere al modo de fabricación."]],
  "418": ["¿Qué objetivo persigue una ortesis tras una lesión del sistema nervioso central?",["Prevenir las deformidades y reducir el dolor","Sustituir las funciones motoras perdidas","Restablecer el mando nervioso deficiente"],["Exacto: busca también estabilizar la articulación y mejorar la función.","Falso: ese objetivo es el de las lesiones del plexo braquial.","Falso: ninguna ortesis lo consigue."]],
  "419": ["¿Qué objetivo persigue una ortesis tras una lesión del plexo braquial?",["Mantener el miembro en posición funcional","Reducir únicamente la espasticidad de los flexores","Corregir una deformidad ósea ya instaurada"],["Exacto: sustituye además funciones motoras e integra el miembro en las actividades diarias.","Falso: la lesión plexual da una parálisis flácida.","Falso: no es el objetivo descrito."]],
  "420": ["¿A qué temperatura se moldean los termoplásticos de baja temperatura?",["Entre sesenta y setenta grados","Entre cien y ciento veinte grados","A temperatura ambiente"],["Exacto: se moldean directamente sobre el paciente y son reutilizables.","Falso: esa temperatura quemaría la piel.","Falso: es necesario calentarlos previamente."]],
  "421": ["¿Qué inconveniente tienen los termoplásticos de baja temperatura?",["Se deforman con el calor","Son muy pesados de llevar","No son reutilizables"],["Exacto: es la contrapartida de su facilidad de conformado.","Falso: su peso es moderado.","Falso: pueden, al contrario, remodelarse."]],
  "422": ["¿Qué material aporta un calor terapéutico pero no conviene para una inmovilización rígida?",["El neopreno","La fibra de carbono","El termoplástico de baja temperatura"],["Exacto: elástico y confortable, no puede inmovilizar con firmeza.","Falso: es, al contrario, muy rígida.","Falso: ofrece una buena rigidez."]],
  "423": ["¿Qué material conviene particularmente en pediatría o en caso de hipersensibilidad?",["El material de malla termoconformable muy ligero","La fibra de carbono rígida","El metal prefabricado de las ortesis convencionales"],["Exacto: su ligereza y su flexibilidad hacen que se tolere bien.","Falso: es costosa y difícil de modificar.","Falso: su peso lo hace poco adecuado."]],
  "424": ["¿Qué papel desempeñan las espumas en una ortesis?",["El confort y la prevención de las presiones","La rigidez y la sujeción articular","La producción de un calor terapéutico"],["Exacto: no desempeñan ningún papel estructural.","Falso: ese papel corresponde a los materiales estructurales.","Falso: esa propiedad es la del neopreno."]],
  "425": ["¿En qué situación se emplea una ortesis de hombro de reposicionamiento?",["En caso de subluxación o de síndrome hombro-mano","En caso de rigidez postraumática aislada","En caso de fractura reciente de la clavícula"],["Exacto: reduce el peso del brazo y reposiciona dinámicamente la cabeza humeral.","Falso: no es la indicación descrita.","Falso: esa lesión corresponde a otro dispositivo."]],
  "426": ["¿Qué efecto producen las cinchas de una ortesis de hombro de reposicionamiento?",["Un efecto de tracción y de rotación externa","Un efecto de compresión y de rotación interna","Un efecto de bloqueo completo del hombro"],["Exacto: son regulables según la necesidad del paciente.","Falso: la rotación interna es precisamente lo que hay que evitar.","Falso: el dispositivo sigue siendo dinámico."]],
  "427": ["¿Qué ventaja tienen las ortesis de elastómero compresivo sobre las férulas rígidas?",["Permiten un movimiento activo asistido","Inmovilizan la articulación con más firmeza","Son mucho menos costosas de producir"],["Exacto: favorecen además la neuroplasticidad mediante el retorno sensorial.","Falso: su flexibilidad se lo impide.","Falso: el coste no es el argumento que se considera."]],
  "428": ["¿Por qué favorecen la neuroplasticidad las ortesis de elastómero compresivo?",["Por el retorno sensorial que proporcionan","Por el calor que producen localmente","Por la compresión venosa que ejercen"],["Exacto: se adaptan además a la práctica en entorno real.","Falso: no es el mecanismo invocado.","Falso: no es el argumento que se considera."]],
  "429": ["¿A qué parálisis se destina la ortesis de brazo colgante de tipo Stanmore?",["A las parálisis completas del plexo braquial","A las parálisis parciales del plexo braquial","A las hemiplejías espásticas del adulto"],["Exacto: soporta el peso del brazo y evita la luxación glenohumeral.","Falso: estas corresponden al dispositivo de tipo Roehampton.","Falso: ese dispositivo no se les destina."]],
  "430": ["¿Qué permite la ortesis de brazo colgante de tipo Stanmore?",["La flexoextensión del codo y la muñeca","La rotación completa del hombro","La pronosupinación activa del antebrazo"],["Exacto: sustituye igualmente la prensión.","Falso: esa función no se restituye.","Falso: esa función no es la descrita."]],
  "431": ["¿A dónde se transmite la carga del brazo con el dispositivo de tipo Roehampton?",["A una banda pélvica","A la escápula contralateral","A un corsé torácico rígido"],["Exacto: se dirige a las parálisis parciales del plexo braquial.","Falso: no es el punto de apoyo del dispositivo.","Falso: el apoyo se hace en la pelvis."]],
  "432": ["¿Qué condición exige la ortesis funcional de enlaces múltiples?",["Una funcionalidad conservada de la mano","Una fuerza deltoidea suficiente","Una sensibilidad normal del hombro"],["Exacto: en cambio, no necesita ninguna fuerza deltoidea.","Falso: su interés es precisamente poder prescindir de ella.","Falso: no es la condición requerida."]],
  "433": ["¿A qué actividades se destina la ortesis funcional de enlaces múltiples?",["La alimentación y la higiene del rostro","El transporte de cargas pesadas a diario","La conducción de automóviles"],["Exacto: se dirige a esos gestos de proximidad, de la mano a la boca y al rostro.","Falso: no es su destino.","Falso: esa actividad no es la buscada."]],
  "434": ["¿Cuántos grados de libertad comprende la ortesis robotizada monoarticular del codo?",["Uno solo, la flexoextensión","Tres, entre ellos la pronosupinación","Ninguno, inmoviliza el codo"],["Exacto: un sensor electromiográfico detecta la señal del bíceps o del tríceps.","Falso: el dispositivo es monoarticular.","Falso: su papel es, al contrario, asistir el movimiento."]],
  "435": ["¿Cómo detecta la ortesis robotizada del codo la intención del paciente?",["Mediante un sensor electromiográfico","Mediante un sensor de presión plantar","Mediante un mando vocal del paciente"],["Exacto: capta la señal residual del bíceps o del tríceps.","Falso: ese sensor no atañe al miembro superior.","Falso: no es el modo de mando descrito."]],
  "436": ["¿Qué controla la ortesis robotizada multiarticular del miembro superior?",["Hombro, codo, muñeca y mano","Únicamente el codo en flexoextensión","Únicamente la prensión de la mano"],["Exacto: amplifica la señal electromiográfica de los músculos residuales.","Falso: esa limitación es la del dispositivo monoarticular.","Falso: su campo es más amplio."]],
  "437": ["¿Qué se puede decir hoy de las ortesis robotizadas del miembro superior?",["Seguras, intensivas y orientadas a la tarea","Sustituyen enteramente a la rehabilitación manual","Su seguridad no está todavía establecida"],["Exacto: queda por cubrir funciones más complejas y por establecer protocolos rentables.","Falso: la complementan sin sustituirla.","Falso: su inocuidad está, al contrario, documentada."]],
  "438": ["¿Qué caracteriza a las actividades básicas de la vida diaria?",["Aseguran la supervivencia, dirigidas a uno mismo","Sirven de puente hacia la comunidad","Corresponden a la realización personal"],["Exacto: repetidas varias veces al día, exigen un esfuerzo cognitivo mínimo.","Falso: esa descripción es la de las actividades instrumentales.","Falso: esa descripción es la de las actividades avanzadas."]],
  "439": ["¿Qué propiedad tienen las actividades básicas de la vida diaria?",["Son universales, independientes de la cultura","Varían mucho según las culturas","Exigen un esfuerzo cognitivo importante"],["Exacto: se automatizan rápidamente y exigen poco esfuerzo cognitivo.","Falso: su universalidad es, al contrario, característica.","Falso: su automatización las hace poco costosas."]],
  "440": ["¿Cuál de estas actividades forma parte de las actividades básicas?",["El sueño y el descanso","La gestión del propio dinero","La participación social"],["Exacto: la alimentación, la higiene, la sexualidad, el vestido y la movilidad forman parte de ellas igualmente.","Falso: esa actividad es instrumental.","Falso: esa actividad es avanzada."]],
  "441": ["¿Qué caracteriza a las actividades instrumentales?",["Exigen una herramienta y se orientan a los demás","Se dirigen a uno mismo y son automáticas","Corresponden únicamente a la realización personal"],["Exacto: sirven de puente hacia otras actividades.","Falso: esa descripción es la de las actividades básicas.","Falso: esa descripción es la de las actividades avanzadas."]],
  "442": ["¿Cuál de estas actividades es instrumental?",["La gestión de la propia salud","El vestido cotidiano","La actividad profesional"],["Exacto: conducir, gestionar el propio dinero y preparar las comidas lo son igualmente.","Falso: esa actividad es básica.","Falso: esa actividad es avanzada."]],
  "443": ["¿Qué caracteriza a las actividades avanzadas?",["Corresponden a la realización personal","Garantizan la supervivencia inmediata","Solo exigen un dispositivo técnico"],["Exacto: el ocio, el trabajo, los estudios y la participación social forman parte de ellas.","Falso: esa función es la de las actividades básicas.","Falso: esa exigencia caracteriza a las actividades instrumentales."]],
  "444": ["¿Qué capacidades exigen las actividades avanzadas?",["Numerosas capacidades cognitivas y físicas","Un esfuerzo cognitivo mínimo y automatizado","Únicamente el dominio de una herramienta técnica"],["Exacto: son las más complejas de los tres niveles.","Falso: esa característica es la de las actividades básicas.","Falso: esa exigencia es la de las actividades instrumentales."]],
  "445": ["¿Cuántas condiciones definen un buen producto de apoyo?",["Seis","Tres","Diez"],["Exacto: necesario, eficaz, sencillo, no restrictivo, no contraindicado, económico y aceptado.","Falso: ese número es inferior al que se considera.","Falso: ese número es superior al que se considera."]],
  "446": ["¿Qué condición de un buen producto de apoyo atañe al usuario?",["Debe ser aceptado por él","Debe ser lo más sofisticado posible","Debe ser elegido únicamente por la familia"],["Exacto: sin aceptación, el dispositivo mejor diseñado queda sin usar.","Falso: la sencillez forma parte, al contrario, de los criterios.","Falso: es el usuario quien debe aceptarlo."]],
  "447": ["¿Qué es una úlcera por presión?",["Una necrosis localizada mecánica y vascular","Una infección cutánea superficial localizada","Una reacción alérgica al material de apoyo"],["Exacto: se le asocia igualmente una alteración linfática.","Falso: el origen es mecánico y circulatorio, no primitivamente infeccioso.","Falso: no interviene ningún mecanismo alérgico."]],
  "448": ["¿Qué zonas están expuestas a las úlceras por presión en decúbito supino?",["Sacro, apófisis espinosas dorsales y talones","Trocánter y maléolos externos","Las tuberosidades isquiáticas"],["Exacto: en decúbito lateral son el trocánter y los maléolos.","Falso: esas zonas están expuestas en decúbito lateral.","Falso: están expuestas en posición sentada."]],
  "449": ["¿Qué zonas están expuestas a las úlceras por presión en posición sentada?",["Las tuberosidades isquiáticas","El sacro y los talones","El trocánter y los maléolos"],["Exacto: el sacro y los talones están expuestos en decúbito supino.","Falso: esas zonas están expuestas en decúbito supino.","Falso: esas zonas están expuestas en decúbito lateral."]],
  "450": ["¿Qué zonas están expuestas a las úlceras por presión en decúbito lateral?",["El trocánter y los maléolos","Las tuberosidades isquiáticas y el periné","El sacro y las apófisis espinosas dorsales"],["Exacto: las tuberosidades isquiáticas están expuestas en posición sentada.","Falso: esas zonas están expuestas en posición sentada.","Falso: esas zonas están expuestas en decúbito supino."]],
  "451": ["¿En qué fase se aplican los ultravioleta y los infrarrojos sobre una úlcera por presión?",["En fase de granulación del tejido","En fase de infección aguda local","En fase de necrosis negra seca"],["Exacto: se aplican veinte minutos a cuarenta y cinco o cincuenta centímetros.","Falso: la infección contraindica varias de estas técnicas.","Falso: no es la fase indicada."]],
  "452": ["¿A qué distancia se aplican los ultravioleta sobre una úlcera por presión?",["De cuarenta y cinco a cincuenta centímetros","De cinco a diez centímetros","Un metro y medio"],["Exacto: durante veinte minutos, en fase de granulación.","Falso: esa distancia expondría a una quemadura.","Falso: esa distancia haría ineficaz el tratamiento."]],
  "453": ["¿Qué condición plantea el uso del láser y de la electroestimulación sobre una úlcera por presión?",["La ausencia de infección","La presencia de una infección activa","Una necrosis negra extensa"],["Exacto: en presencia de una infección, estas técnicas están contraindicadas.","Falso: es precisamente la contraindicación.","Falso: no es la condición requerida."]],
  "454": ["¿Qué estado cutáneo hay que buscar en la prevención de las úlceras por presión?",["Una piel seca, limpia e hidratada","Una piel húmeda y oclusiva","Una piel masajeada con fuerza de forma regular"],["Exacto: hay además que evitar los sedantes y controlar la espasticidad.","Falso: la humedad favorece la maceración.","Falso: esa práctica es perjudicial en las zonas de riesgo."]],
  "455": ["¿Por qué evitar los sedantes en la prevención de las úlceras por presión?",["Reducen los cambios de posición","Resecan excesivamente la piel","Agravan directamente la espasticidad"],["Exacto: la inmovilidad prolongada es el principal factor de riesgo.","Falso: no es el mecanismo en cuestión.","Falso: tienen más bien el efecto contrario."]],
  "456": ["¿Qué cualidad debe tener un cojín antiescaras?",["Redistribuir las presiones de apoyo","Concentrar los apoyos en las tuberosidades isquiáticas","Ser lo más rígido posible"],["Exacto: debe además evitar roces y cizallamientos, y asegurar la estabilidad.","Falso: es exactamente lo que hay que evitar.","Falso: la rigidez aumenta las presiones localizadas."]],
  "457": ["¿Qué propiedad térmica debe tener un cojín antiescaras?",["Ser isotermo","Ser calefactor de forma permanente","Ser refrigerante de forma continua"],["Exacto: debe además ser absorbente, duradero, ligero y manejable.","Falso: el calor favorece la maceración.","Falso: esa propiedad no se busca."]],
  "458": ["¿A qué pacientes se dirige una grúa de transferencia con arnés completo?",["A los que son incapaces de mantenerse de pie","A los que conservan un buen control del tronco","A los que caminan con dos bastones"],["Exacto: su brazo articulado y su sistema hidráulico elevan enteramente a la persona.","Falso: estos corresponden más bien a una grúa verticalizadora.","Falso: esos pacientes no necesitan una grúa."]],
  "459": ["¿Qué condición exige una grúa verticalizadora?",["A los pacientes incapaces de mantenerse de pie","A los que conservan un buen control del tronco","Una marcha autónoma ya posible"],["Exacto: está destinada a las transferencias cortas y favorece la activación muscular.","Falso: esa situación impone una grúa con arnés completo.","Falso: un paciente autónomo no la necesita."]],
  "460": ["¿Qué beneficio aporta una grúa verticalizadora?",["Un control del tronco y fuerza en las piernas","Una ausencia completa de control del tronco","Sustituye a la rehabilitación de la marcha"],["Exacto: el paciente se levanta mediante un arnés, con los pies apoyados en una plataforma.","Falso: es, al contrario, el esfuerzo buscado lo que constituye su interés.","Falso: no la sustituye."]],
  "461": ["¿Qué es la comunicación aumentativa?",["Activa los músculos y la circulación","Suprime todo esfuerzo del paciente","Un medio reservado a los trastornos auditivos"],["Exacto: la comunicación alternativa la sustituye por entero.","Falso: esa definición es la de la comunicación alternativa.","Falso: su campo es mucho más amplio."]],
  "462": ["¿Qué es la comunicación alternativa?",["Un medio que sustituye a la comunicación oral","Un medio que acompaña a la comunicación oral","Un medio reservado a los niños que no leen"],["Exacto: la comunicación aumentativa, por su parte, la acompaña.","Falso: esa definición es la de la comunicación aumentativa.","Falso: su campo no se limita a esa población."]],
  "463": ["¿Qué modo de acceso conviene a una discapacidad motora severa sin comunicación oral?",["El control visual por seguimiento ocular","Los conmutadores con barrido de iconos","El mando vocal del sistema"],["Exacto: los conmutadores convienen más bien a una discapacidad motora moderada.","Falso: suponen una discapacidad motora moderada.","Falso: supone una comunicación oral conservada."]],
  "464": ["¿Qué modo de acceso conviene a una discapacidad motora moderada?",["El control visual por seguimiento ocular","Los conmutadores con barrido de iconos","La escritura con teclado clásico a dos manos"],["Exacto: la selección se hace accionando en el momento deseado.","Falso: se dirige a las discapacidades motoras severas.","Falso: no es un modo de acceso adaptado de los descritos."]],
  "465": ["¿Qué permite el mando vocal en un paciente con discapacidad motora severa?",["El control de la domótica y las alertas de urgencia","Únicamente el acceso a un teclado virtual","Únicamente el control de la silla de ruedas"],["Exacto: supone una comunicación oral conservada.","Falso: su campo es más amplio.","Falso: esa limitación no corresponde a la herramienta."]],
  "466": ["¿Qué alteración participa en la formación de una úlcera por presión?",["Domótica y alertas de urgencia","Únicamente el acceso a un teclado virtual","Una alteración puramente nerviosa periférica"],["Exacto: esos tres mecanismos se conjugan para producir la necrosis.","Falso: la infección es una complicación, no la causa.","Falso: la denervación favorece sin constituir el mecanismo."]],
  "467": ["¿Qué técnica de drenaje se aplica en el abordaje de las úlceras por presión?",["Mecánica, vascular y linfática","Una alteración puramente infecciosa","El drenaje quirúrgico sistemático"],["Exacto: se añade al tratamiento postural y a las técnicas físicas.","Falso: esa técnica atañe al aparato respiratorio.","Falso: no es sistemático."]],
  "468": ["¿Por qué controlar la espasticidad en la prevención de las úlceras por presión?",["Crea apoyos anormales y roces","Provoca una infección cutánea directa","Aumenta la sensibilidad de la piel"],["Exacto: forma parte de los factores que hay que dominar, junto con la hidratación cutánea.","Falso: su papel no es infeccioso.","Falso: no es el mecanismo en cuestión."]],
  "469": ["¿Qué actividad instrumental atañe a la comunicación?",["Crea apoyos y roces","Provoca una infección cutánea directa","La participación social ampliada"],["Exacto: figura en la lista junto con la conducción y la gestión del dinero.","Falso: esa actividad es básica.","Falso: esa actividad es avanzada."]],
  "470": ["¿Qué actividad corresponde al nivel avanzado?",["La actividad académica","La preparación de las comidas","El aseo cotidiano"],["Exacto: el ocio, el trabajo y la participación social completan ese nivel.","Falso: esa actividad es instrumental.","Falso: esa actividad es básica."]],
  "471": ["¿Cuál era el objetivo dominante de la rehabilitación antes de mil novecientos cuarenta?",["La compensación","La facilitación del movimiento","El aprendizaje motor estructurado"],["Exacto: la facilitación del movimiento llega después, entre el cuarenta y el sesenta.","Falso: ese objetivo domina entre mil novecientos cuarenta y sesenta.","Falso: ese objetivo aparece en los años setenta."]],
  "472": ["¿Qué objetivo se impone a partir de los años ochenta?",["La mejoría funcional, no la compensación","La compensación del déficit residual","La facilitación pasiva del movimiento"],["Exacto: esa evolución ha acabado eclipsando al déficit como objetivo.","Falso: ese objetivo es el más antiguo.","Falso: ese objetivo corresponde a los años cuarenta a sesenta."]],
  "473": ["¿Qué tensión atraviesa hoy la rehabilitación neurológica?",["La función ha eclipsado al déficit como objetivo","El déficit ha eclipsado a la función","Ambos objetivos han desaparecido en favor del confort"],["Exacto: ahora bien, la neurociencia de la plasticidad se concentra más bien en la reducción del déficit.","Falso: lo que se describe es lo contrario.","Falso: esa evolución no se describe."]],
  "474": ["¿Qué define una terapia intensiva?",["Mucha práctica activa, en un tiempo concentrado","Una sesión de larga duración, cualquiera que sea la actividad","Una frecuencia elevada de sesiones muy cortas"],["Exacto: con repetición de las tareas funcionales más significativas.","Falso: la pasividad anula el beneficio buscado.","Falso: la frecuencia por sí sola no define la intensidad."]],
  "475": ["¿Cómo se define la intensidad de una terapia?",["El volumen de práctica: repeticiones, duración y frecuencia","El reparto de la terapia a lo largo del tiempo","La cantidad de trabajo más la duración de la sesión"],["Exacto: la dosis añade la duración de la sesión y la dosificación su reparto a lo largo del tiempo.","Falso: esa noción es la de la dosificación.","Falso: esa noción es la de la dosis."]],
  "476": ["¿Qué designa la dosificación de una terapia?",["Su reparto a lo largo del tiempo","La cantidad de trabajo por sesión","La intensidad sumada a la duración de la sesión"],["Exacto: la intensidad es la cantidad de trabajo dentro de una sesión.","Falso: esa noción es la intensidad.","Falso: esa noción es la dosis."]],
  "477": ["¿Qué es una asistencia robótica pasiva?",["El robot guía, sin esfuerzo del paciente","El paciente inicia y el robot completa","El robot resiste o asiste según la necesidad"],["Exacto: es útil en fase precoz, cuando el paciente no puede iniciar.","Falso: esa descripción es la de la asistencia activa.","Falso: esa descripción es la de los sistemas interactivos."]],
  "478": ["¿Qué es una asistencia robótica activa?",["El paciente inicia y el robot solo ayuda cuando es necesario","El robot guía enteramente el movimiento","El miembro sano pilota el miembro afectado"],["Exacto: se asocia a los aspectos sensitivomotores corticales.","Falso: esa descripción es la de la asistencia pasiva.","Falso: esa descripción es la de la asistencia bilateral."]],
  "479": ["¿Qué es una asistencia robótica bilateral?",["La actividad del miembro sano se refleja en el afectado","El robot asiste a ambos miembros por igual","Dos robots trabajan simultáneamente sobre un miembro"],["Exacto: el movimiento del lado válido guía o asiste al lado afectado.","Falso: el principio se basa en el reflejo del lado sano.","Falso: no es el principio descrito."]],
  "480": ["¿A qué procesos se asocia la terapia robótica pasiva?",["A procesos cognitivos","A aspectos sensitivomotores corticales","A mecanismos puramente medulares"],["Exacto: la terapia activa se asocia a los aspectos sensitivomotores corticales.","Falso: esos aspectos corresponden a la terapia activa.","Falso: no es la asociación descrita."]],
  "481": ["¿Qué estructura robótica conviene mejor al domicilio?",["La estructura portátil y flexible","El exoesqueleto articulado","El efector final estacionario"],["Exacto: su ligereza y su flexibilidad la hacen utilizable fuera de un centro asistencial.","Falso: su volumen y su ajuste lo reservan al centro.","Falso: supone un entorno controlado."]],
  "482": ["¿Qué limitación impone un exoesqueleto?",["Sus articulaciones deben seguir las del paciente","Solo puede contactar con el paciente en el antebrazo","Solo funciona en asistencia pasiva"],["Exacto: una desalineación obliga a interrumpir la sesión para reajustar.","Falso: esa limitación es la del efector final.","Falso: puede funcionar en varios modos."]],
  "483": ["¿Qué ventaja presenta un exoesqueleto?",["Conviene si se requiere un soporte completo","Se adapta con mucha facilidad a todos los pacientes","Es el más ligero de los tres tipos"],["Exacto: limita, no obstante, los movimientos más que el efector final.","Falso: esa facilidad de adaptación es la del efector final.","Falso: la estructura portátil y flexible lo es más."]],
  "484": ["¿Mediante qué está en contacto un efector final con el paciente?",["Mediante una ortesis en el antebrazo o en la pierna","Mediante una estructura que sigue toda la articulación","Mediante un arnés que rodea todo el tronco"],["Exacto: ese contacto único le permite adaptarse a morfologías variadas.","Falso: esa descripción es la del exoesqueleto.","Falso: no es el modo de contacto descrito."]],
  "485": ["¿A qué está mejor adaptado el efector final?",["A la repetición intensiva, en medio controlado","Al entrenamiento en el domicilio del paciente","Al soporte completo de un miembro totalmente paralizado"],["Exacto: se adapta además mejor a los distintos pacientes.","Falso: ese uso corresponde a los dispositivos portátiles.","Falso: esa situación corresponde más bien al exoesqueleto."]],
  "486": ["¿Qué es un grado de libertad?",["Un movimiento independiente posible del dispositivo","El número de articulaciones del paciente cubiertas","La fuerza máxima entregada por el motor"],["Exacto: puede ser traslacional en los tres ejes o rotacional.","Falso: no es la definición que se considera.","Falso: la fuerza no entra en esa definición."]],
  "487": ["¿Cuántos grados de libertad comprende un exoesqueleto de marcha?",["Unos dos","Unos seis","Más de diez"],["Exacto: un robot de brazo tiene de tres a seis.","Falso: ese número corresponde más bien a un robot de brazo.","Falso: ese número atañe a los dispositivos complejos para la mano."]],
  "488": ["¿Qué mostraban los primeros resultados de la terapia robótica del miembro superior?",["Hombro y codo, pero no la mano","Una mejoría sobre todo de la mano y los dedos","Ninguna mejoría en ningún segmento"],["Exacto: la transferencia a las actividades diarias seguía siendo escasa.","Falso: es precisamente lo que faltaba.","Falso: sí se observaba un beneficio proximal."]],
  "489": ["¿Qué se puede decir de las mejorías obtenidas por la terapia robótica del miembro superior?",["Significativas, pero sin relevancia clínica","Superan con mucho el umbral de relevancia clínica","No son estadísticamente significativas"],["Exacto: se mantienen por debajo de la diferencia mínima clínicamente importante.","Falso: ese umbral justamente no se alcanza.","Falso: la significación estadística sí se obtiene."]],
  "490": ["¿Qué proporción de pacientes no recupera nunca un miembro superior satisfactorio?",["Del treinta al sesenta por ciento","Menos del cinco por ciento","Más del noventa por ciento"],["Exacto: y eso pese a una rehabilitación intensiva.","Falso: esa estimación es muy optimista.","Falso: esa proporción está sobreestimada."]],
  "491": ["¿Qué característica es común a los robots de marcha?",["El soporte parcial del peso del cuerpo","La presencia de una cinta rodante","El control de la marcha en los tres planos"],["Exacto: estáticos, portátiles, efectores finales e híbridos lo comparten.","Falso: los dispositivos portátiles no la llevan.","Falso: el control suele limitarse al plano sagital."]],
  "492": ["¿Cuántos grados de libertad comprende un exoesqueleto de marcha con cinta?",["Dos, en las caderas y en las rodillas","Cuatro, en las caderas, rodillas y tobillos","Seis, repartidos por todo el miembro"],["Exacto: la rehabilitación se limita, por tanto, al plano sagital.","Falso: el tobillo no está motorizado en este dispositivo.","Falso: ese número corresponde a los robots de brazo."]],
  "493": ["¿Cuántos pasos se obtienen por sesión de treinta minutos con un exoesqueleto de marcha?",["Más de mil","Unos cien","Unos trescientos"],["Exacto: la terapia convencional solo permite de cincuenta a cien.","Falso: esa cifra es la de la terapia convencional.","Falso: esa cifra subestima ampliamente el rendimiento del dispositivo."]],
  "494": ["¿A qué plano se limita la rehabilitación mediante exoesqueleto de marcha con cinta?",["El plano sagital","El plano frontal","Los tres planos del espacio"],["Exacto: a ello se añaden el coste elevado y la necesidad de personal cualificado.","Falso: ese plano no se trabaja con este dispositivo.","Falso: el dispositivo no los cubre."]],
  "495": ["¿Qué se puede decir de la robótica de marcha en el paciente crónico?",["Ninguna ventaja demostrada sobre lo convencional","Una superioridad nítida sobre la terapia convencional","Una inferioridad nítida y un riesgo aumentado"],["Exacto: sigue siendo, en cambio, una buena herramienta asociada a la terapia neurológica.","Falso: esa superioridad no está demostrada.","Falso: no se describe ninguna inferioridad de ese tipo."]],
  "496": ["¿Para qué perfil resulta interesante la robótica de marcha?",["El paciente que anda solo, para la velocidad","El paciente totalmente encamado y no cooperador","El paciente crónico sin ninguna marcha residual"],["Exacto: la combinación de lo convencional y lo robótico optimiza los resultados.","Falso: la falta de cooperación es una contraindicación.","Falso: no se demuestra ninguna ventaja en ese perfil."]],
  "497": ["¿Qué dispositivos se muestran ligeramente superiores en la rehabilitación de la marcha?",["Los efectores finales","Los exoesqueletos portátiles","Los dispositivos híbridos"],["Exacto: superan ligeramente a los exoesqueletos en los datos disponibles.","Falso: se muestran ligeramente menos eficaces.","Falso: no es la comparación referida."]],
  "498": ["¿Qué descarga de peso no hay que superar después de un accidente cerebrovascular?",["El treinta por ciento","El cincuenta por ciento","El diez por ciento"],["Exacto: en las lesiones medulares puede alcanzar el cincuenta por ciento o más.","Falso: ese nivel atañe a las lesiones medulares.","Falso: ese nivel es demasiado restrictivo."]],
  "499": ["¿Qué duración de sesión se recomienda en rehabilitación robótica de la marcha?",["De quince a veinte minutos","De una a dos horas","Cinco minutos como máximo"],["Exacto: a razón de tres a cinco sesiones semanales durante cuatro a seis semanas.","Falso: esa duración supera con mucho el protocolo.","Falso: esa duración resultaría insuficiente."]],
  "500": ["¿A qué velocidad se realiza el entrenamiento robótico de la marcha?",["De cero coma uno a dos coma ocho kilómetros por hora","De cinco a ocho kilómetros por hora","A velocidad libre elegida por el paciente"],["Exacto: la progresión se realiza a lo largo de cuatro a seis semanas.","Falso: esa velocidad es mucho demasiado elevada.","Falso: la velocidad se parametriza."]],
  "501": ["¿Qué peso contraindica la rehabilitación robótica de la marcha?",["Más de ciento treinta y cinco kilogramos","Más de ochenta kilogramos","Menos de cuarenta kilogramos"],["Exacto: las contracturas fijas y la osteoporosis severa son otras contraindicaciones.","Falso: ese umbral es bastante inferior al límite real.","Falso: no se considera ningún umbral bajo de ese tipo."]],
  "502": ["¿Qué estado óseo contraindica la rehabilitación robótica de la marcha?",["Una osteoporosis severa o una inestabilidad ósea","Una osteopenia moderada aislada","Una fractura consolidada desde hace un año"],["Exacto: una artrodesis de cadera o de rodilla también lo impide.","Falso: no constituye una contraindicación.","Falso: esa situación no es una contraindicación."]],
  "503": ["¿Qué conducta contraindica la rehabilitación robótica de la marcha?",["La falta de cooperación o la agresividad","Una ansiedad ligera ante el aparato","Una fatigabilidad moderada al final de la sesión"],["Exacto: un déficit cognitivo severo es igualmente excluyente.","Falso: no constituye una contraindicación.","Falso: obliga a adaptar la duración, no a excluir."]],
  "504": ["¿Qué particularidad morfológica contraindica la rehabilitación robótica de la marcha?",["Una diferencia de longitud de los miembros","Una ligera desigualdad de menos de un centímetro","Un pie plano bilateral reductible"],["Exacto: una escoliosis severa figura igualmente entre las contraindicaciones.","Falso: semejante diferencia no tiene consecuencias.","Falso: esa particularidad no es una contraindicación."]],
  "505": ["¿A partir de qué descarga de peso se reduce claramente la actividad muscular?",["El cuarenta por ciento o más","El diez por ciento o más","El ochenta por ciento o más"],["Exacto: hasta el treinta por ciento, los parámetros de marcha se modifican poco.","Falso: ese nivel es demasiado bajo para modificar la actividad muscular.","Falso: el umbral determinante es bastante anterior."]],
  "506": ["¿Qué músculo resulta más afectado por la descarga de peso?",["El recto femoral","El tríceps sural","El glúteo medio"],["Exacto: cuanto mayor es el soporte, más se alarga el ciclo de marcha.","Falso: no es el músculo más implicado.","Falso: no es el más afectado."]],
  "507": ["¿Qué efecto tiene un soporte de peso importante sobre la marcha?",["Alarga el ciclo de marcha","Acorta el ciclo de marcha","No modifica el ciclo de marcha"],["Exacto: el recto femoral es el músculo más afectado.","Falso: lo que se observa es lo contrario.","Falso: el efecto está bien documentado."]],
  "508": ["¿Qué trabaja el modo de pie de una cinta con plataforma de fuerza y realidad aumentada?",["El equilibrio y la simetría de las cargas","La capacidad de paso y el apoyo monopodal","La funcionalidad y la adaptabilidad de la marcha"],["Exacto: el modo paso trabaja la capacidad de paso y el apoyo monopodal.","Falso: ese trabajo corresponde al modo paso.","Falso: ese trabajo corresponde al modo marcha."]],
  "509": ["¿Qué trabaja el modo marcha de una cinta con plataforma de fuerza y realidad aumentada?",["La funcionalidad y la adaptabilidad","El equilibrio y la simetría de las cargas","La capacidad de paso y el apoyo monopodal"],["Exacto: el dispositivo exige un tono de base funcional previo.","Falso: ese trabajo corresponde al modo de pie.","Falso: ese trabajo corresponde al modo paso."]],
  "510": ["¿A qué paciente se destina un dispositivo de soporte dinámico en el suelo?",["Al paciente que empieza a andar","Al paciente totalmente encamado","Al paciente que ya anda sin ayuda"],["Exacto: permite una marcha autodirigida fuera de la cinta.","Falso: ese perfil corresponde a otros dispositivos.","Falso: no le resultaría de utilidad."]],
  "511": ["¿Qué permite un sistema de soporte tridimensional mediante arnés?",["Asistencia vertical y horizontal libre","Una asistencia estrictamente vertical en el sitio","Una suspensión completa que suprime todo apoyo"],["Exacto: la persona puede desplazarse en el espacio sin quedar obligada a un eje.","Falso: la dimensión horizontal constituye su particularidad.","Falso: el apoyo sigue siendo parcial."]],
  "512": ["¿Cuál es el principio común de las neuroestimulaciones no invasivas?",["Modificar la probabilidad de descarga neuronal","Desencadenar directamente potenciales de acción","Destruir selectivamente redes hiperactivas"],["Exacto: esa modulación actúa después sobre la plasticidad sináptica.","Falso: la estimulación modula la probabilidad sin imponerla.","Falso: no se produce ninguna lesión."]],
  "513": ["¿Qué traduce una potenciación a largo plazo?",["Un aumento de la eficacia sináptica","Una disminución de la eficacia sináptica","Una destrucción de las sinapsis implicadas"],["Exacto: la depresión a largo plazo produce el efecto inverso.","Falso: esa disminución es la depresión a largo plazo.","Falso: no interviene ninguna destrucción."]],
  "514": ["¿Qué técnica pertenece a la familia de las estimulaciones magnéticas?",["La estimulación magnética transcraneal","La estimulación por corriente continua","La estimulación por corriente alterna"],["Exacto: la estimulación por corriente continua pertenece a la familia eléctrica.","Falso: corresponde a la familia eléctrica.","Falso: corresponde igualmente a la familia eléctrica."]],
  "515": ["¿Qué neuronas despolariza sobre todo la estimulación magnética transcraneal?",["Las neuronas piramidales","Las interneuronas inhibidoras profundas","Las células gliales de la corteza"],["Exacto: el campo magnético induce un campo eléctrico que las despolariza.","Falso: no son las células afectadas preferentemente.","Falso: las células gliales no generan potenciales de acción."]],
  "516": ["¿Qué factor reduce la eficacia de la estimulación magnética transcraneal?",["La distancia entre la bobina y el tejido","El color de la bobina empleada","Únicamente la hora del día"],["Exacto: el grosor del cráneo influye, por tanto, directamente en el umbral motor.","Falso: ese parámetro no tiene ninguna influencia.","Falso: la fatiga cuenta, pero no es el factor descrito."]],
  "517": ["¿Qué mide la latencia de un potencial motor evocado?",["La velocidad de conducción nerviosa","El número de unidades motoras activadas","La sensibilidad del sistema motor"],["Exacto: la amplitud informa del número de unidades motoras activadas.","Falso: esa información la da la amplitud.","Falso: esa información la da el umbral motor."]],
  "518": ["¿Qué mide la amplitud de un potencial motor evocado?",["El número de unidades motoras activadas","La velocidad de conducción nerviosa","El grosor del cráneo del paciente"],["Exacto: la latencia informa de la velocidad de conducción.","Falso: esa información la da la latencia.","Falso: ese dato influye en el umbral, sin ser medido."]],
  "519": ["¿Para qué sirve el umbral motor en la estimulación magnética diagnóstica?",["Para comparar ambos hemisferios","Para medir la velocidad de conducción","Para contar las unidades motoras reclutadas"],["Exacto: traduce la sensibilidad del sistema motor.","Falso: esa medida corresponde a la latencia.","Falso: esa medida corresponde a la amplitud."]],
  "520": ["¿Qué efecto produce una estimulación magnética repetitiva de alta frecuencia?",["Un efecto excitador","Un efecto inhibidor","Ningún efecto sobre la excitabilidad cortical"],["Exacto: se dirige a las zonas hipoactivas, a partir de cinco hercios.","Falso: ese efecto se obtiene a baja frecuencia.","Falso: el efecto es nítido y está bien documentado."]],
  "521": ["¿A qué zonas se dirige la estimulación magnética repetitiva de baja frecuencia?",["A las zonas hiperactivas","A las zonas hipoactivas","A las zonas totalmente destruidas"],["Exacto: el hemisferio contralateral después de un accidente cerebrovascular es el ejemplo de ello.","Falso: estas corresponden a la alta frecuencia.","Falso: una zona destruida no puede modularse."]],
  "522": ["¿Qué intensidad se emplea en la estimulación magnética repetitiva de alta frecuencia?",["Del ciento diez al ciento veinte por ciento del umbral","Del noventa al cien por cien del umbral","El cincuenta por ciento del umbral motor"],["Exacto: las sesiones duran de veinte a cuarenta minutos.","Falso: esa intensidad corresponde a la baja frecuencia.","Falso: esa intensidad resultaría insuficiente."]],
  "523": ["¿Qué duración de sesión se aplica en baja frecuencia?",["De quince a treinta minutos","De veinte a cuarenta minutos","De dos a tres minutos"],["Exacto: la alta frecuencia exige de veinte a cuarenta minutos.","Falso: esa duración corresponde a la alta frecuencia.","Falso: esa duración resultaría muy insuficiente."]],
  "524": ["¿Qué factor hace variar el umbral motor?",["El grosor del cráneo y la fatiga","El color del cabello del paciente","La temperatura ambiente de la sala"],["Exacto: la edad, el sexo, la medicación y la orientación de la bobina cuentan igualmente.","Falso: ese parámetro no tiene ninguna influencia.","Falso: ese factor no se considera."]],
  "525": ["¿Qué riesgo infrecuente conlleva la estimulación magnética transcraneal?",["Una crisis convulsiva","Una hemorragia cerebral","Una pérdida de memoria definitiva"],["Exacto: las cefaleas, los acúfenos y los vértigos son más frecuentes pero benignos.","Falso: ese riesgo no se describe.","Falso: no se describe ningún efecto de ese tipo."]],
  "526": ["¿Qué contraindicación absoluta tiene la estimulación magnética transcraneal?",["Un implante metálico en la cabeza","Una migraña antigua tratada","Un traumatismo craneal antiguo"],["Exacto: el embarazo y todo material ferromagnético la contraindican igualmente.","Falso: exige una precaución, no una contraindicación absoluta.","Falso: impone una precaución y no una prohibición."]],
  "527": ["¿Qué intensidad de corriente emplea la estimulación transcraneal por corriente continua?",["De uno a dos miliamperios","De diez a veinte miliamperios","Cien miliamperios"],["Exacto: esa intensidad muy baja modula sin desencadenar potenciales de acción.","Falso: esa intensidad resultaría dolorosa y peligrosa.","Falso: esa intensidad está muy por encima del dispositivo."]],
  "528": ["¿Qué modula la estimulación transcraneal por corriente continua?",["El potencial de membrana en reposo","El número de sinapsis disponibles","La velocidad de conducción axonal"],["Exacto: hace a las neuronas más o menos susceptibles de dispararse.","Falso: su acción es eléctrica e inmediata.","Falso: no es el parámetro modulado."]],
  "529": ["¿Qué efecto produce el ánodo en la estimulación por corriente continua?",["Despolarización parcial, excitabilidad aumentada","Hiperpolarización parcial, excitabilidad reducida","Ninguna modificación de la excitabilidad local"],["Exacto: se coloca sobre las zonas que hay que reforzar.","Falso: ese efecto es el del cátodo.","Falso: el efecto está bien establecido."]],
  "530": ["¿Dónde se coloca el cátodo en la estimulación por corriente continua?",["Sobre una zona con hiperexcitabilidad que hay que reducir","Sobre una zona hipoactiva que hay que reforzar","Siempre sobre el hombro contralateral"],["Exacto: la corriente sale por él, produciendo una hiperpolarización parcial.","Falso: esa zona recibe el ánodo.","Falso: la colocación depende del objetivo."]],
  "531": ["¿Por qué se aplica una subida y una bajada progresivas de la corriente?",["Para evitar los hormigueos","Para aumentar el efecto sobre la plasticidad","Para ahorrar batería del dispositivo"],["Exacto: esas rampas hacen que la sesión se tolere mejor.","Falso: no es la razón invocada.","Falso: esa consideración no entra en juego."]],
  "532": ["¿Cómo se calcula la densidad de corriente?",["La intensidad dividida por la superficie del electrodo","La superficie dividida por la intensidad aplicada","La intensidad multiplicada por la duración de la sesión"],["Exacto: dos miliamperios en treinta y cinco centímetros cuadrados dan unos cero coma cero seis.","Falso: la razón está invertida.","Falso: ese producto no define la densidad."]],
  "533": ["¿Qué solución empapa las esponjas de los electrodos?",["Cloruro de sodio al cero coma nueve por ciento","Agua destilada pura","Un gel alcohólico antiséptico"],["Exacto: la duración de la sesión es de diez a treinta minutos.","Falso: conduce mal la corriente.","Falso: irritaría la piel."]],
  "534": ["¿Qué dice la ley de conservación de la corriente con dos ánodos y un cátodo?",["La suma de las salientes iguala a la entrante","Cada ánodo entrega la corriente total ajustada","El cátodo no recibe ninguna corriente"],["Exacto: la suma de las superficies anódicas debe mantenerse próxima o inferior a la del cátodo.","Falso: la corriente se reparte entre los ánodos.","Falso: recibe la totalidad de la corriente saliente."]],
  "535": ["¿Por qué la superficie de los ánodos debe mantenerse próxima a la del cátodo?",["Para evitar un punto de irritación o un riesgo térmico","Para aumentar el efecto sobre la plasticidad","Para reducir el consumo del dispositivo"],["Exacto: una densidad de corriente demasiado elevada crearía un punto caliente.","Falso: no es la razón invocada.","Falso: esa consideración es ajena al problema."]],
  "536": ["¿Qué es una estimulación por corriente continua aplicada antes de la tarea?",["Fuera de línea, prepara la excitabilidad","En línea, interactúa con la tarea","Una estimulación sin efecto demostrado"],["Exacto: la estimulación en línea actúa durante la tarea, con efectos más específicos.","Falso: esa modalidad se aplica durante la tarea.","Falso: su efecto preparatorio está documentado."]],
  "537": ["¿Qué ventaja presenta una estimulación aplicada durante la tarea?",["Efectos más específicos, ligados al estado funcional","Efectos más duraderos pero menos dirigidos","Una ausencia total de efectos indeseables"],["Exacto: interactúa directamente con los procesos activos.","Falso: la especificidad es precisamente su ventaja.","Falso: los efectos cutáneos siguen siendo posibles."]],
  "538": ["¿Qué contraindicación tiene la estimulación transcraneal por corriente continua?",["Una lesión cutánea bajo los electrodos","Una piel sana y bien hidratada","Una fatiga ligera del paciente"],["Exacto: el embarazo y los dispositivos electrónicos implantados la contraindican también.","Falso: es, al contrario, la situación ideal.","Falso: no constituye una contraindicación."]],
  "539": ["¿Qué es la estimulación eléctrica neuromuscular?",["Una contracción por estimulación del nervio","Una estimulación aplicada durante una tarea","Una estimulación que se dirige a las fibras sensitivas"],["Exacto: sirve para el fortalecimiento y la prevención de la atrofia.","Falso: esa aplicación define la estimulación funcional.","Falso: esa diana es la de la neuroestimulación transcutánea."]],
  "540": ["¿Qué distingue a la estimulación eléctrica funcional?",["Se aplica durante una tarea funcional","Se dirige preferentemente a las fibras sensitivas","No provoca ninguna contracción muscular"],["Exacto: queda así integrada en el movimiento voluntario.","Falso: esa diana es la de la neuroestimulación transcutánea.","Falso: la contracción es, al contrario, lo que se busca."]],
  "541": ["¿Qué fibras estimula la neuroestimulación eléctrica transcutánea?",["Las fibras sensitivas","Las fibras motoras alfa","Las fibras simpáticas posganglionares"],["Exacto: su uso clásico es analgésico, y hoy también antiespástico.","Falso: esa diana es la de la estimulación neuromuscular.","Falso: no son la diana del dispositivo."]],
  "542": ["¿Qué orden de reclutamiento sigue la estimulación eléctrica neuromuscular?",["Las fibras rápidas primero","Las fibras lentas primero","Todas las fibras simultáneamente"],["Exacto: es lo contrario de la contracción voluntaria, de ahí el término de reclutamiento invertido.","Falso: ese orden es el de la contracción voluntaria.","Falso: el reclutamiento sigue siendo ordenado."]],
  "543": ["¿Qué contraindicación absoluta tiene la estimulación eléctrica neuromuscular?",["Un marcapasos implantado","Una epilepsia bien controlada","Una alteración ligera de la sensibilidad"],["Exacto: las lesiones cutáneas en la zona la contraindican igualmente.","Falso: constituye una contraindicación relativa.","Falso: corresponde igualmente a las relativas."]],
  "544": ["¿Qué contraindicación relativa tiene la estimulación eléctrica neuromuscular?",["Una epilepsia no controlada","Un marcapasos implantado","Una herida abierta bajo el electrodo"],["Exacto: el embarazo, los tumores, la trombosis y los trastornos sensitivos lo son igualmente.","Falso: se trata de una contraindicación absoluta.","Falso: esa situación es una contraindicación absoluta."]],
  "545": ["¿Qué criterio neurológico condiciona la estimulación eléctrica funcional?",["Un sistema nervioso periférico indemne","Una lesión periférica completa","Una ausencia total de mando central"],["Exacto: sin integridad periférica no se obtiene ninguna respuesta.","Falso: haría ineficaz la estimulación.","Falso: no es el criterio que se considera."]],
  "546": ["¿Qué grado de espasticidad permite la estimulación eléctrica funcional?",["Menos de dos o tres en la escala de Ashworth","Más de tres en la escala de Ashworth","Cualquier valor, la espasticidad no importa"],["Exacto: por encima, la estimulación se vuelve ineficaz o mal tolerada.","Falso: ese nivel es, al contrario, excluyente.","Falso: constituye un criterio explícito."]],
  "547": ["¿Cuál es la segunda etapa de un programa de estimulación funcional?",["El acondicionamiento muscular previo","La selección del paciente candidato","La integración en las actividades diarias"],["Exacto: la selección del paciente la precede y el entrenamiento funcional le sigue.","Falso: esa etapa es la primera.","Falso: esa etapa es la última."]],
  "548": ["¿Qué duración de contracción se recomienda en estimulación funcional?",["De diez a veinte segundos","De uno a dos segundos","De uno a dos minutos"],["Exacto: con diez a treinta segundos de reposo entre las contracciones.","Falso: esa duración es demasiado breve.","Falso: esa duración provocaría una fatiga excesiva."]],
  "549": ["¿Qué duración total de sesión se recomienda en estimulación funcional?",["De veinte a treinta minutos","Cinco minutos como máximo","Dos horas consecutivas"],["Exacto: a razón de tres a cinco días por semana.","Falso: esa duración es insuficiente.","Falso: esa duración es excesiva."]],
  "550": ["¿Qué frecuencia de neuroestimulación transcutánea reduce la espasticidad?",["La baja frecuencia, de uno a diez hercios","La alta frecuencia, de veinte a cien hercios","Cualquier frecuencia, sin distinción"],["Exacto: su efecto es inhibidor sobre los reflejos espinales.","Falso: facilita, al contrario, la activación motora.","Falso: el efecto depende estrechamente de la frecuencia."]],
  "551": ["¿Qué frecuencia de neuroestimulación transcutánea facilita la activación motora?",["La alta frecuencia, de veinte a cien hercios","La baja frecuencia, de uno a diez hercios","La frecuencia nula, en corriente continua"],["Exacto: la baja frecuencia produce el efecto inverso, inhibidor.","Falso: reduce, al contrario, la espasticidad.","Falso: ese modo corresponde a la estimulación transcraneal."]],
  "552": ["¿Qué intensidad se emplea en neuroestimulación transcutánea en neurología?",["Sensorial o en el límite motor, sin contracción","Máxima, con contracción visible y sostenida","Infraliminar, sin ninguna sensación percibida"],["Exacto: una contracción visible sobrepasaría el objetivo buscado.","Falso: aquí no se busca la contracción.","Falso: la sensación debe percibirse."]],
  "553": ["¿Mediante qué mecanismo reduce la neuroestimulación transcutánea la espasticidad?",["Las aferencias cutáneas inhiben los reflejos","Fatiga directamente el músculo espástico","Bloquea la conducción del nervio motor"],["Exacto: las aferencias propioceptivas participan en el mismo mecanismo.","Falso: no se produce ninguna contracción.","Falso: no es el mecanismo descrito."]],
  "554": ["¿Qué uso clásico tiene la neuroestimulación eléctrica transcutánea?",["La analgesia","El fortalecimiento muscular","La prevención de la atrofia"],["Exacto: la modulación de la espasticidad es un uso más reciente.","Falso: ese uso es el de la estimulación neuromuscular.","Falso: ese objetivo corresponde igualmente a la estimulación neuromuscular."]],
  "555": ["¿A qué zona se dirige la alta frecuencia magnética en la depresión mayor?",["A la corteza prefrontal dorsolateral izquierda","Al hemisferio contralateral a la lesión","A la corteza motora primaria derecha"],["Exacto: es una zona hipoactiva, que se trata de reactivar.","Falso: esa diana corresponde a la baja frecuencia después de un accidente cerebrovascular.","Falso: esa diana no es la descrita aquí."]],
  "556": ["¿Por qué vía desciende la señal durante una estimulación magnética diagnóstica?",["Por la vía corticoespinal, hasta las alfa","Por las columnas dorsales y el lemnisco","Por el haz espinotalámico anterior"],["Exacto: el electromiograma registra entonces el potencial motor evocado.","Falso: esas vías son sensitivas y ascendentes.","Falso: esa vía es igualmente sensitiva."]],
  "557": ["¿Cuál es el principio de la terapia por restricción inducida?",["Restringir el miembro válido e intensificar el afectado","Restringir el miembro afectado para protegerlo","Movilizar ambos miembros de forma simétrica"],["Exacto: una férula, un guante o un vendaje restringen el lado válido.","Falso: es el miembro válido el que se restringe.","Falso: la asimetría deliberada constituye todo el principio."]],
  "558": ["¿Qué protocolo se propone en terapia por restricción inducida?",["Seis horas por semana, seis horas de restricción","Una hora por semana, sin restricción asociada","Una restricción permanente de día y de noche"],["Exacto: no existe, sin embargo, un consenso total sobre el protocolo.","Falso: la restricción es inseparable del método.","Falso: la restricción se limita a una parte del día."]],
  "559": ["¿Qué suscita consenso en la terapia por restricción inducida?",["La eficacia de la restricción del lado funcional","La duración exacta de restricción diaria","El número de sesiones semanales requerido"],["Exacto: el protocolo preciso, en cambio, no es unánime.","Falso: es precisamente lo que varía según los equipos.","Falso: ese parámetro no suscita consenso."]],
  "560": ["¿En qué paciente resulta más beneficiosa la terapia por restricción inducida?",["El paciente crónico, más allá de los seis meses","El paciente en fase aguda inmediata","El paciente sin ninguna motricidad residual"],["Exacto: en él supera a la rehabilitación tradicional.","Falso: esa fase no se presta a ello.","Falso: se exigen criterios motores mínimos."]],
  "561": ["¿Qué extensión de muñeca se exige para una terapia por restricción inducida?",["Veinte grados","Diez grados","Cuarenta y cinco grados"],["Exacto: se requieren además diez grados de extensión de las articulaciones de los dedos.","Falso: esa cifra atañe a los dedos y al pulgar.","Falso: esa exigencia sería demasiado restrictiva."]],
  "562": ["¿Qué extensión de las articulaciones de los dedos se exige en terapia por restricción inducida?",["Al menos diez grados","Al menos veinte grados","Al menos cuarenta grados"],["Exacto: con diez grados de abducción o de extensión del pulgar.","Falso: esa cifra atañe a la muñeca.","Falso: esa exigencia es excesiva."]],
  "563": ["¿Qué nivel de espasticidad permite la terapia por restricción inducida?",["Como máximo dos en la escala de Ashworth","Como máximo cuatro en la escala de Ashworth","Cualquier valor, la espasticidad no importa"],["Exacto: el dolor debe mantenerse igualmente por debajo de cuatro sobre diez.","Falso: ese nivel es demasiado elevado.","Falso: constituye un criterio explícito."]],
  "564": ["¿Qué prueba funcional valida la inclusión en terapia por restricción inducida?",["Levantar un objeto plano de una mesa y soltarlo","Transportar una carga de cinco kilogramos","Escribir a mano una frase legible"],["Exacto: ese gesto acredita una prensión y una relajación mínimas.","Falso: no existe ninguna exigencia de fuerza de ese tipo.","Falso: no es la prueba que se considera."]],
  "565": ["¿Sobre qué miembro actúa más el entrenamiento por tareas repetitivas?",["El miembro inferior","El miembro superior","Ambos de forma estrictamente igual"],["Exacto: las pruebas son en él más nítidas que para el miembro superior.","Falso: los efectos son en él más limitados.","Falso: la diferencia está documentada."]],
  "566": ["¿Qué ganancia media de distancia obtiene el entrenamiento por tareas repetitivas?",["Unos treinta y cinco metros en seis minutos","Unos doscientos metros en seis minutos","Ninguna ganancia medible en la marcha"],["Exacto: las pruebas se califican de moderadas.","Falso: esa ganancia está muy sobreestimada.","Falso: sí se demuestra un beneficio."]],
  "567": ["¿Cuánto tiempo se mantienen los efectos del entrenamiento por tareas repetitivas?",["Hasta seis meses después de la terapia","Hasta cinco años después de la terapia","Solamente unos pocos días"],["Exacto: entre los seis meses y el año, el mantenimiento ya no está demostrado.","Falso: ningún dato respalda semejante duración.","Falso: el mantenimiento es bastante más prolongado."]],
  "568": ["¿En cuánto aumentan las repeticiones las instrucciones centradas en los objetivos?",["Del sesenta y dos al ciento veintiocho por ciento","Del cinco al diez por ciento","No cambian en nada el número de repeticiones"],["Exacto: las más eficaces animan a la velocidad y al rendimiento personal.","Falso: la ganancia es bastante superior.","Falso: el efecto es, al contrario, considerable."]],
  "569": ["¿Qué distingue la realidad virtual de la realidad aumentada?",["La virtual aísla del mundo real","La virtual superpone elementos a lo real","La realidad virtual hace interactuar lo digital y lo físico"],["Exacto: la realidad aumentada superpone elementos sin interacción directa.","Falso: esa descripción es la de la realidad aumentada.","Falso: esa descripción es la de la realidad mixta."]],
  "570": ["¿Qué caracteriza a la realidad mixta?",["Lo digital interactúa con lo físico","El usuario queda totalmente aislado de lo real","Los elementos digitales están simplemente superpuestos"],["Exacto: esa interacción se produce en tiempo real.","Falso: esa descripción es la de la realidad virtual.","Falso: esa descripción es la de la realidad aumentada."]],
  "571": ["¿Qué es un dispositivo semiinmersivo?",["Pantallas grandes o simuladores","Un casco con sonido envolvente","Una pantalla de ordenador tradicional"],["Exacto: el inmersivo supone un casco y un sonido envolvente.","Falso: ese material define el inmersivo.","Falso: ese material define el no inmersivo."]],
  "572": ["¿Qué es un enfoque descendente en rehabilitación?",["Partir de los procesos cognitivos superiores","Partir de los reflejos medulares elementales","Partir del miembro afectado hacia el tronco"],["Exacto: se influye así en las funciones más elementales.","Falso: esa lógica sería ascendente.","Falso: esa descripción es anatómica, no cognitiva."]],
  "573": ["¿Cuál es el lugar de la realidad virtual en la rehabilitación?",["Un complemento eficaz, no un sustituto","Un sustituto validado de la terapia clásica","Una herramienta sin efecto demostrado"],["Exacto: las pruebas no son lo bastante sólidas para sustituir a la terapia convencional.","Falso: las pruebas no lo respaldan.","Falso: se describe un efecto moderado significativo."]],
  "574": ["¿Qué tipo de realidad virtual da los mejores resultados sobre la motricidad global?",["La realidad virtual totalmente inmersiva","La realidad virtual no inmersiva","La realidad aumentada superpuesta"],["Exacto: los enfoques no inmersivos convienen mejor a la destreza fina.","Falso: conviene mejor a la destreza fina.","Falso: no es la modalidad comparada aquí."]],
  "575": ["¿Qué tipo de enfoque conviene mejor a la destreza fina?",["Los enfoques no inmersivos","Los enfoques totalmente inmersivos","Únicamente los enfoques semiinmersivos"],["Exacto: la inmersión total sirve más a la motricidad global.","Falso: sirven más bien a la motricidad global.","Falso: no es la comparación referida."]],
  "576": ["¿Qué duración de intervención optimiza los resultados en realidad virtual?",["Más de seis semanas","Menos de dos semanas","Más de dos años"],["Exacto: empezar en los seis meses siguientes al accidente cerebrovascular optimiza aún más los resultados.","Falso: esa duración es insuficiente.","Falso: esa duración supera lo recomendado."]],
  "577": ["¿Qué frecuencia mínima hace eficaz la realidad virtual?",["Al menos tres días por semana","Una vez al mes","Una vez por semana"],["Exacto: con sesiones de al menos treinta a sesenta minutos.","Falso: esa frecuencia es muy insuficiente.","Falso: la frecuencia que se considera es más elevada."]],
  "578": ["¿Qué induce realmente el cambio neuroplástico?",["El diseño y la personalización","Únicamente la sofisticación del material empleado","Únicamente el número de horas pasadas ante la pantalla"],["Exacto: la tecnología sola no garantiza ningún cambio.","Falso: es precisamente la ilusión que hay que evitar.","Falso: la cantidad no basta."]],
  "579": ["¿Qué sistemas de realidad virtual son los más eficaces?",["Los diseñados para la rehabilitación","Los creados con fines recreativos","Ambos dan los mismos resultados"],["Exacto: superan a los sistemas creados con fines recreativos.","Falso: son menos eficaces.","Falso: la diferencia está documentada."]],
  "580": ["¿Qué criterio excluye a un paciente de la realidad virtual?",["Una epilepsia fotosensible","Una espasticidad puntuada con uno en Ashworth","Una edad superior a los sesenta y cinco años"],["Exacto: la heminegligencia, los trastornos perceptivos graves y la espasticidad elevada lo excluyen igualmente.","Falso: el umbral de exclusión se sitúa por encima de dos.","Falso: la edad no es un criterio de exclusión."]],
  "581": ["¿Qué sistema activa la terapia por observación de acciones?",["El sistema de las neuronas espejo","El sistema vestibular periférico","El sistema de las columnas dorsales"],["Exacto: observar a otra persona activa con más intensidad que observarse a uno mismo.","Falso: ese sistema no es el que se activa.","Falso: esa vía es puramente sensitiva."]],
  "582": ["¿Qué observación produce la activación más intensa?",["La observación de otra persona","La observación de su propio movimiento","La observación de un dibujo animado"],["Exacto: en caso de autoobservación, el modelo no debe ser patológico.","Falso: su activación es menor.","Falso: no es la comparación establecida."]],
  "583": ["¿Sobre qué función es más eficaz la terapia por observación de acciones?",["La marcha y su velocidad","La destreza fina de los dedos","El equilibrio del tronco sentado"],["Exacto: mejora en el miembro superior si se aplica a las actividades diarias.","Falso: es ahí donde resulta menos eficaz.","Falso: no es la función principalmente mejorada."]],
  "584": ["¿En qué fase es más eficaz la terapia por observación de acciones?",["En fase crónica","En fase aguda inmediata","Únicamente en fase subaguda"],["Exacto: es igualmente eficaz en la enfermedad de Parkinson y en la parálisis cerebral.","Falso: su efecto es ahí menor.","Falso: su efecto es máximo más tardíamente."]],
  "585": ["¿Qué beneficio aporta la terapia por observación de acciones al paciente afásico?",["Una mejoría de la memoria verbal","Una recuperación completa del lenguaje","Ningún beneficio cognitivo demostrado"],["Exacto: esa mejoría persiste al menos dos meses.","Falso: no se describe ninguna recuperación total.","Falso: hay un beneficio verbal documentado."]],
  "586": ["¿En quién puede la observación de acciones superar a la imaginería motora?",["En los niños y en las personas mayores","En los adultos jóvenes deportistas","En los pacientes sin déficit motor"],["Exacto: a menudo les cuesta generar imágenes motoras.","Falso: estos generan con facilidad imágenes motoras.","Falso: no es la población buscada."]],
  "587": ["¿Qué es la estimulación basal?",["Un concepto global y transversal","Una técnica instrumental bien codificada","Una terapia reservada a las sesiones supervisadas"],["Exacto: no es ni una técnica ni una terapia, y se aplica en cualquier momento.","Falso: precisamente no es una técnica.","Falso: se aplica en cualquier entorno."]],
  "588": ["¿Qué sentidos busca activar la estimulación basal?",["Tacto, movimiento, equilibrio y cuerpo","La visión y la audición de forma prioritaria","Exclusivamente el gusto y el olfato"],["Exacto: se dirige a las personas muy gravemente afectadas.","Falso: no son los sentidos fundamentales buscados.","Falso: esos sentidos no constituyen su diana principal."]],
  "589": ["¿Qué límite presenta la estimulación basal?",["Pocas pruebas y una confusión frecuente con lo multisensorial","Un coste material prohibitivo","Contraindicaciones muy numerosas"],["Exacto: esa confusión dificulta la evaluación de su eficacia.","Falso: no exige material costoso.","Falso: no es el límite que se señala."]],
  "590": ["¿En qué principio se asienta el concepto Bobath?",["La lesión afecta a la persona en su conjunto","La lesión solo afecta a un segmento aislado","El movimiento resulta de un proceso cognitivo"],["Exacto: el enfoque es inclusivo, individualizado y centrado en los problemas.","Falso: es precisamente esa visión la que el enfoque supera.","Falso: ese principio es el del ejercicio terapéutico cognoscitivo."]],
  "591": ["¿Qué busca la intervención según el concepto Bobath?",["Optimizar el control postural y el movimiento selectivo","Reforzar la fuerza máxima de los miembros","Activar patrones reflejos globales"],["Exacto: constituyen la base de la función.","Falso: la fuerza bruta no es el objetivo primero.","Falso: esa lógica es la de la locomoción refleja."]],
  "592": ["¿Qué es la facilitación en el concepto Bobath?",["La interacción terapeuta-paciente","Hacer el movimiento en lugar del paciente","Únicamente la consigna verbal dada al paciente"],["Exacto: el manejo, el entorno, la elección de la tarea y las ayudas verbales forman parte de ella.","Falso: lo que se busca es, al contrario, la autoiniciación.","Falso: no se reduce a las consignas."]],
  "593": ["¿Qué busca favorecer la facilitación?",["La autoiniciación y la autoterminación","La dependencia de la guía del terapeuta","La ejecución pasiva del gesto por el terapeuta"],["Exacto: crea las condiciones de una experiencia todavía imposible en solitario.","Falso: lo que se busca es lo contrario.","Falso: la pasividad se opone al principio."]],
  "594": ["¿Qué es la locomoción refleja según Vojta?",["Un método que activa patrones motores normales","Un método que suprime los reflejos arcaicos","Un método basado en la percepción de los problemas"],["Exacto: se dirige a los trastornos neurológicos y a los déficits posturales.","Falso: su objetivo es activar, no suprimir.","Falso: ese principio es el del ejercicio terapéutico cognoscitivo."]],
  "595": ["¿Por qué se desencadena la locomoción refleja?",["Por estímulos llamados zonas","Por consignas verbales del terapeuta","Por la observación de un modelo en movimiento"],["Exacto: parte siempre de posiciones corporales definidas.","Falso: el desencadenamiento es puramente somestésico.","Falso: ese principio es el de la observación de acciones."]],
  "596": ["¿Qué se puede decir del contenido del movimiento activado por la locomoción refleja?",["Es siempre el mismo","Varía en cada sesión","Depende de la voluntad del paciente"],["Exacto: la activación atañe a un patrón global de postura y de movimiento.","Falso: la constancia es una característica del método.","Falso: la activación es precisamente involuntaria."]],
  "597": ["¿Cuáles son los tres componentes de la locomoción refleja?",["Control postural, enderezamiento y movimiento fásico","Percepción, hipótesis y verificación","Adaptación, rotación y equilibrio"],["Exacto: el movimiento fásico corresponde al paso de los miembros libres.","Falso: esa secuencia corresponde al ejercicio terapéutico cognoscitivo.","Falso: esas nociones corresponden al programa acuático."]],
  "598": ["¿Cómo concibe el movimiento el ejercicio terapéutico cognoscitivo?",["Como el resultado de un proceso cognitivo","Como la consecuencia de un patrón reflejo","Como un fin en sí mismo que hay que automatizar"],["Exacto: el paciente no aprende a moverse moviéndose, sino percibiendo.","Falso: esa concepción corresponde a la locomoción refleja.","Falso: en él el movimiento es un medio para resolver problemas."]],
  "599": ["¿Cuál es la secuencia de adquisición según el ejercicio terapéutico cognoscitivo?",["Problema cognitivo, hipótesis perceptiva, verificación","Movimiento, repetición, automatización","Estímulo, respuesta, refuerzo"],["Exacto: el movimiento se realiza con los ojos cerrados, entre la hipótesis y la verificación.","Falso: esa secuencia es la del aprendizaje motor clásico.","Falso: esa secuencia corresponde al condicionamiento."]],
  "600": ["¿En qué condición ejecuta el paciente el movimiento en el ejercicio cognoscitivo?",["Una herramienta que cambia de forma","Una herramienta que no cambia de forma","Ante un espejo terapéutico"],["Exacto: la visión sirve para presentar el problema y después el paciente formula su hipótesis.","Falso: la visión se suprime voluntariamente durante la ejecución.","Falso: ese dispositivo corresponde a otro enfoque."]],
  "601": ["¿Por qué se considera activo el primer grado del ejercicio cognoscitivo?",["Por su componente atencional","Porque el paciente contrae sus músculos","Porque precede al segundo grado"],["Exacto: aunque el movimiento sea pasivo, la atención del paciente está comprometida.","Falso: el movimiento es pasivo por definición.","Falso: el orden no justifica ese calificativo."]],
  "602": ["¿Qué trabaja el segundo grado del ejercicio terapéutico cognoscitivo?",["El control de las contracciones, en movimiento asistido","La adaptación del tono, en movimiento pasivo","La automatización, en movimiento activo libre"],["Exacto: el tercer grado se refiere al movimiento activo sin ayuda.","Falso: ese objetivo es el del primer grado.","Falso: ese objetivo es el del tercer grado."]],
  "603": ["¿Qué es una herramienta móvil en el ejercicio terapéutico cognoscitivo?",["Una herramienta que cambia de forma","Una herramienta que no cambia de forma","Una herramienta que el paciente desplaza él mismo"],["Exacto: solicita la presión, el peso y la resistencia.","Falso: esa descripción es la de la herramienta fija.","Falso: el criterio se refiere a la deformabilidad."]],
  "604": ["¿Cómo es la densidad del cuerpo humano respecto a la del agua?",["Ligeramente inferior","Claramente superior","Exactamente idéntica"],["Exacto: es lo que permite la flotación.","Falso: el cuerpo se hundiría entonces sistemáticamente.","Falso: la ligera diferencia es determinante."]],
  "605": ["¿Qué efecto circulatorio produce la presión hidrostática?",["La viscosidad, con arrastre y turbulencia","La flotabilidad, que aligera el cuerpo","No tiene ningún efecto circulatorio"],["Exacto: aumenta la presión auricular derecha y asciende el diafragma.","Falso: el desplazamiento se produce hacia el centro.","Falso: su efecto es, al contrario, importante."]],
  "606": ["¿En cuánto reduce el peso la inmersión hasta la apófisis xifoides?",["En un sesenta por ciento o más","En un setenta y cinco por ciento o más","En un veinte por ciento aproximadamente"],["Exacto: en la séptima vértebra cervical, la reducción alcanza el setenta y cinco por ciento o más.","Falso: ese nivel corresponde a una inmersión más alta.","Falso: esa reducción está muy subestimada."]],
  "607": ["¿En cuánto reduce el peso la inmersión hasta la séptima cervical?",["En un setenta y cinco por ciento o más","En un sesenta por ciento o más","En un treinta por ciento aproximadamente"],["Exacto: en la apófisis xifoides, la reducción es del sesenta por ciento.","Falso: ese nivel corresponde a la apófisis xifoides.","Falso: esa reducción está muy subestimada."]],
  "608": ["¿Qué propiedad del agua permite el entrenamiento de la fuerza?",["La viscosidad, mediante arrastre y turbulencia","La flotabilidad, que aligera el cuerpo","Únicamente la presión hidrostática"],["Exacto: la resistencia aumenta con la velocidad del movimiento.","Falso: reduce, al contrario, la carga.","Falso: actúa sobre todo en la circulación."]],
  "609": ["¿A qué temperatura se realizan las sesiones terapéuticas en piscina?",["Entre treinta y tres y treinta y cinco grados y medio","Entre veintisiete y veintinueve grados","Entre veinte y veintidós grados"],["Exacto: las piscinas públicas se mantienen entre veintisiete y veintinueve grados.","Falso: ese intervalo es el de las piscinas públicas.","Falso: esa temperatura resultaría mucho demasiado fría."]],
  "610": ["¿Cuál es el primer punto del programa acuático en diez etapas?",["La adaptación mental","La relajación","La rotación transversal"],["Exacto: la relajación viene después y luego las rotaciones.","Falso: constituye el segundo punto.","Falso: constituye el tercer punto."]],
  "611": ["¿Cuál es el último punto del programa acuático en diez etapas?",["La progresión simple y la brazada","El equilibrio como inmovilidad","Afrontar las turbulencias"],["Exacto: desemboca en la autonomía en el agua, incluso en la natación independiente.","Falso: constituye el octavo punto.","Falso: constituye el noveno punto."]],
  "612": ["¿Cuál es el objetivo del programa acuático en diez etapas?",["La autonomía del paciente en el agua","El rendimiento en natación deportiva","Únicamente el fortalecimiento muscular"],["Exacto: la natación independiente es su posible culminación.","Falso: el rendimiento no es el objetivo.","Falso: el objetivo es mucho más amplio."]],
  "613": ["¿Qué beneficio aporta el programa acuático al margen de la motricidad?",["Confianza, comunicación y participación","Únicamente la mejoría de la fuerza máxima","Ningún beneficio más allá del medio acuático"],["Exacto: la función respiratoria y la motricidad global mejoran igualmente.","Falso: los beneficios van mucho más allá de la fuerza.","Falso: la participación social resulta mejorada."]],
  "614": ["¿Qué postula la cognición corporeizada?",["Los procesos cognitivos dependen del cuerpo que los sostiene","Los procesos cognitivos son independientes del cuerpo","El cuerpo solo interviene después de la decisión cognitiva"],["Exacto: las experiencias corporales dan forma a las representaciones cognitivas.","Falso: es precisamente la concepción que este modelo rechaza.","Falso: la interacción es constante y recíproca."]],
  "615": ["¿Qué redes sostienen la atención?",["Prefrontal, parietal y tálamo","Hipocampo y corteza temporal","Las áreas de Broca, de Wernicke y el fascículo arqueado"],["Exacto: la memoria se asienta más bien en el hipocampo y en las redes frontotemporales.","Falso: esas estructuras sostienen la memoria.","Falso: esas áreas sostienen el lenguaje."]],
  "616": ["¿Qué estructuras sostienen el lenguaje?",["Broca, Wernicke y el fascículo arqueado","El hipocampo y la corteza temporal medial","Las áreas sensoriales primarias"],["Exacto: las funciones ejecutivas corresponden a la corteza prefrontal.","Falso: esas estructuras sostienen la memoria.","Falso: estas sostienen la percepción."]],
  "617": ["¿De qué depende la velocidad de procesamiento de la información?",["De la mielinización y de la eficacia sináptica","Únicamente del tamaño de la corteza prefrontal dominante","Del número de áreas sensoriales efectivamente reclutadas"],["Exacto: no depende de un área única.","Falso: no se describe ninguna relación de ese tipo.","Falso: no es el determinante que se considera."]],
  "618": ["¿Cuándo comienza un trastorno del neurodesarrollo?",["En periodo prenatal o perinatal","En la edad adulta o en la vejez avanzada","Indistintamente a cualquier edad de la vida, sin periodo crítico"],["Exacto: un trastorno neurocognitivo adquirido comienza en la edad adulta o en la vejez.","Falso: esa cronología es la del trastorno adquirido.","Falso: el periodo de inicio es un criterio determinante."]],
  "619": ["¿Qué caracteriza a un trastorno del neurodesarrollo?",["Un déficit de funciones nunca adquiridas","Una pérdida de funciones previamente adquiridas","Una fluctuación de las capacidades"],["Exacto: el trastorno adquirido corresponde a una pérdida de funciones previamente adquiridas.","Falso: esa definición es la del trastorno adquirido.","Falso: su evolución es más bien estable o lentamente progresiva."]],
  "620": ["¿Qué neurobiología subyace a un trastorno del neurodesarrollo?",["Migración, sinaptogénesis y mielinización","Una atrofia con pérdida sináptica y pérdida neuronal","Una desmielinización inflamatoria diseminada en placas"],["Exacto: a ello se asocia con frecuencia una disfunción frontoestriatal.","Falso: esa neurobiología es la del trastorno adquirido.","Falso: ese mecanismo corresponde a una patología concreta."]],
  "621": ["¿Cómo evoluciona un trastorno del neurodesarrollo?",["De forma crónica, estable o lenta","De forma rápidamente degenerativa","Mediante una curación espontánea hacia el final de la adolescencia"],["Exacto: sigue siendo mejorable mediante una intervención precoz.","Falso: esa evolución es la de algunos trastornos adquiridos.","Falso: no se describe ninguna curación espontánea."]],
  "622": ["¿Qué neurobiología subyace a un trastorno neurocognitivo adquirido?",["Atrofia, pérdida neuronal y depleción","Anomalías de migración y de sinaptogénesis corticales","Una hiperplasia compensadora de las redes corticales"],["Exacto: el trastorno del neurodesarrollo corresponde más bien a anomalías de maduración.","Falso: esa neurobiología es la del trastorno del neurodesarrollo.","Falso: no se describe ninguna hiperplasia."]],
  "623": ["¿Qué herramientas detectan un trastorno del neurodesarrollo?",["Los cuestionarios de la primera infancia","Las pruebas cognitivas del adulto","La prueba del reloj y la evaluación cognitiva global"],["Exacto: las pruebas cognitivas breves del adulto sirven para el trastorno adquirido.","Falso: estas detectan el trastorno adquirido.","Falso: esas herramientas se dirigen al adulto y a la persona mayor."]],
  "624": ["¿Qué perfil neurocognitivo acompaña a un accidente cerebrovascular?",["Afasia, heminegligencia y desorientación","Cambios de personalidad y desinhibición","Alucinaciones con fluctuaciones marcadas"],["Exacto: esos trastornos se añaden a la hemiparesia, la espasticidad y la ataxia.","Falso: ese perfil sugiere un traumatismo craneal.","Falso: ese perfil sugiere una demencia por cuerpos de Lewy."]],
  "625": ["¿Qué perfil neurocognitivo acompaña a un traumatismo craneal?",["Déficits ejecutivos y cambios de personalidad","Pérdida de memoria reciente y trastornos visuoespaciales","Marcha magnética y fluctuaciones cognitivas"],["Exacto: problemas de inhibición y de atención los acompañan.","Falso: ese perfil sugiere una enfermedad de Alzheimer.","Falso: ese perfil sugiere una demencia vascular."]],
  "626": ["¿Qué perfil neurocognitivo acompaña a la enfermedad de Parkinson?",["Funciones ejecutivas, planificación y lentitud","Alucinaciones y fluctuaciones cognitivas nítidas","Heminegligencia y desorientación espacial"],["Exacto: la lentitud de procesamiento es ahí característica.","Falso: ese perfil sugiere una demencia por cuerpos de Lewy.","Falso: ese perfil sugiere un accidente cerebrovascular."]],
  "627": ["¿Qué marcha caracteriza a la demencia vascular?",["Una marcha magnética","Una marcha a pasos cortos festinante","Una marcha en estepaje bilateral"],["Exacto: fluctuaciones cognitivas y déficits ejecutivos la acompañan.","Falso: esa marcha sugiere un síndrome parkinsoniano.","Falso: esa marcha sugiere una neuropatía."]],
  "628": ["¿Qué signo distingue a la demencia por cuerpos de Lewy?",["Alucinaciones y fluctuaciones cognitivas","Una pérdida aislada de la memoria reciente verbal","Una heminegligencia izquierda"],["Exacto: con frecuencia se le asocia un parkinsonismo.","Falso: ese signo sugiere una enfermedad de Alzheimer.","Falso: ese signo sugiere un accidente cerebrovascular derecho."]],
  "629": ["¿Qué trastorno cognitivo domina en la esclerosis múltiple?",["La lentitud y los trastornos ejecutivos","Las alucinaciones visuales recurrentes nocturnas","La desorientación espacial"],["Exacto: puede asociarse un temblor intencional.","Falso: ese signo sugiere una demencia por cuerpos de Lewy.","Falso: ese signo sugiere un accidente cerebrovascular."]],
  "630": ["¿Qué busca el enfoque de restablecimiento?",["Recuperar la función, priorizando la calidad","Recuperar la función, priorizando la cantidad","Sustituir la función por un dispositivo"],["Exacto: el enfoque compensatorio privilegia, al contrario, la cantidad.","Falso: esa prioridad es la del enfoque compensatorio.","Falso: esa lógica es la del enfoque sustitutivo."]],
  "631": ["¿Qué busca el enfoque compensatorio?",["Recuperar la función, priorizando la cantidad","Recuperar la función normalizando el patrón","Ralentizar el deterioro funcional"],["Exacto: permite ciertas compensaciones en beneficio de la autonomía.","Falso: esa prioridad es la del restablecimiento.","Falso: ese objetivo es el del enfoque de contención."]],
  "632": ["¿Qué busca el enfoque sustitutivo?",["Sustituir la función por un dispositivo","Preservar lo adquirido y evitar recaídas posteriores","Normalizar el patrón de movimiento deficitario"],["Exacto: otras partes del cuerpo pueden igualmente tomar el relevo.","Falso: ese objetivo es el del enfoque de mantenimiento.","Falso: ese objetivo es el del restablecimiento."]],
  "633": ["¿Qué busca el enfoque de contención?",["Ralentizar el deterioro funcional","Recuperar en calidad la función perdida por el paciente","Asegurar el confort terminal"],["Exacto: busca además minimizar el sufrimiento.","Falso: ese objetivo es el del restablecimiento.","Falso: ese objetivo es el del enfoque paliativo."]],
  "634": ["¿Cómo se articulan los seis enfoques terapéuticos?",["Se combinan y se pasa de uno a otro","Se excluyen estrictamente unos a otros","Se suceden siempre en un orden fijo"],["Exacto: un mismo plan puede combinar varios enfoques para funciones diferentes.","Falso: su combinación es, al contrario, la regla.","Falso: la evolución del paciente dicta las transiciones."]],
  "635": ["¿Cómo se puntúa una escala de consecución de objetivos?",["De menos dos a más dos","De cero a diez, con cinco como esperado","De uno a siete, con cuatro como esperado"],["Exacto: más uno y más dos superan lo esperado; menos uno y menos dos se quedan por debajo.","Falso: esa graduación no es la que se considera.","Falso: esa graduación es la de otra escala."]],
  "636": ["¿Qué exige una tarea de doble tarea bien diseñada?",["Que comprometa realmente la atención cognitiva","Que sea puramente motora y repetitiva","Que se realice en completo silencio"],["Exacto: debe ser prioritaria con respecto a una tarea automatizable.","Falso: el componente cognitivo es indispensable.","Falso: no es el criterio que se considera."]],
  "637": ["¿Qué pasa a ser el componente más costoso en un paciente con marcha corticalizada?",["La marcha misma","La tarea cognitiva asociada","Ambas en partes estrictamente iguales"],["Exacto: ya no está automatizada y monopoliza la atención.","Falso: es la marcha la que pasa a ser prioritaria en atención.","Falso: el desequilibrio es nítido."]],
  "638": ["¿En qué condiciones emplear la doble tarea?",["Solo si el rendimiento puede ser positivo","Sistemáticamente, desde la primera sesión","Únicamente en el paciente sin déficit cognitivo"],["Exacto: un rendimiento negativo acrecienta la frustración y genera bloqueos.","Falso: el fracaso repetido es contraproducente.","Falso: no es el criterio decisivo."]],
  "639": ["¿Qué memoria suele estar mejor preservada?",["La memoria motora implícita","La memoria episódica reciente","La memoria semántica"],["Exacto: escaleras, pedaleo y transferencias pueden automatizarse sin recuerdo consciente.","Falso: a menudo es la más afectada.","Falso: no es la mejor preservada en este contexto."]],
  "640": ["¿Qué es una apraxia?",["La pérdida de una capacidad de acción ya adquirida","La incapacidad de adquirir los automatismos","Un déficit motor primario del miembro"],["Exacto: sobreviene en el adulto, sin un déficit motor o sensorial que lo explique.","Falso: esa descripción es la de la dispraxia del niño.","Falso: la ausencia de semejante déficit forma parte de la definición."]],
  "641": ["¿Qué es una dispraxia?",["La incapacidad de adquirir los automatismos","La pérdida de una capacidad adquirida","Una parálisis parcial de origen central o medular"],["Exacto: atañe al niño a lo largo de su desarrollo.","Falso: esa descripción es la de la apraxia.","Falso: no se trata de un déficit motor."]],
  "642": ["¿Cuándo se trata una estereotipia de autoestimulación?",["Solo si resulta perjudicial","Sistemáticamente, en cuanto se detecta en sesión","Nunca, sea cual sea la situación"],["Exacto: de lo contrario cumple funciones positivas para la persona.","Falso: a menudo tiene una utilidad funcional.","Falso: se trata cuando resulta perjudicial."]],
  "643": ["¿Qué estrategia emplear ante una estereotipia molesta?",["La redirección positiva","El castigo de la conducta","La indiferencia ante la conducta"],["Exacto: el castigo queda explícitamente excluido.","Falso: ese enfoque está proscrito.","Falso: se prefiere la redirección a la indiferencia."]],
  "644": ["¿Cuáles son los cuatro tipos de atención que hay que trabajar?",["Sostenida, alternante, selectiva y dividida","Visual, auditiva, táctil y vestibular","Inmediata, reciente y antigua"],["Exacto: cada una exige un trabajo específico.","Falso: esa división es sensorial y no atencional.","Falso: esa división atañe a la memoria."]],
  "645": ["¿Qué técnica se propone ante una heminegligencia?",["La estimulación optocinética","La confrontación directa del paciente con su déficit","La inmovilización prolongada del lado negligido"],["Exacto: la terapia espejo, las actividades bimanuales y los entornos virtuales la complementan.","Falso: ese enfoque es ineficaz y se vive mal.","Falso: esa conducta agravaría la negligencia."]],
  "646": ["¿Cómo reaccionar ante un delirio o una alucinación?",["Validar la emoción y redirigir la atención","Confrontar directamente al paciente con la realidad","Ignorar enteramente el discurso del paciente"],["Exacto: nunca hay que confrontar directamente el contenido del delirio.","Falso: esa confrontación está explícitamente proscrita.","Falso: la emoción debe, al contrario, reconocerse."]],
  "647": ["¿Qué precaución hay que tomar con un paciente confuso?",["Anunciar verbalmente todo contacto físico","Tocar al paciente sin avisar para sorprenderlo","Limitar al máximo las referencias visuales"],["Exacto: relojes, calendarios y fotografías refuerzan además la orientación.","Falso: esa conducta genera ansiedad y agitación.","Falso: las referencias son, al contrario, útiles."]],
  "648": ["¿Qué estrategia conviene a un déficit de inhibición?",["Tareas con un inicio y un final claros","Tareas abiertas, sin ningún límite de tiempo","Consignas deliberadamente ambiguas y cambiantes"],["Exacto: las consignas de tipo acción o inhibición estructuran la respuesta.","Falso: la ausencia de marco agrava el trastorno.","Falso: la ambigüedad es contraproducente."]],
  "649": ["¿Qué estrategia adoptar ante una negativa ligada al miedo?",["Proponer un logro sencillo","Proponer una tarea más exigente","Aplazar el abordaje"],["Exacto: el dolor exige alternativas; la desmotivación, un refuerzo positivo.","Falso: esa conducta agravaría la aprensión.","Falso: la evitación refuerza el miedo."]],
  "650": ["¿Cómo actuar durante un episodio de agresividad?",["Mantener la calma y desescalar","Levantar la voz e imponer un marco","Aumentar las exigencias cognitivas"],["Exacto: hay que evitar además las exigencias cognitivas elevadas.","Falso: esa conducta agrava la escalada.","Falso: la carga cognitiva debe, al contrario, bajar."]],
  "651": ["¿Qué caracteriza a la estimulación multisensorial?",["Receptiva y pasiva, busca el bienestar sensorial","Activa y terapéutica, dirigida por un terapeuta ocupacional","Relacional, busca la percepción corporal"],["Exacto: puede proponerse fuera de un marco estrictamente terapéutico.","Falso: esa descripción es la de la integración sensorial.","Falso: esa descripción es la de la estimulación basal."]],
  "652": ["¿Qué caracteriza a la integración sensorial?",["Activa y terapéutica, dirigida al proceso","Pasiva y receptiva, busca el bienestar sensorial","Experiencial, busca la competencia motora del paciente"],["Exacto: la conduce un terapeuta ocupacional.","Falso: esa descripción es la de la estimulación multisensorial.","Falso: esa descripción es la del enfoque cinestésico."]],
  "653": ["¿Qué se puede decir de los enfoques sensoriales complementarios?",["Preparan al paciente para otras intervenciones","Constituyen terapias de pleno derecho","Sustituyen a la rehabilitación motora"],["Exacto: su papel es preparatorio más que terapéutico.","Falso: es precisamente lo que no son.","Falso: no la sustituyen."]],
  "654": ["¿Qué comprende el complejo estabilizador del tronco?",["Diafragmas, lumbares y abdominales","Únicamente los músculos abdominales superficiales y oblicuos","El diafragma torácico tomado de forma aislada"],["Exacto: esos cuatro conjuntos forman un recinto funcional.","Falso: esa reducción olvida lo esencial del complejo.","Falso: solo es uno de los cuatro elementos."]],
  "655": ["¿Cuál es una de las tres funciones del complejo estabilizador del tronco?",["Regular la presión intraabdominal","Asegurar la digestión de los alimentos","Producir las hormonas del estrés"],["Exacto: estabiliza además el complejo lumbopélvico y transmite las fuerzas.","Falso: esa función no es mecánica.","Falso: esa función es endocrina."]],
  "656": ["¿Qué es la presión intraabdominal?",["La presión confinada en la cavidad abdominal","La presión que reina en la caja torácica","La presión ejercida únicamente sobre el suelo pélvico"],["Exacto: constituye el eje mecánico del tronco.","Falso: esa presión es intratorácica.","Falso: atañe a toda la cavidad abdominal."]],
  "657": ["¿Qué influye más en la presión intraabdominal?",["El diafragma y la pared abdominal","Los músculos de los miembros inferiores","La posición de la cabeza y del cuello"],["Exacto: en el paciente neurológico, su gestión suele estar alterada.","Falso: no intervienen directamente.","Falso: no es el determinante principal."]],
  "658": ["¿Qué produce una postura cifótica en el espacio abdominal?",["Lo reduce y desplaza el centro","Lo aumenta y recentra la masa visceral","No modifica el espacio abdominal disponible"],["Exacto: de ello se siguen una compresión visceral y una presión crónicamente elevada.","Falso: el hundimiento del tronco reduce ese espacio.","Falso: la modificación es, al contrario, determinante."]],
  "659": ["¿Hacia dónde se ejerce el vector de fuerza en caso de presión intraabdominal elevada?",["Hacia abajo, sobre el diafragma pélvico","Hacia arriba, sobre el diafragma torácico","Lateralmente, hacia las paredes"],["Exacto: de ello resulta una sobrecarga constante del suelo pélvico.","Falso: el vector se dirige hacia abajo.","Falso: no es la dirección descrita."]],
  "660": ["¿Qué provoca la sobrecarga crónica del suelo pélvico?",["Una incontinencia al menor esfuerzo","Una retención urinaria completa","Una hipertonía duradera y protectora"],["Exacto: su capacidad contráctil acaba agotándose.","Falso: lo que se describe es la incontinencia.","Falso: el agotamiento contráctil es, al contrario, la regla."]],
  "661": ["¿Qué otra repercusión tiene la postura cifótica?",["Una dificultad del movimiento diafragmático","Una mejoría de la capacidad vital","Una ausencia de efecto sobre la respiración"],["Exacto: la respiración queda comprometida.","Falso: lo que se observa es lo contrario.","Falso: el efecto respiratorio es directo."]],
  "662": ["¿Qué papel desempeña la formación reticular sobre el tronco?",["Controla los músculos de flexión y de extensión","Controla únicamente los músculos de los miembros","No tiene ningún papel motor demostrado"],["Exacto: desempeña además un papel fundamental en el ritmo respiratorio.","Falso: su acción recae precisamente sobre el tronco.","Falso: su papel motor está bien establecido."]],
  "663": ["¿Qué centro contiene la formación reticular?",["El centro organizador de la micción","El centro de la visión binocular","El centro del lenguaje articulado"],["Exacto: regula además el ritmo respiratorio y el tono del tronco.","Falso: esa función corresponde a las vías visuales.","Falso: esa función corresponde a la corteza."]],
  "664": ["¿Qué efecto tiene la activación de los músculos del suelo pélvico sobre la micción?",["La inhibe","La desencadena","No tiene efecto alguno"],["Exacto: esa noción fundamenta varias estrategias de rehabilitación perineal.","Falso: lo que se produce es lo contrario.","Falso: el efecto inhibidor está bien establecido."]],
  "665": ["¿Con qué está correlacionada la activación del diafragma?",["Con el equilibrio estático y dinámico","Únicamente con la capacidad respiratoria máxima","Con la fuerza de los miembros superiores"],["Exacto: el diafragma participa plenamente en la estabilidad postural.","Falso: su papel postural es igual de importante.","Falso: esa correlación no se describe."]],
  "666": ["¿Qué caracteriza a la fase oral de la disfagia neurológica?",["Una propulsión lingual insuficiente","Un retraso nítido del reflejo de deglución faríngeo","Un peristaltismo ineficaz acompañado de reflujo"],["Exacto: corresponde a una afectación cortical o de los nervios craneales de la cara y de la lengua.","Falso: ese signo caracteriza a la fase faríngea.","Falso: ese signo caracteriza a la fase esofágica."]],
  "667": ["¿Qué caracteriza a la fase faríngea de la disfagia?",["Un cierre laríngeo incompleto con aspiración","Una masticación ineficaz y mal coordinada","Una sensación de obstrucción con reflujo"],["Exacto: la elevación del hueso hioides disminuye y el reflejo se retrasa.","Falso: ese signo caracteriza a la fase oral.","Falso: ese signo caracteriza a la fase esofágica."]],
  "668": ["¿Qué afectación subyace a una disfagia de fase faríngea?",["Una afectación del tronco cerebral o de los pares nueve y diez","Una afectación cortical o de los pares cinco, siete y doce","Una disfunción autónoma o del control vagal"],["Exacto: el riesgo de aspiración es ahí particularmente elevado.","Falso: esa afectación corresponde a la fase oral.","Falso: esa afectación corresponde a la fase esofágica."]],
  "669": ["¿Qué caracteriza a la fase esofágica de la disfagia?",["Una alteración del tránsito con reflujo","Una debilidad lingual con mala propulsión","Un defecto de protección laríngea"],["Exacto: corresponde a una disfunción autónoma o del control vagal.","Falso: ese signo caracteriza a la fase oral.","Falso: ese signo caracteriza a la fase faríngea."]],
  "670": ["¿Qué signo clínico sugiere una disfagia?",["Una voz húmeda después de la ingesta","Una voz nasal permanente","Una afonía completa y súbita"],["Exacto: la tos durante la ingesta y los atragantamientos frecuentes la acompañan.","Falso: ese signo sugiere más bien una afectación miasténica.","Falso: no es el signo característico descrito."]],
  "671": ["¿Qué riesgo mayor conlleva una disfagia neurológica?",["La neumonía por aspiración","La úlcera gastroduodenal hemorrágica","La litiasis salival"],["Exacto: la deshidratación y la malnutrición se añaden a ello.","Falso: ese riesgo no es el descrito.","Falso: esa complicación no está relacionada."]],
  "672": ["¿Por qué puede ser silenciosa una aspiración?",["La sensibilidad afectada impide percibir el bolo","El paciente oculta voluntariamente sus atragantamientos","El bolo es demasiado pequeño para ser detectado"],["Exacto: el paciente no detecta los residuos y no activa el reflejo a tiempo.","Falso: el mecanismo es neurológico y no conductual.","Falso: el volumen no es la explicación."]],
  "673": ["¿Cuál es el peligro de una aspiración silenciosa?",["Un riesgo elevado sin signo visible","Una tos violenta e inmediata después de la ingesta","Un riesgo desdeñable en la práctica corriente"],["Exacto: el peligro existe aun cuando falte la tos.","Falso: es precisamente esa tos la que falta.","Falso: el riesgo es, al contrario, elevado."]],
  "674": ["¿Qué efecto tiene la ausencia de extensión del tronco sobre la deglución?",["Modifica la alineación faríngea","Facilita claramente el paso del bolo alimentario","No tiene efecto medible sobre la deglución"],["Exacto: la resistencia mecánica al bolo aumenta y la sincronización se pierde.","Falso: lo que se produce es lo contrario.","Falso: el efecto postural es, al contrario, determinante."]],
  "675": ["¿Cuál es la primera etapa terapéutica en la disfagia neurológica?",["La corrección de la postura","La modificación de la textura de los alimentos","La colocación de una sonda"],["Exacto: condiciona la alineación, la sincronización y la protección de la vía aérea.","Falso: esa medida viene como complemento.","Falso: esa decisión es una medida de último recurso."]],
  "676": ["¿Qué es una vejiga neurógena?",["Una pérdida de función de origen nervioso","Una infección urinaria recidivante vuelta crónica","Una malformación congénita de la pared vesical"],["Exacto: junto con los trastornos sexuales, pesa mucho en la calidad de vida.","Falso: el origen es neurológico y no infeccioso.","Falso: el origen descrito es adquirido y nervioso."]],
  "677": ["¿Cuál es el lugar de la postura en el abordaje global?",["Influye en la deglución, la continencia y el habla","Solo atañe a la estética del paciente","Solo guarda relación con la marcha"],["Exacto: nunca es, por tanto, un elemento aislado.","Falso: sus consecuencias funcionales son mayores.","Falso: su influencia es mucho más amplia."]],
  "678": ["¿Qué protege una buena gestión de la presión intraabdominal?",["El suelo pélvico y la respiración","Únicamente el raquis lumbar y sus discos","Únicamente la función digestiva y el tránsito"],["Exacto: es el mensaje de síntesis del abordaje global.","Falso: el beneficio es más amplio.","Falso: no es el beneficio descrito."]],
  "679": ["¿Qué regula el sistema reticular más allá de la motricidad?",["El tono de base de la postura","Únicamente la temperatura corporal central del sujeto","Únicamente la secreción de las hormonas digestivas basales"],["Exacto: enlaza así postura, respiración, micción y vigilia.","Falso: esa regulación corresponde al hipotálamo.","Falso: esa función es endocrina."]]
});
